QT_ISI(29,{"5242":["(Maha Suci Allah) Maha Suci dari sifat-sifat semua makhluk (Yang di tangan kekuasaan-Nyalah) yang berada dalam pengaturan-Nyalah (segala kerajaan) segala kekuasaan dan pengaruh (dan Dia Maha Kuasa atas segala sesuatu).",[["تَبَـٰرَكَ","Blessed is"],["ٱلَّذِى","He"],["بِيَدِهِ","in Whose Hand"],["ٱلْمُلْكُ","(is) the Dominion"],["وَهُوَ","and He"],["عَلَىٰ","(is) over"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌ","All-Powerful"]]],"5243":["(Yang menjadikan mati) di dunia (dan hidup) di akhirat, atau yang menjadikan mati dan hidup di dunia. Nuthfah pada asalnya sebagai barang mati, kemudian jadilah ia hidup; pengertian hidup ialah karena ia mempunyai perasaan. Pengertian mati adalah kebalikannya. Pengertian lafal al-khalqu berdasarkan makna yang kedua ini berarti memastikan (supaya Dia menguji kalian) atau mencoba kalian di dalam kehidupan ini (siapa di antara kalian yang lebih baik amalnya) maksudnya yang paling taat kepada Allah. (Dan Dia Maha Perkasa) di dalam melakukan pembalasan terhadap orang yang durhaka kepada-Nya (lagi Maha Pengampun) kepada orang yang bertobat kepada-Nya.",[["ٱلَّذِى","The One Who"],["خَلَقَ","created"],["ٱلْمَوْتَ","death"],["وَٱلْحَيَوٰةَ","and life"],["لِيَبْلُوَكُمْ","that He may test you"],["أَيُّكُمْ","which of you"],["أَحْسَنُ","(is) best"],["عَمَلًۭا ۚ","(in) deed"],["وَهُوَ","And He"],["ٱلْعَزِيزُ","(is) the All-Mighty"],["ٱلْغَفُورُ","the Oft-Forgiving"]]],"5244":["(Yang telah menciptakan tujuh langit berlapis-lapis) yakni sebagian di antaranya berada di atas sebagian yang lain tanpa bersentuhan. (Kamu sekali-kali tidak melihat pada ciptaan Yang Maha Pemurah) pada tujuh langit yang berlapis-lapis itu atau pada makhluk yang lain (sesuatu yang tidak seimbang) yang berbeda dan tidak seimbang. (Maka lihatlah berulang-ulang) artinya lihatlah kembali ke langit (adakah kamu lihat) padanya (keretakan?) maksudnya retak dan berbelah-belah.",[["ٱلَّذِى","The One Who"],["خَلَقَ","created"],["سَبْعَ","seven"],["سَمَـٰوَٰتٍۢ","heavens"],["طِبَاقًۭا ۖ","one above another"],["مَّا","Not"],["تَرَىٰ","you see"],["فِى","in"],["خَلْقِ","(the) creation"],["ٱلرَّحْمَـٰنِ","(of) the Most Gracious"],["مِن","any"],["تَفَـٰوُتٍۢ ۖ","fault"],["فَٱرْجِعِ","So return"],["ٱلْبَصَرَ","the vision"],["هَلْ","can"],["تَرَىٰ","you see"],["مِن","any"],["فُطُورٍۢ","flaw"]]],"5245":["(Kemudian pandanglah sekali lagi) ulangilah kembali penglihatanmu berkali-kali (niscaya akan berbalik) akan kembali (penglihatanmu itu kepadamu dalam keadaan hina) karena tidak menemukan sesuatu cacat (dan penglihatanmu itu pun dalam keadaan payah) yakni tidak melihat sama sekali adanya cacat.",[["ثُمَّ","Then"],["ٱرْجِعِ","return"],["ٱلْبَصَرَ","the vision"],["كَرَّتَيْنِ","twice (again)"],["يَنقَلِبْ","Will return"],["إِلَيْكَ","to you"],["ٱلْبَصَرُ","the vision"],["خَاسِئًۭا","humbled"],["وَهُوَ","while it"],["حَسِيرٌۭ","(is) fatigued"]]],"5246":["(Dan sesungguhnya Kami telah menghiasi langit yang dekat) yang dekat dengan bumi (dengan lampu-lampu) dengan bintang-bintang (dan Kami jadikan bintang-bintang itu alat-alat pelempar) alat untuk melempar dan merajam (setan-setan) bilamana mereka mencuri pembicaraan para malaikat dengan telinga mereka; umpamanya terpisah batu meteor dari bintang-bintang itu yang bentuknya bagaikan segumpal api, lalu mengejar setan dan membunuhnya atau membuatnya cacat. Pengertian ini bukan berarti bahwa bintang-bintang itu lenyap dari tempatnya (dan Kami sediakan bagi mereka siksa neraka yang menyala-nyala) yang besar apinya.",[["وَلَقَدْ","And certainly"],["زَيَّنَّا","We have beautified"],["ٱلسَّمَآءَ","the heaven"],["ٱلدُّنْيَا","nearest"],["بِمَصَـٰبِيحَ","with lamps"],["وَجَعَلْنَـٰهَا","and We have made them"],["رُجُومًۭا","(as) missiles"],["لِّلشَّيَـٰطِينِ ۖ","for the devils"],["وَأَعْتَدْنَا","and We have prepared"],["لَهُمْ","for them"],["عَذَابَ","punishment"],["ٱلسَّعِيرِ","(of) the Blaze"]]],"5247":["(Dan orang-orang yang kafir kepada Rabb mereka, memperoleh azab Jahanam. Dan itulah seburuk-buruk tempat kembali) yakni neraka Jahanam.",[["وَلِلَّذِينَ","And for those who"],["كَفَرُوا۟","disbelieved"],["بِرَبِّهِمْ","in their Lord"],["عَذَابُ","(is the) punishment"],["جَهَنَّمَ ۖ","(of) Hell"],["وَبِئْسَ","and wretched is"],["ٱلْمَصِيرُ","the destination"]]],"5248":["(Apabila mereka dilemparkan ke dalamnya mereka mendengar suara neraka yang mengerikan) yaitu suara yang tidak enak didengar sebagaimana suara keledai (sedang neraka itu menggelegar) yakni mendidih.",[["إِذَآ","When"],["أُلْقُوا۟","they are thrown"],["فِيهَا","therein"],["سَمِعُوا۟","they will hear"],["لَهَا","from it"],["شَهِيقًۭا","an inhaling"],["وَهِىَ","while it"],["تَفُورُ","boils up"]]],"5249":["(Hampir-hampir neraka itu terpecah-pecah) menurut suatu qiraat lafal tamayyazu dibaca tatamayyazu sesuai dengan asalnya, artinya terbelah-belah (lantaran marah) karena murka kepada orang kafir. (Setiap kali dilemparkan ke dalamnya sekumpulan orang) segolongan di antara orang-orang kafir (penjaga-penjaga neraka itu bertanya kepada mereka) dengan pertanyaan yang mengandung nada celaan, (\"Apakah belum pernah datang kepada kalian seorang pemberi peringatan?\") maksudnya seorang rasul yang memberikan peringatan kepada kalian akan azab Allah swt.",[["تَكَادُ","It almost"],["تَمَيَّزُ","bursts"],["مِنَ","from"],["ٱلْغَيْظِ ۖ","rage"],["كُلَّمَآ","Every time"],["أُلْقِىَ","is thrown"],["فِيهَا","therein"],["فَوْجٌۭ","a group"],["سَأَلَهُمْ","(will) ask them"],["خَزَنَتُهَآ","its keepers"],["أَلَمْ","Did not"],["يَأْتِكُمْ","come to you"],["نَذِيرٌۭ","a warner"]]],"5250":["(Mereka menjawab, \"Benar ada, sesungguhnya telah datang kepada kami seorang pemberi peringatan, maka kami mendustakannya dan kami katakan, Allah tidak menurunkan sesuatu pun; tidak lain) tiadalah (kamu hanyalah di dalam kesesatan yang besar.\") Kalimat in antum illaa fii dhalaalin kabiir dapat dianggap sebagai perkataan para malaikat penjaga neraka kepada orang-orang kafir sewaktu mereka dijelaskan sebagai orang-orang yang mendustakan rasul-rasul. Kalimat ini pun dapat pula dianggap sebagai perkataan orang-orang kafir sebagai alasan mereka tidak percaya kepada rasul-rasul.",[["قَالُوا۟","They will say"],["بَلَىٰ","Yes"],["قَدْ","indeed"],["جَآءَنَا","came to us"],["نَذِيرٌۭ","a warner"],["فَكَذَّبْنَا","but we denied"],["وَقُلْنَا","and we said"],["مَا","Not"],["نَزَّلَ","has sent down"],["ٱللَّهُ","Allah"],["مِن","any"],["شَىْءٍ","thing"],["إِنْ","Not"],["أَنتُمْ","you (are)"],["إِلَّا","but"],["فِى","in"],["ضَلَـٰلٍۢ","error"],["كَبِيرٍۢ","great"]]],"5251":["(Dan mereka berkata, \"Sekiranya kami mendengarkan) maksudnya mendengar yang disertai pemahaman (atau memikirkan) memikirkan apa yang didengarnya, yaitu peringatan rasul-rasul kepada mereka (niscaya tidaklah kami termasuk penghuni-penghuni neraka yang menyala-nyala\").",[["وَقَالُوا۟","And they will say"],["لَوْ","If"],["كُنَّا","we had"],["نَسْمَعُ","listened"],["أَوْ","or"],["نَعْقِلُ","reasoned"],["مَا","not"],["كُنَّا","we (would) have been"],["فِىٓ","among"],["أَصْحَـٰبِ","(the) companions"],["ٱلسَّعِيرِ","(of) the Blaze"]]],"5252":["(Mereka mengakui) orang-orang kafir itu mengaku di saat tiada gunanya lagi pengakuan (dosa mereka) yaitu dosa mendustakan peringatan-peringatan. (Maka kebinasaanlah) dapat dibaca fasuhqan dan fasuhuqan (bagi penghuni-penghuni neraka yang menyala-nyala) mereka dijauhkan dari rahmat Allah swt.",[["فَٱعْتَرَفُوا۟","Then they (will) confess"],["بِذَنۢبِهِمْ","their sins"],["فَسُحْقًۭا","so away with"],["لِّأَصْحَـٰبِ","(the) companions"],["ٱلسَّعِيرِ","(of) the Blaze"]]],"5253":["(Sesungguhnya orang-orang yang takut kepada Rabbnya) mereka yang takut kepada-Nya (dalam sendirian) sewaktu mereka tidak kelihatan oleh orang lain, mereka tetap taat kepada-Nya. Dengan demikian berarti bila mereka berada secara terang-terangan maka lebih takut lagi (mereka akan memperoleh ampunan dan pahala yang besar) yang dimaksud adalah surga.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَخْشَوْنَ","fear"],["رَبَّهُم","their Lord"],["بِٱلْغَيْبِ","unseen"],["لَهُم","for them"],["مَّغْفِرَةٌۭ","(is) forgiveness"],["وَأَجْرٌۭ","and a reward"],["كَبِيرٌۭ","great"]]],"5254":["(Dan rahasiakanlah) hai manusia (perkataan kalian atau lahirkanlah ia; sesungguhnya Dia) yakni Allah swt. (Maha Mengetahui segala isi hati) Maha Mengetahui apa yang tersimpan di dalam kalbu dan apa yang kalian ucapkan. Asbabun nuzul ayat ini ialah karena orang-orang musyrik mengatakan, sebagian di antara mereka kepada sebagian yang lain, \"Rahasiakanlah pembicaraan kalian, niscaya Tuhannya Muhammad tidak akan dapat mendengarkannya.\"",[["وَأَسِرُّوا۟","And conceal"],["قَوْلَكُمْ","your speech"],["أَوِ","or"],["ٱجْهَرُوا۟","proclaim"],["بِهِۦٓ ۖ","it"],["إِنَّهُۥ","Indeed, He"],["عَلِيمٌۢ","(is the) All-Knower"],["بِذَاتِ","of what (is in)"],["ٱلصُّدُورِ","the breasts"]]],"5255":["(Apakah Tuhan yang telah menciptakan tidak mengetahui) apa yang kalian rahasiakan itu, yakni apakah ilmu-Nya tidak dapat menjangkau hal tersebut (sedangkan Dia Maha Halus) ilmu-Nya (lagi Maha Waspada).",[["أَلَا","Does not"],["يَعْلَمُ","know"],["مَنْ","(the One) Who"],["خَلَقَ","created"],["وَهُوَ","And He"],["ٱللَّطِيفُ","(is) the Subtle"],["ٱلْخَبِيرُ","the All-Aware"]]],"5256":["(Dialah yang menjadikan bumi itu mudah bagi kalian) mudah untuk dipakai berjalan di atas permukaannya (maka berjalanlah di segala penjurunya) pada semua arahnya (dan makanlah sebagian dari rezeki-Nya) yang sengaja diciptakan buat kalian. (Dan hanya kepada-Nyalah kalian dibangkitkan) dari kubur untuk mendapatkan pembalasan.",[["هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["جَعَلَ","made"],["لَكُمُ","for you"],["ٱلْأَرْضَ","the earth"],["ذَلُولًۭا","subservient"],["فَٱمْشُوا۟","so walk"],["فِى","in"],["مَنَاكِبِهَا","(the) paths thereof"],["وَكُلُوا۟","and eat"],["مِن","of"],["رِّزْقِهِۦ ۖ","His provision"],["وَإِلَيْهِ","and to Him"],["ٱلنُّشُورُ","(is) the Resurrection"]]],"5257":["(Apakah kalian merasa aman) dapat dibaca secara tahqiq dan dapat pula dibaca secara tashil (terhadap kekuasaan Allah yang di langit) yakni pengaruh dan kekuasaan-Nya yang di langit (bahwa Dia akan menjungkir balikkan) berkedudukan menjadi badal dari lafal man (bumi bersama kalian, sehingga dengan tiba-tiba bumi itu berguncang) menjadi gempa dan menindih kalian.",[["ءَأَمِنتُم","Do you feel secure"],["مَّن","(from Him) Who"],["فِى","(is) in"],["ٱلسَّمَآءِ","the heaven"],["أَن","not"],["يَخْسِفَ","He will cause to swallow"],["بِكُمُ","you"],["ٱلْأَرْضَ","the earth"],["فَإِذَا","when"],["هِىَ","it"],["تَمُورُ","sways"]]],"5258":["(Atau apakah kalian merasa aman terhadap kekuasaan Allah yang di langit bahwa Dia akan mengirimkan) lafal an yursila menjadi badal dari lafal man (kepada kalian badai yang berbatu) yakni angin dahsyat yang menghujani kalian dengan batu. (Maka kelak kalian akan mengetahui) di saat kalian menyaksikan azab-Nya (bagaimana peringatan-Ku) yakni azab-Ku; maksudnya bahwa azab-Ku itu adalah benar.",[["أَمْ","Or"],["أَمِنتُم","do you feel secure"],["مَّن","(from Him) Who"],["فِى","(is) in"],["ٱلسَّمَآءِ","the heaven"],["أَن","that"],["يُرْسِلَ","He will send"],["عَلَيْكُمْ","against you"],["حَاصِبًۭا ۖ","a storm of stones"],["فَسَتَعْلَمُونَ","Then you would know"],["كَيْفَ","how"],["نَذِيرِ","(was) My warning"]]],"5259":["(Dan sesungguhnya orang-orang sebelum mereka telah mendustakan) umat-umat sebelum mereka. (Maka alangkah hebatnya kemurkaan-Ku) keingkaran-Ku terhadap mereka disebabkan kedustaan mereka, yaitu sewaktu mereka dibinasakan, bahwasanya pembinasaan-Ku itu adalah benar.",[["وَلَقَدْ","And indeed"],["كَذَّبَ","denied"],["ٱلَّذِينَ","those"],["مِن","from"],["قَبْلِهِمْ","before them"],["فَكَيْفَ","and how"],["كَانَ","was"],["نَكِيرِ","My rejection"]]],"5260":["(Apakah mereka tidak melihat) tidak memperhatikan (burung-burung yang berada di atas mereka) yakni di udara (yang mengembangkan sayapnya) melebarkan sayapnya (dan mengatupkannya?) menutupkannya sesudah dikembangkan. (Tidak ada yang menahan mereka) agar jangan jatuh ke bumi sewaktu mengembangkan dan mengatupkan sayapnya (selain Yang Maha Penyayang) yakni dengan kekuasaan-Nya. (Sesungguhnya Dia Maha Melihat segala sesuatu) makna yang dimaksud, apakah mereka tidak menyimpulkan dengan tetapnya burung-burung di udara tentang kekuasaan Kami, bahwa Kami dapat menimpakan kepada mereka azab yang telah disebutkan di atas tadi dan azab lainnya.",[["أَوَلَمْ","Do not"],["يَرَوْا۟","they see"],["إِلَى","[to]"],["ٱلطَّيْرِ","the birds"],["فَوْقَهُمْ","above them"],["صَـٰٓفَّـٰتٍۢ","spreading (their wings)"],["وَيَقْبِضْنَ ۚ","and folding"],["مَا","Not"],["يُمْسِكُهُنَّ","holds them"],["إِلَّا","except"],["ٱلرَّحْمَـٰنُ ۚ","the Most Gracious"],["إِنَّهُۥ","Indeed, He"],["بِكُلِّ","(is) of every"],["شَىْءٍۭ","thing"],["بَصِيرٌ","All-Seer"]]],"5261":["(Atau siapakah) berkedudukan menjadi mubtada (dia) menjadi khabar dari mubtada (yang) menjadi badal dari lafal haadza (menjadi tentara) yakni penolong-penolong (kalian) berkedudukan menjadi shilah dari lafal alladzii (yang akan menolong kalian) menjadi sifat dari lafal jundun (selain daripada Allah Yang Maha Penyayang) yang dapat menolak datangnya azab bagi kalian; yakni tiada seseorang pun yang dapat menolong kalian (tidak lain) tiadalah (orang-orang kafir itu hanyalah dalam keadaan tertipu) mereka tertipu oleh setan, bahwasanya azab tidak akan turun atas mereka.",[["أَمَّنْ","Who is"],["هَـٰذَا","this"],["ٱلَّذِى","the one"],["هُوَ","he"],["جُندٌۭ","(is) an army"],["لَّكُمْ","for you"],["يَنصُرُكُم","to help you"],["مِّن","from"],["دُونِ","besides"],["ٱلرَّحْمَـٰنِ ۚ","the Most Gracious"],["إِنِ","Not"],["ٱلْكَـٰفِرُونَ","(are) the disbelievers"],["إِلَّا","but"],["فِى","in"],["غُرُورٍ","delusion"]]],"5262":["(Atau siapakah dia yang memberi kalian rezeki jika Dia menahan) yakni Allah Yang Maha Penyayang menahan (rezeki-Nya) yakni hujan-Nya terhadap kalian. Jawab syaratnya tidak disebutkan, karena dapat disimpulkan dari kalimat sebelumnya. Lengkapnya, siapakah yang dapat memberi kalian rezeki? Tentu tiada seorang pun yang dapat memberikan rezeki kepada kalian selain-Nya. (Tetapi mereka terus-menerus) berkelanjutan (di dalam kesombongan) dalam kesombongannya (dan menjauhkan diri) dari kebenaran.",[["أَمَّنْ","Who is"],["هَـٰذَا","this"],["ٱلَّذِى","the one"],["يَرْزُقُكُمْ","to provide you"],["إِنْ","if"],["أَمْسَكَ","He withheld"],["رِزْقَهُۥ ۚ","His provision"],["بَل","Nay"],["لَّجُّوا۟","they persist"],["فِى","in"],["عُتُوٍّۢ","pride"],["وَنُفُورٍ","and aversion"]]],"5263":["(Maka apakah orang yang berjalan terjungkal) yakni terbalik (di atas mukanya itu lebih banyak mendapat petunjuk, ataukah orang yang berjalan tegap) yakni secara wajar dengan kakinya (di atas jalan) tuntunan (yang lurus) khabar dari mubtada yang kedua tidak disebutkan karena cukup hanya ditunjukkan oleh makna yang terkandung di dalam khabar yang pertama, yakni lebih banyak mendapat petunjuk. Perumpamaan ini menggambarkan tentang keadaan orang yang kafir pada permintaan yang pertama, dan orang yang beriman pada perumpamaan yang kedua, yakni manakah di antara keduanya yang lebih banyak mendapat petunjuk?",[["أَفَمَن","Then is he who"],["يَمْشِى","walks"],["مُكِبًّا","fallen"],["عَلَىٰ","on"],["وَجْهِهِۦٓ","his face"],["أَهْدَىٰٓ","better guided"],["أَمَّن","or (he) who"],["يَمْشِى","walks"],["سَوِيًّا","upright"],["عَلَىٰ","on"],["صِرَٰطٍۢ","(the) Path"],["مُّسْتَقِيمٍۢ","Straight"]]],"5264":["(Katakanlah! \"Dialah Yang menjadikan kalian) yakni yang telah menciptakan kalian (dan menjadikan bagi kalian pendengaran, penglihatan dan hati\") atau kalbu. (Tetapi amat sedikit kalian bersyukur) huruf maa adalah huruf zaidah, dan jumlah kalimat ini merupakan jumlah isti'naf atau kalimat baru yang memberitakan tentang syukur mereka yang amat sedikit terhadap nikmat-nikmat tersebut.",[["قُلْ","Say"],["هُوَ","He"],["ٱلَّذِىٓ","(is) the One Who"],["أَنشَأَكُمْ","produced you"],["وَجَعَلَ","and made"],["لَكُمُ","for you"],["ٱلسَّمْعَ","the hearing"],["وَٱلْأَبْصَـٰرَ","and the vision"],["وَٱلْأَفْـِٔدَةَ ۖ","and the feelings"],["قَلِيلًۭا","Little"],["مَّا","(is) what"],["تَشْكُرُونَ","you give thanks"]]],"5265":["(Katakanlah! \"Dialah Yang menjadikan kalian berkembang biak) artinya menciptakan kalian dapat berkembang biak (di muka bumi, dan hanya kepada-Nyalah kalian kelak dikumpulkan\") untuk menjalani hisab.",[["قُلْ","Say"],["هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["ذَرَأَكُمْ","multiplied you"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَإِلَيْهِ","and to Him"],["تُحْشَرُونَ","you will be gathered"]]],"5266":["(Dan mereka berkata) kepada orang-orang yang beriman, (\"Kapankah datangnya Janji itu) yakni janji datangnya hari semua makhluk dihimpun (jika kalian adalah orang-orang yang benar?\") dalam hal ini.",[["وَيَقُولُونَ","And they say"],["مَتَىٰ","When"],["هَـٰذَا","(is) this"],["ٱلْوَعْدُ","promise"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"5267":["(Katakanlah!, \"Sesungguhnya ilmu) tentang kedatangan hari tersebut (hanya pada sisi Allah, dan sesungguhnya aku hanyalah seorang pemberi peringatan yang menjelaskan.\") Yakni yang jelas peringatannya.",[["قُلْ","Say"],["إِنَّمَا","Only"],["ٱلْعِلْمُ","the knowledge"],["عِندَ","(is) with"],["ٱللَّهِ","Allah"],["وَإِنَّمَآ","and only"],["أَنَا۠","I am"],["نَذِيرٌۭ","a warner"],["مُّبِينٌۭ","clear"]]],"5268":["(Ketika mereka melihat azab itu) sesudah mereka dihimpunkan (sudah dekat) artinya, dekat sekali (menjadi muramlah) menjadi hitam muramlah (muka orang-orang kafir itu. Dan dikatakan) kepada mereka, yakni para malaikat penjaga neraka berkata kepada mereka (\"Inilah) azab (yang dahulu kalian terhadapnya) yakni sewaktu kalian diancam dengan azab ini (selalu menganggapnya sebagai yang diada-adakan.\") Yakni kalian menduga, bahwasanya kalian tidak akan dibangkitkan menjadi hidup kembali. Hal ini menceritakan keadaan di masa mendatang, akan tetapi ungkapannya memberikan pengertian sudah terjadi. Ini tiada lain karena subjeknya pasti benar-benar terjadi.",[["فَلَمَّا","But when"],["رَأَوْهُ","they (will) see it"],["زُلْفَةًۭ","approaching"],["سِيٓـَٔتْ","(will be) distressed"],["وُجُوهُ","(the) faces"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟","disbelieved"],["وَقِيلَ","and it will be said"],["هَـٰذَا","This"],["ٱلَّذِى","(is) that which"],["كُنتُم","you used to"],["بِهِۦ","for it"],["تَدَّعُونَ","call"]]],"5269":["(Katakanlah!, \"Terangkanlah kepadaku jika Allah mematikan aku dan orang-orang yang bersama dengan aku) yakni orang-orang mukmin, kami binasa karena azab-Nya, sebagaimana yang kalian maksudkan (atau memberi rahmat kepada kami) maksudnya, Dia tidak mengazab kami (tetapi siapakah yang dapat melindungi orang-orang yang kafir dari siksa yang pedih?\") Tentu saja tiada seorang pun yang dapat melindungi mereka dari azab-Nya.",[["قُلْ","Say"],["أَرَءَيْتُمْ","Have you seen"],["إِنْ","if"],["أَهْلَكَنِىَ","destroys me"],["ٱللَّهُ","Allah"],["وَمَن","and whoever"],["مَّعِىَ","(is) with me"],["أَوْ","or"],["رَحِمَنَا","has mercy upon us"],["فَمَن","then who"],["يُجِيرُ","(can) protect"],["ٱلْكَـٰفِرِينَ","the disbelievers"],["مِنْ","from"],["عَذَابٍ","a punishment"],["أَلِيمٍۢ","painful"]]],"5270":["(Katakanlah!, \"Dialah Allah Yang Maha Penyayang kami beriman kepada-Nya dan kepada-Nyalah kami bertawakal. Kelak kalian akan mengetahui) bilamana mereka menyaksikan azab itu. Lafal fasata`lamuuna dapat pula dibaca fasaya`lamuuna, artinya kelak mereka akan mengetahui di saat mereka menyaksikan azab (siapakah yang berada dalam kesesatan yang nyata.\") Kami-kah atau mereka?",[["قُلْ","Say"],["هُوَ","He"],["ٱلرَّحْمَـٰنُ","(is) the Most Gracious"],["ءَامَنَّا","we believe"],["بِهِۦ","in Him"],["وَعَلَيْهِ","and upon Him"],["تَوَكَّلْنَا ۖ","we put (our) trust"],["فَسَتَعْلَمُونَ","So you will know"],["مَنْ","who"],["هُوَ","(is) it"],["فِى","(that is) in"],["ضَلَـٰلٍۢ","error"],["مُّبِينٍۢ","clear"]]],"5271":["(Katakanlah, \"Terangkanlah kepadaku jika sumber air kalian menjadi kering;) yakni airnya masuk jauh ke dalam bumi (maka siapakah yang akan mendatangkan air yang mengalir bagi kalian?\") Sehingga air itu menyumber dan dapat dicapai oleh tangan atau oleh timba-timba, sebagaimana air yang kalian miliki sekarang? Tiada seorang pun yang dapat mendatangkannya selain Allah swt. Maka, mengapa kalian mengingkari adanya hari berbangkit, yaitu hari di mana Dia membangkitkan kalian menjadi hidup kembali. Disunahkan bagi pembaca surah ini, bila bacaannya sampai kepada lafal ma`iin, hendaknya ia mengucapkan kalimat jawabannya, yaitu \"allaahu rabbul 'aalamiina/Allah Rabb semesta alam yang dapat mengeluarkannya. Demikianlah menurut keterangan yang dikemukakan di dalam hadis. Dan ayat ini dibacakan terhadap sebagian orang-orang yang bersifat angkara murka, maka menurut perawinya, bahwa cangkul dan sekop penggali tanah terus menghunjam ke tanah, akan tetapi sumber air tidak muncul-muncul juga; ia telah pergi jauh meresap ke dalam bumi yang tidak dapat dicapainya. Kami berlindung kepada Allah dari perbuatan berani melawan Allah dan ayat-ayat-Nya.",[["قُلْ","Say"],["أَرَءَيْتُمْ","Have you seen"],["إِنْ","if"],["أَصْبَحَ","becomes"],["مَآؤُكُمْ","your water"],["غَوْرًۭا","sunken"],["فَمَن","then who"],["يَأْتِيكُم","could bring you"],["بِمَآءٍۢ","water"],["مَّعِينٍۭ","flowing"]]],"5272":["(Nun) adalah salah satu dari huruf hijaiah, hanya Allahlah yang mengetahui arti dan maksudnya (demi qalam) yang dipakai untuk menulis nasib semua makhluk di Lohmahfuz (dan apa yang mereka tulis) apa yang ditulis oleh para malaikat berupa kebaikan dan kesalehan.",[["نٓ ۚ","Nun"],["وَٱلْقَلَمِ","By the pen"],["وَمَا","and what"],["يَسْطُرُونَ","they write"]]],"5273":["(Kamu sekali-kali bukanlah) hai Muhammad (orang gila, berkat nikmat Rabbmu) yang telah mengaruniakan kenabian kepadamu, dan juga nikmat-nikmat-Nya yang lain. Ayat ini merupakan jawaban terhadap perkataan orang-orang kafir, yang mengatakan bahwa Muhammad adalah orang gila.",[["مَآ","Not"],["أَنتَ","you (are)"],["بِنِعْمَةِ","by (the) Grace"],["رَبِّكَ","(of) your Lord"],["بِمَجْنُونٍۢ","a madman"]]],"5274":["(Dan sesungguhnya bagi kamu benar-benar pahala yang besar yang tidak putus-putusnya) tiada pernah terputus.",[["وَإِنَّ","And indeed"],["لَكَ","for you"],["لَأَجْرًا","surely (is) a reward"],["غَيْرَ","without"],["مَمْنُونٍۢ","end"]]],"5275":["(Dan sesungguhnya kamu benar-benar berbudi pekerti) beragama (yang agung.)",[["وَإِنَّكَ","And indeed, you"],["لَعَلَىٰ","surely (are)"],["خُلُقٍ","(of) a moral character"],["عَظِيمٍۢ","great"]]],"5276":["(Maka kelak kamu akan melihat dan mereka pun akan melihat.)",[["فَسَتُبْصِرُ","So you will see"],["وَيُبْصِرُونَ","and they will see"]]],"5277":["(Siapakah di antara kalian yang gila) yang tidak waras akalnya, kamukah atau mereka. Lafal al-maftuun ini wazannya sama dengan lafal al-ma`quul, berasal dari mashdar al-futuun, artinya gila.",[["بِأَييِّكُمُ","Which of you"],["ٱلْمَفْتُونُ","(is) the afflicted one"]]],"5278":["(Sesungguhnya Rabbmu, Dialah Yang Paling Mengetahui siapa yang sesat dari jalan-Nya dan Dialah Yang Paling mengetahui orang-orang yang mendapat petunjuk) lafal a`lamu di sini bermakna 'aalimun, yakni Dia mengetahui siapa yang sesat dari jalan-Nya dan Dialah Yang mengetahui orang-orang yang mendapat petunjuk.",[["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["هُوَ","He"],["أَعْلَمُ","(is) most knowing"],["بِمَن","of (he) who"],["ضَلَّ","has strayed"],["عَن","from"],["سَبِيلِهِۦ","His way"],["وَهُوَ","and He"],["أَعْلَمُ","(is) most knowing"],["بِٱلْمُهْتَدِينَ","of the guided ones"]]],"5279":["(Maka janganlah kamu ikuti orang-orang yang mendustakan ayat-ayat Allah.)",[["فَلَا","So (do) not"],["تُطِعِ","obey"],["ٱلْمُكَذِّبِينَ","the deniers"]]],"5280":["(Mereka menginginkan) mengharapkan (supaya) merupakan mashdariyah (kamu bersikap lunak) bersikap lembut terhadap mereka (lalu mereka bersikap lunak) pula terhadapmu; diathafkan kepada lafal tudhinu. Seandainya dijadikan sebagai jawab dari tamanni yang tersimpulkan dari lafal wadduu, maka sebelum huruf fa diperkirakan adanya lafal hum. Yakni, seandainya kamu bersikap lunak terhadap mereka, maka mereka pun akan bersikap lunak pula terhadapmu.",[["وَدُّوا۟","They wish"],["لَوْ","that"],["تُدْهِنُ","you should compromise"],["فَيُدْهِنُونَ","so they would compromise"]]],"5281":["(Dan janganlah kamu ikuti setiap orang yang banyak bersumpah) dengan cara yang batil (lagi hina) yakni rendah.",[["وَلَا","And (do) not"],["تُطِعْ","obey"],["كُلَّ","every"],["حَلَّافٍۢ","habitual swearer"],["مَّهِينٍ","worthless"]]],"5282":["(Yang banyak mencela) atau sering mengumpat (yang kian ke mari menghambur fitnah) yakni berjalan ke sana dan ke mari di antara orang-orang dengan maksud merusak mereka, yakni menghasut mereka.",[["هَمَّازٍۢ","Defamer"],["مَّشَّآءٍۭ","going about"],["بِنَمِيمٍۢ","with malicious gossip"]]],"5283":["(Yang banyak menghalangi perbuatan baik) artinya sangat kikir tidak mau membelanjakan hartanya kepada hak-hak yang diwajibkan atas dirinya (yang melampaui batas) sangat aniaya (lagi banyak dosa) banyak melakukan perbuatan dosa.",[["مَّنَّاعٍۢ","A preventer"],["لِّلْخَيْرِ","of (the) good"],["مُعْتَدٍ","transgressor"],["أَثِيمٍ","sinful"]]],"5284":["(Yang kaku kasar) wataknya kaku lagi kasar (selain dari itu, yang terkenal kejahatannya) dia adalah seseorang yang dianggap sebagai orang Quraisy, padahal dia bukan dari kalangan mereka, yaitu Walid bin Mughirah. Ayahnya menjulukinya sebagai orang Quraisy setelah ia berumur delapan belas tahun. Ibnu Abbas r.a. mengatakan, bahwa kami belum pernah mengetahui, bahwa Allah swt. menyifati seseorang dengan sifat-sifat yang tercela sebagaimana yang telah dilakukan-Nya terhadap Walid, sehingga keaiban itu tetap menempel pada diri Walid untuk selama-lamanya. Dan bertaalluq kepada lafal zaniim, zharaf yang terdapat pada sebelumnya.",[["عُتُلٍّۭ","Cruel"],["بَعْدَ","after"],["ذَٰلِكَ","(all) that"],["زَنِيمٍ","utterly useless"]]],"5285":["(Karena dia mempunyai banyak harta dan anak) bentuk asalnya adalah lian, dan bertaalluq kepada makna yang menunjukkan terhadap pengertiannya.",[["أَن","Because"],["كَانَ","(he) is"],["ذَا","a possessor"],["مَالٍۢ","(of) wealth"],["وَبَنِينَ","and children"]]],"5286":["(Apabila dibacakan kepadanya ayat-ayat Kami) yakni Alquran (ia berkata) bahwa Alquran itu (dongeng-dongengan orang-orang dahulu kala.\") Yaitu hanyalah kedustaan yang sengaja dibuat-buat guna menyenangkan hati kami sewaktu ia disebutkan atau diceritakan. Menurut suatu qiraat ada lafal a-an dengan memakai dua huruf Hamzah yang kedua-duanya difathahkan.",[["إِذَا","When"],["تُتْلَىٰ","are recited"],["عَلَيْهِ","to him"],["ءَايَـٰتُنَا","Our Verses"],["قَالَ","he says"],["أَسَـٰطِيرُ","Stories"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"5287":["(Kelak akan Kami beri tanda dia di belalainya) Kami akan menjadikan tanda pada hidungnya, yang menyebabkannya cacat seumur hidup. Maka dia terpotong-potong hidungnya ketika perang Badar.",[["سَنَسِمُهُۥ","We will brand him"],["عَلَى","on"],["ٱلْخُرْطُومِ","the snout"]]],"5288":["(Sesungguhnya Kami telah mencoba mereka) Kami telah menguji orang-orang musyrik Mekah dengan paceklik dan kelaparan (sebagaimana Kami telah mencoba pemilik-pemilik kebun) atau ladang (ketika mereka bersumpah bahwa mereka sungguh-sungguh akan memetik hasilnya) akan memetik buahnya (di pagi hari) di pagi buta, supaya orang-orang miskin tidak mengetahuinya. Maka orang-orang yang memiliki kebun itu mempunyai alasan bila mereka tidak memberikan sedekah kepada mereka; tidak sebagaimana bapak-bapak mereka yang selalu memberikan sebagian dari hasilnya buat orang-orang miskin sebagai sedekahnya.",[["إِنَّا","Indeed, We"],["بَلَوْنَـٰهُمْ","have tried them"],["كَمَا","as"],["بَلَوْنَآ","We tried"],["أَصْحَـٰبَ","(the) companions"],["ٱلْجَنَّةِ","(of) the garden"],["إِذْ","when"],["أَقْسَمُوا۟","they swore"],["لَيَصْرِمُنَّهَا","to pluck its fruit"],["مُصْبِحِينَ","(in the) morning"]]],"5289":["(Dan mereka tidak mengecualikan) di dalam sumpah mereka itu kepada kehendak Allah swt. Ayat ini merupakan jumlah isti'naf atau kalimat permulaan; yakni, kelakuan mereka seperti itu; mereka tidak pernah menggantungkan sumpahnya itu kepada kehendak Allah swt.",[["وَلَا","And not"],["يَسْتَثْنُونَ","making exception"]]],"5290":["(Lalu kebun itu diliputi malapetaka dari Rabbmu) berupa api yang melahap kesemuanya di waktu malam (ketika mereka sedang tidur.)",[["فَطَافَ","So there came"],["عَلَيْهَا","upon it"],["طَآئِفٌۭ","a visitation"],["مِّن","from"],["رَّبِّكَ","your Lord"],["وَهُمْ","while they"],["نَآئِمُونَ","were asleep"]]],"5291":["(Maka jadilah kebun itu hitam seperti malam yang gelap gulita) yakni menjadi hangus terbakar semuanya, sehingga tampak hitam.",[["فَأَصْبَحَتْ","So it became"],["كَٱلصَّرِيمِ","as if reaped"]]],"5292":["(Lalu mereka panggil-memanggil di pagi hari.)",[["فَتَنَادَوْا۟","And they called one another"],["مُصْبِحِينَ","(at) morning"]]],"5293":["(\"Pergilah di waktu pagi ini ke kebun kalian) ke ladang kalian; lafal ini menafsirkan pengertian yang terkandung di dalam lafal tanadauw; atau huruf an dianggap sebagai an mashdariyah (jika kalian hendak memetik buahnya\") ingin memetik hasilnya; jawab syaratnya ditunjukkan oleh pengertian kalimat sebelumnya.",[["أَنِ","That"],["ٱغْدُوا۟","Go early"],["عَلَىٰ","to"],["حَرْثِكُمْ","your crop"],["إِن","if"],["كُنتُمْ","you would"],["صَـٰرِمِينَ","pluck (the) fruit"]]],"5294":["(Maka pergilah mereka saling berbisik-bisikan) yakni dengan secara diam-diam.",[["فَٱنطَلَقُوا۟","So they went"],["وَهُمْ","while they"],["يَتَخَـٰفَتُونَ","lowered (their) voices"]]],"5295":["(\"Pada hari ini janganlah ada seorang miskin pun masuk ke dalam kebun kalian.\") Ayat ini merupakan penafsiran dari makna yang terkandung pada ayat sebelumnya; atau huruf an dianggap sebagai huruf mashdariyah.",[["أَن","That"],["لَّا","Not"],["يَدْخُلَنَّهَا","will enter it"],["ٱلْيَوْمَ","today"],["عَلَيْكُم","upon you"],["مِّسْكِينٌۭ","any poor person"]]],"5296":["(Dan berangkatlah mereka di pagi hari dengan niat menghalangi) orang-orang miskin (seraya merasa mampu) yakni mampu untuk menghalangi orang-orang miskin, menurut dugaan mereka sendiri.",[["وَغَدَوْا۟","And they went early"],["عَلَىٰ","with"],["حَرْدٍۢ","determination"],["قَـٰدِرِينَ","able"]]],"5297":["(Tatkala mereka melihat kebun itu) dalam keadaan hangus terbakar (mereka berkata, \"Sesungguhnya kita benar-benar orang-orang yang sesat.\") Bukankah ini kebun kita. Kemudian setelah mereka mengetahui, bahwa itu adalah benar-benar kebun mereka, lalu mereka mengatakan:",[["فَلَمَّا","But when"],["رَأَوْهَا","they saw it"],["قَالُوٓا۟","they said"],["إِنَّا","Indeed, we"],["لَضَآلُّونَ","(are) surely lost"]]],"5298":["(Bahkan kita dihalangi) dari memperoleh buahnya disebabkan kita telah menghalang-halangi orang-orang miskin dari memperoleh bagiannya.",[["بَلْ","Nay"],["نَحْنُ","We"],["مَحْرُومُونَ","(are) deprived"]]],"5299":["(Berkatalah seorang yang paling baik pikirannya di antara mereka) yaitu orang yang terbaik di antara mereka (\"Bukankah aku mengatakan kepada kalian, mengapa tidak) kenapa tidak (kalian bertasbih?\") kepada Allah seraya bertobat kepada-Nya.",[["قَالَ","Said"],["أَوْسَطُهُمْ","(the) most moderate of them"],["أَلَمْ","Did not"],["أَقُل","I tell"],["لَّكُمْ","you"],["لَوْلَا","'Why not"],["تُسَبِّحُونَ","you glorify (Allah)?'"]]],"5300":["(Mereka mengucapkan, \"Maha Suci Rabb kami, sesungguhnya kami adalah orang-orang yang zalim.\") Karena kami telah menghalang-halangi orang-orang miskin dari haknya.",[["قَالُوا۟","They said"],["سُبْحَـٰنَ","Glory be"],["رَبِّنَآ","(to) our Lord"],["إِنَّا","Indeed, we"],["كُنَّا","[we] were"],["ظَـٰلِمِينَ","wrongdoers"]]],"5301":["(Lalu sebagian mereka menghadapi sebagian yang lain seraya cela-mencela.)",[["فَأَقْبَلَ","Then approached"],["بَعْضُهُمْ","some of them"],["عَلَىٰ","to"],["بَعْضٍۢ","others"],["يَتَلَـٰوَمُونَ","blaming each other"]]],"5302":["(Mereka berkata, \"Aduhai) huruf ya di sini bermakna tanbih (celakalah kita) binasalah kita (sesungguhnya kita ini benar-benar orang-orang yang melampaui batas.)",[["قَالُوا۟","They said"],["يَـٰوَيْلَنَآ","O woe to us"],["إِنَّا","Indeed, we"],["كُنَّا","[we] were"],["طَـٰغِينَ","transgressors"]]],"5303":["(Mudah-mudahan Rabb kita memberikan ganti kepada kita) dapat dibaca yubdilanaa dan yubaddilanaa (yang lebih baik daripada itu; sesungguhnya kita mengharapkan ampunan dari Rabb kita.\") Supaya Dia menerima tobat kita dan mendatangkan kepada kita kebun yang lebih baik dari kebun kita yang dahulu. Menurut suatu riwayat disebutkan, bahwa setelah itu mereka diberi kebun yang lebih baik dari yang semula.",[["عَسَىٰ","Perhaps"],["رَبُّنَآ","our Lord"],["أَن","[that]"],["يُبْدِلَنَا","will substitute for us"],["خَيْرًۭا","a better"],["مِّنْهَآ","than it"],["إِنَّآ","Indeed, we"],["إِلَىٰ","to"],["رَبِّنَا","our Lord"],["رَٰغِبُونَ","turn devoutly"]]],"5304":["(Seperti itulah) sebagaimana azab Kami kepada mereka (azab) di dunia, bagi orang yang menentang perintah Kami dari kalangan orang-orang kafir Mekah dan lain-lainnya. (Dan sesungguhnya azab akhirat lebih besar jika mereka mengetahui) jika mereka mengetahuinya, niscaya mereka tidak akan menentang perintah Kami. Ayat ini diturunkan sewaktu orang-orang kafir Mekah mengatakan, bahwa jika Dia membangkitkan kami, niscaya kami akan diberi pahala yang lebih baik daripada kalian.",[["كَذَٰلِكَ","Such"],["ٱلْعَذَابُ ۖ","(is) the punishment"],["وَلَعَذَابُ","And surely the punishment"],["ٱلْـَٔاخِرَةِ","(of) the Hereafter"],["أَكْبَرُ ۚ","(is) greater"],["لَوْ","if"],["كَانُوا۟","they"],["يَعْلَمُونَ","know"]]],"5305":["(Sesungguhnya bagi orang-orang yang bertakwa surga-surga yang penuh kenikmatan di sisi Rabbnya.)",[["إِنَّ","Indeed"],["لِلْمُتَّقِينَ","for the righteous"],["عِندَ","with"],["رَبِّهِمْ","their Lord"],["جَنَّـٰتِ","(are) Gardens"],["ٱلنَّعِيمِ","(of) Delight"]]],"5306":["(Maka apakah patut Kami menjadikan orang-orang Islam itu sama dengan orang-orang yang berdosa?) maksudnya mendapatkan pahala yang sama dengan orang-orang kafir.",[["أَفَنَجْعَلُ","Then will We treat"],["ٱلْمُسْلِمِينَ","the Muslims"],["كَٱلْمُجْرِمِينَ","like the criminals"]]],"5307":["(Mengapa kalian berbuat demikian; bagaimanakah kalian mengambil keputusan?) dengan keputusan yang rusak ini?",[["مَا","What"],["لَكُمْ","(is) for you"],["كَيْفَ","How"],["تَحْكُمُونَ","(do) you judge"]]],"5308":["(Atau adakah) artinya, benarkah (kalian mempunyai kitab) yang diturunkan dari Allah (yang kalian mempelajarinya) yang kalian membacanya.",[["أَمْ","Or"],["لَكُمْ","(is) for you"],["كِتَـٰبٌۭ","a book"],["فِيهِ","wherein"],["تَدْرُسُونَ","you learn"]]],"5309":["(Bahwa di dalamnya kalian benar-benar boleh memilih apa yang kalian sukai) kalian boleh memilih sesuka hati.",[["إِنَّ","Indeed"],["لَكُمْ","for you"],["فِيهِ","in it"],["لَمَا","what"],["تَخَيَّرُونَ","you choose"]]],"5310":["(Atau apakah kalian memperoleh janji-janji) perjanjian-perjanjian (yang diperkuat dengan sumpah dari Kami) yang telah diperkuat oleh Kami (yang tetap berlaku sampai hari kiamat) lafal ilaa yaumil qiyaamah ini bertaalluq kepadanya makna yang terkandung di dalam lafal 'alainaa, dan di dalam kalam ini terkandung makna qasam atau sumpah, yakni Kami telah bersumpah untuk mewajibkannya bagi kalian (sesungguhnya kalian benar-benar dapat mengambil keputusan) sekehendak kalian tentangnya?",[["أَمْ","Or"],["لَكُمْ","for you"],["أَيْمَـٰنٌ","oaths"],["عَلَيْنَا","from us"],["بَـٰلِغَةٌ","reaching"],["إِلَىٰ","to"],["يَوْمِ","(the) Day"],["ٱلْقِيَـٰمَةِ ۙ","(of) the Resurrection"],["إِنَّ","indeed"],["لَكُمْ","for you"],["لَمَا","(is) what"],["تَحْكُمُونَ","you judge"]]],"5311":["(Tanyakanlah kepada mereka, \"Siapakah di antara mereka terhadap hal tersebut) hukum atau keputusan yang mereka ambil buat diri mereka sendiri, yaitu bahwasanya mereka kelak di akhirat akan diberi pahala yang lebih utama dari orang-orang mukmin (yang bertanggung jawab?\") yang menanggungnya bagi mereka.",[["سَلْهُمْ","Ask them"],["أَيُّهُم","which of them"],["بِذَٰلِكَ","for that"],["زَعِيمٌ","(is) responsible"]]],"5312":["(Atau apakah mereka mempunyai) di sisi mereka (sekutu-sekutu?) yang sepakat dengan mereka tentang ucapan itu, yaitu mereka akan menjamin bagi mereka dalam hal ini. Maka apabila memang demikian keadaannya (maka hendaklah mereka mendatangkan sekutu-sekutu mereka) yang akan memberikan jaminan tentang hal itu bagi mereka (jika mereka adalah orang-orang yang benar.)",[["أَمْ","Or"],["لَهُمْ","(are) for them"],["شُرَكَآءُ","partners"],["فَلْيَأْتُوا۟","Then let them bring"],["بِشُرَكَآئِهِمْ","their partners"],["إِن","if"],["كَانُوا۟","they are"],["صَـٰدِقِينَ","truthful"]]],"5313":["Ingatlah (pada hari betis disingkapkan) ungkapan ini menggambarkan tentang dahsyatnya keadaan pada hari kiamat, yaitu sewaktu hisab dan pembalasan dilaksanakan. Dikatakan \"kasyafatil harbu 'an saaqin\", artinya perang itu berkobar dengan sengitnya (dan mereka dipanggil untuk bersujud) sebagai ujian buat keimanan mereka (maka mereka tidak kuasa) karena punggung mereka lekat bertumpuk menjadi satu, sehingga mereka tidak dapat bersujud.",[["يَوْمَ","(The) Day"],["يُكْشَفُ","will be uncovered"],["عَن","from"],["سَاقٍۢ","the shin"],["وَيُدْعَوْنَ","and they will be called"],["إِلَى","to"],["ٱلسُّجُودِ","prostrate"],["فَلَا","but not"],["يَسْتَطِيعُونَ","they will be able"]]],"5314":["(Seraya tunduk ke bawah) lafal khaasyi`atan ini merupakan hal dari dhamir yang terkandung pada lafal yad`uuna, artinya, dalam keadaan terhina (pandangan mereka) maksudnya, mereka tidak dapat mengangkat pandangan matanya (lagi mereka diliputi) mereka diselimuti (kehinaan. Dan sesungguhnya mereka dahulu diseru) sewaktu di dunia (untuk bersujud sedang mereka dalam keadaan sejahtera) akan tetapi mereka tidak mau melakukannya, yakni tidak mau salat.",[["خَـٰشِعَةً","Humbled"],["أَبْصَـٰرُهُمْ","their eyes"],["تَرْهَقُهُمْ","will cover them"],["ذِلَّةٌۭ ۖ","humiliation"],["وَقَدْ","And indeed"],["كَانُوا۟","they were"],["يُدْعَوْنَ","called"],["إِلَى","to"],["ٱلسُّجُودِ","prostrate"],["وَهُمْ","while they"],["سَـٰلِمُونَ","(were) sound"]]],"5315":["(Maka serahkanlah kepada-Ku) berikanlah kepada Aku (orang-orang yang mendustakan perkataan ini) yang mendustakan Alquran. (Nanti Kami akan menarik mereka dengan berangsur-angsur) Kami akan mengambil mereka secara berangsur-angsur (dari arah yang tidak mereka ketahui.)",[["فَذَرْنِى","So leave Me"],["وَمَن","and whoever"],["يُكَذِّبُ","denies"],["بِهَـٰذَا","this"],["ٱلْحَدِيثِ ۖ","Statement"],["سَنَسْتَدْرِجُهُم","We will progressively lead them"],["مِّنْ","from"],["حَيْثُ","where"],["لَا","not"],["يَعْلَمُونَ","they know"]]],"5316":["(Dan Aku memberi tangguh kepada mereka) Aku menangguhkan mereka. (Sesungguhnya rencana-Ku amat teguh) amat kuat dan tak dapat ditinggalkan.",[["وَأُمْلِى","And I will give respite"],["لَهُمْ ۚ","to them"],["إِنَّ","Indeed"],["كَيْدِى","My plan"],["مَتِينٌ","(is) firm"]]],"5317":["(Ataukah) yakni apakah (kamu meminta kepada mereka) atas penyampaian risalahmu (upah dengan utang, lalu mereka karena utang itu) karena apa yang harus mereka bayarkan kepadamu (merasa keberatan) karena itu lalu mereka tidak mau beriman kepada Alquran.",[["أَمْ","Or"],["تَسْـَٔلُهُمْ","you ask them"],["أَجْرًۭا","a payment"],["فَهُم","so they"],["مِّن","from"],["مَّغْرَمٍۢ","(the) debt"],["مُّثْقَلُونَ","(are) burdened"]]],"5318":["(Ataukah ada pada mereka ilmu tentang yang gaib) yaitu mengenai apa yang tertulis di Lohmahfuz (lalu mereka menulis) daripadanya apa yang mereka katakan itu.",[["أَمْ","Or"],["عِندَهُمُ","(is) with them"],["ٱلْغَيْبُ","the unseen"],["فَهُمْ","so they"],["يَكْتُبُونَ","write it"]]],"5319":["(Maka bersabarlah kamu terhadap ketetapan Rabbmu) terhadap mereka, sesuai dengan apa yang dikehendaki-Nya (dan janganlah kamu seperti orang yang berada dalam perut ikan paus) dalam hal ketergesa-gesaannya dan ketidaksabarannya, yaitu sebagaimana Nabi Yunus a.s. (ketika ia berdoa) kepada Rabbnya (sedangkan ia dalam keadaan marah) terhadap kaumnya, hatinya penuh dengan kemarahan sewaktu ia berada di dalam perut ikan besar itu.",[["فَٱصْبِرْ","So be patient"],["لِحُكْمِ","for (the) decision"],["رَبِّكَ","(of) your Lord"],["وَلَا","and (do) not"],["تَكُن","be"],["كَصَاحِبِ","like (the) companion"],["ٱلْحُوتِ","(of) the fish"],["إِذْ","when"],["نَادَىٰ","he called out"],["وَهُوَ","while he"],["مَكْظُومٌۭ","(was) distressed"]]],"5320":["(Kalau sekiranya ia tidak segera mendapat) tidak segera disusul oleh (nikmat) yakni rahmat (dari Rabbnya, benar-benar ia dicampakkan) dari perut ikan besar itu (ke tanah yang tandus) tanah yang tidak ada tumbuh-tumbuhannya (dalam keadaan tercela) akan tetapi Allah mengasihaninya sehingga ia dicampakkan tidak dalam keadaan tercela.",[["لَّوْلَآ","If not"],["أَن","that"],["تَدَٰرَكَهُۥ","overtook him"],["نِعْمَةٌۭ","a Favor"],["مِّن","from"],["رَّبِّهِۦ","his Lord"],["لَنُبِذَ","surely he would have been thrown"],["بِٱلْعَرَآءِ","onto (the) naked shore"],["وَهُوَ","while he"],["مَذْمُومٌۭ","(was) blamed"]]],"5321":["(Lalu Rabbnya memilihnya) memberinya kenabian (dan menjadikannya termasuk orang-orang yang saleh) yakni sebagian dari para nabi.",[["فَٱجْتَبَـٰهُ","But chose him"],["رَبُّهُۥ","his Lord"],["فَجَعَلَهُۥ","and made him"],["مِنَ","of"],["ٱلصَّـٰلِحِينَ","the righteous"]]],"5322":["(Dan sesungguhnya orang-orang kafir itu benar-benar hampir menggelincirkan kamu) dapat dibaca layuzliquunaka dan layazliquunaka (dengan pandangan mereka) mereka memandangmu dengan pandangan yang sangat tajam, sehingga pandangannya hampir-hampir membuatmu pingsan dan menjatuhkanmu dari tempat atau kedudukanmu (tatkala mereka mendengar peringatan) yakni Alquran (dan mereka berkata) karena dengki, (\"Sesungguhnya ia benar-benar orang gila.\") Mereka dengki karena Alquran yang diturunkan kepadanya itu.",[["وَإِن","And indeed"],["يَكَادُ","would almost"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["لَيُزْلِقُونَكَ","surely make you slip"],["بِأَبْصَـٰرِهِمْ","with their look"],["لَمَّا","when"],["سَمِعُوا۟","they hear"],["ٱلذِّكْرَ","the Message"],["وَيَقُولُونَ","and they say"],["إِنَّهُۥ","Indeed, he"],["لَمَجْنُونٌۭ","(is) surely mad"]]],"5323":["(Dan tidak lain dia) yakni Alquran itu (hanyalah peringatan) pelajaran (bagi seluruh umat) yaitu jin dan manusia, dan tiada menimbulkan kegilaan disebabkannya.",[["وَمَا","And not"],["هُوَ","it (is)"],["إِلَّا","but"],["ذِكْرٌۭ","a Reminder"],["لِّلْعَـٰلَمِينَ","to the worlds"]]],"5324":["(Hari yang benar) yaitu hari kiamat, dikatakan demikian karena pada hari itu dibenarkan hal-hal yang diingkari, seperti mengenai adanya hari kebangkitan, hari hisab dan hari pembalasan. Atau dinamakan demikian karena pada hari itu ditampakkan kepada mereka hal-hal tersebut.",[["ٱلْحَآقَّةُ","The Inevitable Reality"]]],"5325":["(Apakah hari yang benar itu) ungkapan ini mengandung makna yang menggambarkan tentang keagungan hari kiamat; dan berkedudukan sebagai mubtada yang sekaligus sebagai khabar dari lafal al-haaqqah yang pertama.",[["مَا","What"],["ٱلْحَآقَّةُ","(is) the Inevitable Reality"]]],"5326":["(Dan tahukah kamu) sudah tahukah kamu (apakah hari yang benar itu?) ungkapan ini menambah keagungan hari kiamat. Maa yang pertama menjadi mubtada sedangkan maa yang kedua menjadi khabarnya. Dan maa yang kedua berikut khabarnya berkedudukan sebagai maf'ul kedua dari lafal adraa.",[["وَمَآ","And what"],["أَدْرَىٰكَ","will make you know"],["مَا","what"],["ٱلْحَآقَّةُ","(is) the Inevitable Reality"]]],"5327":["(Kaum Tsamud dan kaum 'Ad telah mendustakan hari yang menggentarkan) yakni hari kiamat, hari kiamat dinamakan demikian karena kedahsyatan dan kengerian yang terjadi pada hari itu sangat menggentarkan hati.",[["كَذَّبَتْ","Denied"],["ثَمُودُ","Thamud"],["وَعَادٌۢ","and Aad"],["بِٱلْقَارِعَةِ","the Striking Calamity"]]],"5328":["(Adapun kaum Tsamud, maka mereka telah dibinasakan dengan teriakan yang dahsyat) teriakan yang kerasnya melampaui batas.",[["فَأَمَّا","So as for"],["ثَمُودُ","Thamud"],["فَأُهْلِكُوا۟","they were destroyed"],["بِٱلطَّاغِيَةِ","by the overpowering (blast)"]]],"5329":["(Adapun kaum Ad maka mereka telah dibinasakan dengan angin yang sangat keras) sangat keras suaranya (lagi amat kuat) kuat lagi keras; angin tersebut ditimpakan atas kaum Ad, sekalipun mereka kuat lagi keras tetapi menghadapi angin ini mereka tidak berarti apa-apa.",[["وَأَمَّا","And as for"],["عَادٌۭ","Aad"],["فَأُهْلِكُوا۟","they were destroyed"],["بِرِيحٍۢ","by a wind"],["صَرْصَرٍ","screaming"],["عَاتِيَةٍۢ","violent"]]],"5330":["(Yang Allah tundukkan angin itu) artinya Allah mengirimkannya dengan kekuasaan-Nya (kepada mereka selama tujuh malam dan delapan hari) dimulai pada pagi hari Rabu, tanggal dua puluh dua bulan Syawal; angin itu terjadi di pertengahan musim dingin (terus-menerus) atau secara berturut-turut. Keadaan angin itu diserupakan dengan pekerjaan yang dilakukan oleh tukang setrika, yaitu sewaktu ia mengulang-ulang setrikaannya pada penyakit yang diobatinya. Yakni, ia mengulang-ulanginya dari satu waktu ke waktu yang lainnya hingga penyakitnya lenyap sama sekali (maka kamu lihat kaum 'Ad pada waktu itu mati bergelimpangan) mereka tercampakkan ke dalam keadaan binasa (seakan-akan mereka batang) pokok (pohon kurma yang lapuk) yang jatuh karena keropos atau lapuk.",[["سَخَّرَهَا","Which He imposed"],["عَلَيْهِمْ","upon them"],["سَبْعَ","(for) seven"],["لَيَالٍۢ","nights"],["وَثَمَـٰنِيَةَ","and eight"],["أَيَّامٍ","days"],["حُسُومًۭا","(in) succession"],["فَتَرَى","so you would see"],["ٱلْقَوْمَ","the people"],["فِيهَا","therein"],["صَرْعَىٰ","fallen"],["كَأَنَّهُمْ","as if they were"],["أَعْجَازُ","trunks"],["نَخْلٍ","(of) date-palms"],["خَاوِيَةٍۢ","hollow"]]],"5331":["(Maka apakah kamu melihat bekas-bekas mereka?) lafal baaqiyah adalah sifat dari lafal nafsin yang diperkirakan keberadaannya; yaitu apakah kamu melihat seseorang pun yang tinggal di antara mereka? Atau lafal baaqiyah ini huruf ta-nya untuk menunjukkan makna mubalaghah, yakni bekas-bekasnya? Tentu saja tidak.",[["فَهَلْ","Then do"],["تَرَىٰ","you see"],["لَهُم","of them"],["مِّنۢ","any"],["بَاقِيَةٍۢ","remains"]]],"5332":["(Dan telah datang Firaun dan orang-orang yang mengikutinya) beserta para pengikutnya. Menurut suatu qiraat, lafal qabilahu dibaca qablahu sehingga artinya, orang-orang kafir yang sebelumnya (dan negeri-negeri yang dijungkirbalikkan) penduduknya dijungkirbalikkan berikut negeri-negeri tempat tinggal mereka; yang dimaksud adalah negeri-negeri tempat tinggal kaum Nabi Luth (karena kesalahan yang besar) karena mereka mengerjakan perbuatan-perbuatan dosa besar.",[["وَجَآءَ","And came"],["فِرْعَوْنُ","Firaun"],["وَمَن","and (those)"],["قَبْلَهُۥ","before him"],["وَٱلْمُؤْتَفِكَـٰتُ","and the overturned cities"],["بِٱلْخَاطِئَةِ","with sin"]]],"5333":["(Maka masing-masing mereka mendurhakai rasul Rabb mereka) mendurhakai Nabi Luth dan nabi-nabi lainnya (lalu Allah menyiksa mereka dengan siksaan yang sangat keras) siksaan yang lebih keras daripada siksaan-siksaan lainnya.",[["فَعَصَوْا۟","And they disobeyed"],["رَسُولَ","(the) Messenger"],["رَبِّهِمْ","(of) their Lord"],["فَأَخَذَهُمْ","so He seized them"],["أَخْذَةًۭ","(with) a seizure"],["رَّابِيَةً","exceeding"]]],"5334":["(Sesungguhnya Kami tatkala air naik) naik ke atas, sehingga segala sesuatu termasuk gunung-gunung dan lain-lainnya semuanya tenggelam yaitu, pada masa banjir besar (Kami bawa kalian) bapak moyang kalian, karena kalian pada zaman itu masih berada di dalam tulang sulbi mereka (ke dalam bahtera) atau perahu yang dibuat oleh Nabi Nuh. Akhirnya, selamatlah Nabi Nuh beserta orang-orang yang beriman bersamanya yang berada di dalam bahtera itu, sedangkan yang lainnya semua mati tenggelam.",[["إِنَّا","Indeed, We"],["لَمَّا","when"],["طَغَا","overflowed"],["ٱلْمَآءُ","the water"],["حَمَلْنَـٰكُمْ","We carried you"],["فِى","in"],["ٱلْجَارِيَةِ","the sailing (ship)"]]],"5335":["(Agar Kami jadikan peristiwa itu) atau perbuatan ini, yaitu diselamatkan-Nya orang-orang yang beriman dan ditenggelamkan-Nya orang-orang yang kafir (peringatan bagi kalian) pelajaran (dan agar diperhatikan) supaya hal itu tetap diingat (oleh telinga yang mau mendengar) mau menerima apa yang didengarnya.",[["لِنَجْعَلَهَا","That We might make it"],["لَكُمْ","for you"],["تَذْكِرَةًۭ","a reminder"],["وَتَعِيَهَآ","and would be conscious of it"],["أُذُنٌۭ","an ear"],["وَٰعِيَةٌۭ","conscious"]]],"5336":["(Maka apabila sangkakala ditiup sekali tiup) yaitu, untuk tiupan yang kedua kalinya, sebagai pemula untuk dijalankannya peradilan di antara semua makhluk.",[["فَإِذَا","Then when"],["نُفِخَ","is blown"],["فِى","in"],["ٱلصُّورِ","the trumpet "],["نَفْخَةٌۭ","a blast"],["وَٰحِدَةٌۭ","single"]]],"5337":["(Dan diangkatlah) diangkatlah ke atas (bumi dan gunung-gunung, lalu dibenturkan keduanya) diadukan (sekali bentur.)",[["وَحُمِلَتِ","And are lifted"],["ٱلْأَرْضُ","the earth"],["وَٱلْجِبَالُ","and the mountains"],["فَدُكَّتَا","and crushed"],["دَكَّةًۭ","(with) a crushing"],["وَٰحِدَةًۭ","single"]]],"5338":["(Maka pada hari itu terjadilah hari kiamat) yakni hari terakhir.",[["فَيَوْمَئِذٍۢ","Then (on) that Day"],["وَقَعَتِ","will occur"],["ٱلْوَاقِعَةُ","the Occurrence"]]],"5339":["(Dan terbelahlah langit, karena pada hari itu langit menjadi lemah) melemah.",[["وَٱنشَقَّتِ","And will split"],["ٱلسَّمَآءُ","the heaven"],["فَهِىَ","so it"],["يَوْمَئِذٍۢ","(is on) that Day"],["وَاهِيَةٌۭ","frail"]]],"5340":["(Dan malaikat-malaikat) lafal al-malaku adalah bentuk jamak dari lafal malaa'ikah, artinya malaikat-malaikat (berada di penjuru-penjuru langit) berada di seantero langit. (Dan diangkatlah Arasy Rabbmu di atas mereka) oleh malaikat-malaikat tersebut (pada hari itu yang jumlahnya ada delapan malaikat) ada delapan malaikat atau delapan barisan malaikat.",[["وَٱلْمَلَكُ","And the Angels"],["عَلَىٰٓ","(will be) on"],["أَرْجَآئِهَا ۚ","its edges"],["وَيَحْمِلُ","and will bear"],["عَرْشَ","(the) Throne"],["رَبِّكَ","(of) your Lord"],["فَوْقَهُمْ","above them"],["يَوْمَئِذٍۢ","that Day"],["ثَمَـٰنِيَةٌۭ","eight"]]],"5341":["(Pada hari itu kalian dihadapkan) untuk menjalani hisab (tiada yang tersembunyi) dapat dibaca laa takhfaa dan laa yakhfaa (dari keadaan kalian barang sedikit pun) yaitu dari hal-hal yang kalian rahasiakan.",[["يَوْمَئِذٍۢ","That Day"],["تُعْرَضُونَ","you will be exhibited"],["لَا","not"],["تَخْفَىٰ","will be hidden"],["مِنكُمْ","among you"],["خَافِيَةٌۭ","any secret"]]],"5342":["(Adapun orang-orang yang diberikan kepadanya kitabnya dari sebelah kanannya, maka dia berkata) kepada golongannya untuk mengetahui apa yang dia rahasiakan: (\"Ambillah) terimalah (bacalah kitabku ini.\") Di dalam ungkapan ini terdapat perselisihan pendapat, manakah di antara lafal haa-umu dan iqra`uu yang menjadi amil dari lafal kitabiyah ini?",[["فَأَمَّا","Then as for"],["مَنْ","(him) who"],["أُوتِىَ","is given"],["كِتَـٰبَهُۥ","his record"],["بِيَمِينِهِۦ","in his right hand"],["فَيَقُولُ","will say"],["هَآؤُمُ","Here"],["ٱقْرَءُوا۟","read"],["كِتَـٰبِيَهْ","my record"]]],"5343":["(\"Sesungguhnya aku yakin) aku telah merasa yakin (bahwa sesungguhnya aku akan menemui hisab terhadap diriku.\")",[["إِنِّى","Indeed, I"],["ظَنَنتُ","was certain"],["أَنِّى","that I"],["مُلَـٰقٍ","(will) meet"],["حِسَابِيَهْ","my account"]]],"5344":["(Maka orang itu berada dalam kehidupan yang diridai) lafal raadhiyah berarti mardhiyah, artinya diridai.",[["فَهُوَ","So he"],["فِى","(will be) in"],["عِيشَةٍۢ","a life"],["رَّاضِيَةٍۢ","pleasant"]]],"5345":["(Dalam surga yang tinggi.)",[["فِى","In"],["جَنَّةٍ","a Garden"],["عَالِيَةٍۢ","elevated"]]],"5346":["(Buah-buahannya) buah-buahan yang dipetiknya (dekat) sangat dekat yaitu dapat dicapai oleh orang yang berdiri, orang yang duduk, dan malah orang yang berbaring.",[["قُطُوفُهَا","Its clusters of fruits"],["دَانِيَةٌۭ","hanging near"]]],"5347":["Maka dikatakan kepada mereka: (\"Makan dan minumlah dengan nyaman) lafal hanii'an berkedudukan sebagai hal, dengan sedap (disebabkan amal yang telah kalian kerjakan pada hari-hari yang telah lalu\") sewaktu kalian di dunia.",[["كُلُوا۟","Eat"],["وَٱشْرَبُوا۟","and drink"],["هَنِيٓـًٔۢا","(in) satisfaction"],["بِمَآ","for what"],["أَسْلَفْتُمْ","you sent before you"],["فِى","in"],["ٱلْأَيَّامِ","the days"],["ٱلْخَالِيَةِ","past"]]],"5348":["(Adapun orang-orang yang diberikan kepadanya kitabnya dari sebelah kirinya, maka dia berkata, \"Aduhai) wahai; lafal ya di sini menunjukkan makna tanbih (alangkah baiknya kiranya tidak diberikan kepadaku kitabku.)",[["وَأَمَّا","But as for"],["مَنْ","(him) who"],["أُوتِىَ","is given"],["كِتَـٰبَهُۥ","his record"],["بِشِمَالِهِۦ","in his left hand"],["فَيَقُولُ","will say"],["يَـٰلَيْتَنِى","O! I wish"],["لَمْ","not"],["أُوتَ","I had been given"],["كِتَـٰبِيَهْ","my record"]]],"5349":["(Dan aku tidak mengetahui apa hisab terhadap diriku.)",[["وَلَمْ","And not"],["أَدْرِ","I had known"],["مَا","what"],["حِسَابِيَهْ","(is) my account"]]],"5350":["(Wahai kiranya kematian itulah) kematian di dunia (yang menyelesaikan segala sesuatu.) Yang memutuskan hidupku dan tidak akan dibangkitkan lagi.",[["يَـٰلَيْتَهَا","O! I wish it"],["كَانَتِ","had been"],["ٱلْقَاضِيَةَ","the end"]]],"5351":["(Hartaku sekali-kali tidak memberi manfaat kepadaku.)",[["مَآ","Not"],["أَغْنَىٰ","has availed"],["عَنِّى","me"],["مَالِيَهْ ۜ","my wealth"]]],"5352":["(Telah hilang kekuasaanku dariku\") kekuatanku dan argumentasi atau hujahku. Huruf Ha yang terdapat dalam lafal kitabiyah, hisabiyah, maliyah, dan sulthaniyah, semuanya adalah ha saktah yang tetap dibaca baik dalam keadaan Waqaf maupun dalam keadaan Washal. Demikian itu karena mengikut mushhaf imam/induk dan karena mengikut dalil naqli. Akan tetapi sekali pun demikian, ada pula sebagian ulama yang tidak membacakannya bila diwashalkan.",[["هَلَكَ","Is gone"],["عَنِّى","from me"],["سُلْطَـٰنِيَهْ","my authority"]]],"5353":["(\"Peganglah dia) khithab atau perintah dalam ayat ini ditujukan kepada para malaikat penjaga neraka Jahanam (lalu belenggulah dia.\") Ikatlah kedua tangannya menjadi satu dengan kepalanya ke dalam belenggu.",[["خُذُوهُ","Seize him"],["فَغُلُّوهُ","and shackle him"]]],"5354":["(\"Kemudian ke dalam neraka Jahanam) neraka yang apinya menyala-nyala (masukkanlah dia\") jebloskanlah dia ke dalamnya.",[["ثُمَّ","Then"],["ٱلْجَحِيمَ","(into) the Hellfire"],["صَلُّوهُ","burn him"]]],"5355":["(\"Kemudian dengan rantai yang panjangnya tujuh puluh hasta) menurut ukuran hasta malaikat (belitlah dia\") lilitlah dia dengan rantai itu sesudah ia dimasukkan ke dalam neraka. Huruf fa di sini tidak dapat mencegah hubungan antara fi'il dan zharaf yang mendahuluinya.",[["ثُمَّ","Then"],["فِى","into"],["سِلْسِلَةٍۢ","a chain"],["ذَرْعُهَا","its length"],["سَبْعُونَ","(is) seventy"],["ذِرَاعًۭا","cubits"],["فَٱسْلُكُوهُ","insert him"]]],"5356":["(\"Sesungguhnya dia dahulu tidak beriman kepada Allah Yang Maha Besar.\")",[["إِنَّهُۥ","Indeed, he"],["كَانَ","was"],["لَا","not"],["يُؤْمِنُ","believing"],["بِٱللَّهِ","in Allah"],["ٱلْعَظِيمِ","the Most Great"]]],"5357":["(\"Dan juga dia tidak mendorong untuk memberi makan orang miskin.\")",[["وَلَا","And (did) not"],["يَحُضُّ","feel the urge"],["عَلَىٰ","on"],["طَعَامِ","(the) feeding"],["ٱلْمِسْكِينِ","(of) the poor"]]],"5358":["(Maka tiada seorang teman pun baginya pada hari ini di sini) maksudnya, pada hari ini tiada kaum kerabat yang bermanfaat bagi dirinya.",[["فَلَيْسَ","So not"],["لَهُ","for him"],["ٱلْيَوْمَ","today"],["هَـٰهُنَا","here"],["حَمِيمٌۭ","any devoted friend"]]],"5359":["(Dan tiada pula makanan sedikit pun baginya kecuali dari darah dan nanah) yaitu nanah dan darah ahli neraka, atau shadiid, yaitu nama sejenis pohon yang ada di dalam neraka.",[["وَلَا","And not"],["طَعَامٌ","any food"],["إِلَّا","except"],["مِنْ","from"],["غِسْلِينٍۢ","(the) discharge of wounds"]]],"5360":["(Tidak ada yang memakannya kecuali orang-orang yang berdosa) orang-orang yang kafir.",[["لَّا","Not"],["يَأْكُلُهُۥٓ","will eat it"],["إِلَّا","except"],["ٱلْخَـٰطِـُٔونَ","the sinners"]]],"5361":["(Maka) huruf laa di sini adalah huruf zaidah (Aku bersumpah dengan apa yang kalian lihat) makhluk-makhluk yang kalian lihat.",[["فَلَآ","But nay"],["أُقْسِمُ","I swear"],["بِمَا","by what"],["تُبْصِرُونَ","you see"]]],"5362":["(Dan dengan apa yang tidak kalian lihat) di antara makhluk-makhluk itu.",[["وَمَا","And what"],["لَا","not"],["تُبْصِرُونَ","you see"]]],"5363":["(Sesungguhnya dia) yakni Alquran itu (adalah benar-benar perkataan utusan yang mulia) yang disampaikan oleh malaikat Jibril dari Allah swt.",[["إِنَّهُۥ","Indeed, it (is)"],["لَقَوْلُ","surely (the) Word"],["رَسُولٍۢ","(of) a Messenger"],["كَرِيمٍۢ","noble"]]],"5364":["(Dan Alquran itu bukanlah perkataan seorang penyair. Sedikit sekali kalian beriman kepadanya.)",[["وَمَا","And not"],["هُوَ","it"],["بِقَوْلِ","(is the) word"],["شَاعِرٍۢ ۚ","(of) a poet"],["قَلِيلًۭا","little"],["مَّا","(is) what"],["تُؤْمِنُونَ","you believe"]]],"5365":["(Dan bukan pula perkataan tukang tenung. Sedikit sekali kalian mengambil pelajaran darinya) lafal tu'minuuna pada ayat di atas dan lafal tadzakkaruuna, kedua-duanya dapat pula dibaca yu'minuuna dan yadzakkaruuna. Huruf maa-nya merupakan huruf zaidah yang berfungsi mengukuhkan makna. Makna ayat, bahwasanya mereka itu hanya beriman kepada hal-hal yang sedikit sekali, dan mereka pun hanya ingat sedikit tentang hal-hal yang didatangkan oleh Nabi saw. yaitu berupa kebaikan, silaturahmi, dan memelihara kehormatan. Maka hal-hal tersebut tiada memberi manfaat kepada mereka barang sedikit pun.",[["وَلَا","And not"],["بِقَوْلِ","(it is the) word"],["كَاهِنٍۢ ۚ","(of) a soothsayer"],["قَلِيلًۭا","little"],["مَّا","(is) what"],["تَذَكَّرُونَ","you take heed"]]],"5366":["Bahkan Alquran itu (diturunkan dari Rabb semesta alam.)",[["تَنزِيلٌۭ","(It is) a revelation"],["مِّن","from"],["رَّبِّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"5367":["(Seandainya dia mengada-adakan) yakni Nabi Muhammad (sebagian perkataan atas nama Kami) seumpamanya dia mengatakan dari Kami, padahal Kami tidak pernah mengatakannya.",[["وَلَوْ","And if"],["تَقَوَّلَ","he (had) fabricated"],["عَلَيْنَا","against Us"],["بَعْضَ","some"],["ٱلْأَقَاوِيلِ","sayings"]]],"5368":["(Niscaya benar-benar Kami pegang) niscaya Kami tangkap (dia) sebagai hukuman baginya (dengan kekuatan) dan kekuasaan-Ku.",[["لَأَخَذْنَا","Certainly We (would) have seized"],["مِنْهُ","him"],["بِٱلْيَمِينِ","by the right hand"]]],"5369":["(Kemudian benar-benar Kami potong urat tali jantungnya) yang apabila urat itu terputus maka orang itu akan mati.",[["ثُمَّ","Then"],["لَقَطَعْنَا","certainly We (would) have cut off"],["مِنْهُ","from him"],["ٱلْوَتِينَ","the aorta"]]],"5370":["(Maka sekali-kali tidak ada seorang pun dari kalian) lafal min ahadin adalah isimnya maa, sedangkan huruf min adalah huruf zaidah yang mengandung makna mengukuhkan kenafiannya. Dan lafal minkum adalah hal dari lafal ahadin (yang dapat menghalang-halangi Kami daripadanya) tiada seorang pun yang dapat mencegah-Ku daripadanya. Lafal haajiziina adalah khabar dari maa, dan ia dijamakkan karena lafal ahadan di dalam konteks nafi yang maknanya mengandung pengertian jamak. Dan dhamir yang terdapat di dalam lafal `anhu merujuk kepada Nabi saw.; yakni tiada seorang pun yang dapat mencegah Kami dari hukumannya.",[["فَمَا","And not"],["مِنكُم","from you"],["مِّنْ","any"],["أَحَدٍ","one"],["عَنْهُ","[from him]"],["حَـٰجِزِينَ","(who could) prevent (it)"]]],"5371":["(Dan sesungguhnya dia itu) Alquran itu (benar-benar suatu pelajaran bagi orang-orang yang bertakwa.)",[["وَإِنَّهُۥ","And indeed, it"],["لَتَذْكِرَةٌۭ","(is) surely a reminder"],["لِّلْمُتَّقِينَ","for the Allah-fearing"]]],"5372":["(Dan sesungguhnya Kami benar-benar mengetahui, bahwa di antara kalian) hai manusia (ada orang-orang yang mendustakan) Alquran dan ada pula yang mempercayainya.",[["وَإِنَّا","And indeed, We"],["لَنَعْلَمُ","surely know"],["أَنَّ","that"],["مِنكُم","among you"],["مُّكَذِّبِينَ","(are) deniers"]]],"5373":["(Dan sesungguhnya dia itu) Alquran itu (menjadi penyesalan bagi orang-orang kafir) di saat mereka melihat pahala yang diterima oleh orang-orang yang beriman kepadanya, dan hukuman yang diterima oleh orang-orang yang mendustakannya.",[["وَإِنَّهُۥ","And indeed, it"],["لَحَسْرَةٌ","(is) surely a regret"],["عَلَى","upon"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"5374":["(Dan sesungguhnya dia itu) Alquran itu (benar-benar perkara hak yang diyakini) atau keyakinan yang hak.",[["وَإِنَّهُۥ","And indeed, it (is)"],["لَحَقُّ","surely (the) truth"],["ٱلْيَقِينِ","(of) certainty"]]],"5375":["(Maka bertasbihlah) sucikanlah Dia (dengan menyebut nama) huruf ba di sini adalah huruf zaidah (Rabbmu Yang Maha Besar) Maha Suci Dia.",[["فَسَبِّحْ","So glorify"],["بِٱسْمِ","(the) name"],["رَبِّكَ","(of) your Lord"],["ٱلْعَظِيمِ","the Most Great"]]],"5376":["(Seseorang telah meminta) yakni berdoa meminta (kedatangan azab yang akan menimpa.)",[["سَأَلَ","Asked"],["سَآئِلٌۢ","a questioner"],["بِعَذَابٍۢ","about a punishment"],["وَاقِعٍۢ","bound to happen"]]],"5377":["(Untuk orang-orang kafir, yang tidak seorang pun dapat menolaknya) dia adalah Nadhr bin Haris, ia mengatakan di dalam permintaannya, sebagaimana yang disitir oleh firman-Nya, \"Ya Allah, jika betul (Alquran) ini, dialah yang benar dari sisi Engkau...\" (Q.S. Al-Anfal 32)",[["لِّلْكَـٰفِرِينَ","To the disbelievers"],["لَيْسَ","not"],["لَهُۥ","of it"],["دَافِعٌۭ","any preventer"]]],"5378":["(Yang datang dari Allah) lafal minallaah ini berkaitan erat dengan lafal Waaqi' yang ada di akhir ayat pertama (yang mempunyai tempat-tempat naik) tempat-tempat naik bagi para malaikat, yaitu langit.",[["مِّنَ","From"],["ٱللَّهِ","Allah"],["ذِى","Owner"],["ٱلْمَعَارِجِ","(of) the ways of ascent"]]],"5379":["(Naiklah) dapat dibaca ta`ruju dan ya`ruju (malaikat-malaikat dan Jibril) Malaikat Jibril (kepada-Nya) kepada tempat turun bagi perintah-Nya di langit (dalam sehari) lafal fii yaumin bertaalluq kepada lafal yang tidak disebutkan, azab menimpa orang-orang kafir pada hari kiamat (yang kadarnya lima puluh ribu tahun) ini menurut apa yang dirasakan oleh orang kafir, karena penderitaan dan kesengsaraan yang mereka temui di hari itu. Adapun orang yang beriman merasakan hal itu amat pendek, bahkan lebih pendek daripada satu kali salat fardu yang dilakukan sewaktu di dunia. Demikianlah menurut keterangan yang disebutkan di dalam hadis.",[["تَعْرُجُ","Ascend"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["وَٱلرُّوحُ","and the Spirit"],["إِلَيْهِ","to Him"],["فِى","in"],["يَوْمٍۢ","a Day"],["كَانَ","[is]"],["مِقْدَارُهُۥ","its measure"],["خَمْسِينَ","(is) fifty"],["أَلْفَ","thousand"],["سَنَةٍۢ","year(s)"]]],"5380":["(Maka bersabarlah kamu) ayat ini diturunkan sebelum ada perintah berperang (dengan sabar yang baik) sabar yang tidak disertai dengan gelisah.",[["فَٱصْبِرْ","So be patient"],["صَبْرًۭا","a patience"],["جَمِيلًا","good"]]],"5381":["(Sesungguhnya mereka memandangnya) memandang azab itu (jauh) artinya mustahil akan terjadi.",[["إِنَّهُمْ","Indeed, they"],["يَرَوْنَهُۥ","see it"],["بَعِيدًۭا","(as) far off"]]],"5382":["(Sedangkan Kami memandangnya dekat) pasti terjadi.",[["وَنَرَىٰهُ","But We see it"],["قَرِيبًۭا","near"]]],"5383":["(Pada hari ketika langit) lafal ayat ini bertaalluq kepada lafal yang tidak disebutkan, yaitu azab itu terjadi pada hari ketika langit (menjadi seperti luluhan perak) seperti leburan perak.",[["يَوْمَ","(The) Day "],["تَكُونُ","will be"],["ٱلسَّمَآءُ","the sky"],["كَٱلْمُهْلِ","like molten copper"]]],"5384":["(Dan gunung-gunung menjadi seperti bulu) maksudnya bagaikan bulu domba ringannya, terbawa terbang oleh angin.",[["وَتَكُونُ","And will be"],["ٱلْجِبَالُ","the mountains"],["كَٱلْعِهْنِ","like wool"]]],"5385":["(Dan tidak ada seorang teman akrab pun menanyakan temannya) tiada karib kerabat yang menanyakan kerabatnya, karena pada hari itu masing-masing orang disibukkan oleh keadaannya sendiri.",[["وَلَا","And not"],["يَسْـَٔلُ","will ask"],["حَمِيمٌ","a friend"],["حَمِيمًۭا","(about) a friend"]]],"5386":["(Sedangkan mereka saling melihat) sebagian teman-teman akrab itu saling melihat kepada sebagian yang lain, dan mereka saling mengenal antara yang satu dengan yang lainnya akan tetapi mereka tiada berkata barang sepatah pun. Jumlah ayat ini merupakan kalimat baru atau jumlah isti'naf. (Orang kafir ingin) ia berharap (kalau sekiranya) lafal lau di sini bermakna an, yakni bahwasanya (dia dapat menebus dirinya dari azab hari itu) dapat dibaca yaumi'idzin dan yauma'idzin (dengan anak-anaknya.)",[["يُبَصَّرُونَهُمْ ۚ","They will be made to see each other"],["يَوَدُّ","Would wish"],["ٱلْمُجْرِمُ","the criminal"],["لَوْ","if"],["يَفْتَدِى","he (could be) ransomed"],["مِنْ","from"],["عَذَابِ","(the) punishment"],["يَوْمِئِذٍۭ","(of) that Day"],["بِبَنِيهِ","by his children"]]],"5387":["(Dan istrinya) atau teman hidupnya (dan saudaranya.)",[["وَصَـٰحِبَتِهِۦ","And his spouse"],["وَأَخِيهِ","and his brother"]]],"5388":["(Dan kaum familinya) atau famili-familinya, mereka dinamakan fashiilah karena orang yang bersangkutan terpisah hubungannya dengan mereka (yang melindunginya) yang pernah mengasuhnya.",[["وَفَصِيلَتِهِ","And his nearest kindred"],["ٱلَّتِى","who"],["تُـْٔوِيهِ","sheltered him"]]],"5389":["(Dan orang-orang di atas bumi seluruhnya, kemudian mengharapkan tebusan itu dapat menyelamatkannya) dapat membebaskannya dari azab itu. Lafal ayat ini diathafkan kepada lafal yaftadii.",[["وَمَن","And whoever"],["فِى","(is) on"],["ٱلْأَرْضِ","the earth"],["جَمِيعًۭا","all"],["ثُمَّ","then"],["يُنجِيهِ","it (could) save him"]]],"5390":["(Sekali-kali tidak dapat) lafal ini merupakan sanggahan terhadap apa yang dia harapkan itu (sesungguhnya neraka ini) neraka yang mereka saksikan itu (adalah api yang bergejolak) lafal lazhaa adalah nama lain dari neraka Jahanam, dinamakan demikian karena apinya bergejolak membakar orang-orang kafir.",[["كَلَّآ ۖ","By no means"],["إِنَّهَا","Indeed, it (is)"],["لَظَىٰ","surely a Flame of Hell"]]],"5391":["(Yang mengelupaskan kulit kepala) asy-syawaa bentuk jamak dari lafal syawaatun, artinya kulit kepala.",[["نَزَّاعَةًۭ","A remover"],["لِّلشَّوَىٰ","of the skin of the head"]]],"5392":["(Yang memanggil orang yang membelakang dan yang berpaling) dari iman; sebab neraka Jahanam itu mengatakan kepada mereka kemarilah, kemarilah.",[["تَدْعُوا۟","Inviting"],["مَنْ","(him) who"],["أَدْبَرَ","turned his back"],["وَتَوَلَّىٰ","and went away"]]],"5393":["(Serta mengumpulkan) harta (lalu menyimpannya) menaruhnya di dalam peti simpanan dan tidak menunaikan hak Allah yang ada pada harta bendanya itu.",[["وَجَمَعَ","And collected"],["فَأَوْعَىٰٓ","and hoarded"]]],"5394":["(Sesungguhnya manusia diciptakan bersifat keluh-kesah) lafal haluu`an merupakan hal atau kata keterangan keadaan dari lafal yang tidak disebutkan, dan sekaligus sebagai penafsirnya.",[["۞ إِنَّ","Indeed"],["ٱلْإِنسَـٰنَ","the man"],["خُلِقَ","was created"],["هَلُوعًا","anxious "]]],"5395":["(Apabila ia ditimpa kesusahan ia berkeluh kesah) atau sewaktu ia ditimpa keburukan berkeluh kesah.",[["إِذَا","When"],["مَسَّهُ","touches him"],["ٱلشَّرُّ","the evil"],["جَزُوعًۭا","distressed"]]],"5396":["(Dan apabila ia mendapat kebaikan ia amat kikir) sewaktu ia mendapat harta benda ia kikir, tidak mau menunaikan hak Allah yang ada pada hartanya itu.",[["وَإِذَا","And when"],["مَسَّهُ","touches him"],["ٱلْخَيْرُ","the good"],["مَنُوعًا","withholding"]]],"5397":["(Kecuali orang-orang yang mengerjakan salat) yakni, orang-orang yang beriman.",[["إِلَّا","Except"],["ٱلْمُصَلِّينَ","those who pray "]]],"5398":["(Yang mereka itu tetap mengerjakan salatnya) terus-menerus mengerjakannya.",[["ٱلَّذِينَ","Those who"],["هُمْ","[they]"],["عَلَىٰ","at"],["صَلَاتِهِمْ","their prayer"],["دَآئِمُونَ","(are) constant"]]],"5399":["(Dan orang-orang yang dalam hartanya tersedia bagian tertentu) yakni zakat.",[["وَٱلَّذِينَ","And those who"],["فِىٓ","in"],["أَمْوَٰلِهِمْ","their wealth"],["حَقٌّۭ","(is) a right"],["مَّعْلُومٌۭ","known"]]],"5400":["(Bagi orang miskin yang meminta dan orang yang tidak mempunyai apa-apa) yang tidak mau meminta-minta, demi memelihara kehormatannya sekalipun ia tidak punya.",[["لِّلسَّآئِلِ","For the one who asks"],["وَٱلْمَحْرُومِ","and the deprived"]]],"5401":["(Dan orang-orang yang mempercayai hari pembalasan) yaitu, hari ketika semua orang mendapatkan balasan amal perbuatannya.",[["وَٱلَّذِينَ","And those who"],["يُصَدِّقُونَ","accept (the) truth"],["بِيَوْمِ","(of the) Day"],["ٱلدِّينِ","(of) the Judgment"]]],"5402":["(Dan orang-orang yang takut terhadap azab Rabbnya) mereka takut akan azab-Nya.",[["وَٱلَّذِينَ","And those who"],["هُم","[they]"],["مِّنْ","of"],["عَذَابِ","(the) punishment"],["رَبِّهِم","(of) their Lord"],["مُّشْفِقُونَ","(are) fearful "]]],"5403":["(Karena sesungguhnya azab Rabb mereka tidak dapat orang merasa aman) dari kedatangannya.",[["إِنَّ","Indeed"],["عَذَابَ","(the) punishment"],["رَبِّهِمْ","(of) your Lord"],["غَيْرُ","(is) not"],["مَأْمُونٍۢ","to be felt secure (of) "]]],"5404":["(Dan orang-orang yang memelihara kemaluannya.)",[["وَٱلَّذِينَ","And those who"],["هُمْ","[they]"],["لِفُرُوجِهِمْ","their modesty"],["حَـٰفِظُونَ","(are) guardians"]]],"5405":["(Kecuali terhadap istri-istri mereka atau budak-budak yang mereka miliki) yakni budak-budak perempuan (maka sesungguhnya mereka dalam hal ini tidak tercela.)",[["إِلَّا","Except"],["عَلَىٰٓ","from"],["أَزْوَٰجِهِمْ","their spouses"],["أَوْ","or"],["مَا","what"],["مَلَكَتْ","they possess"],["أَيْمَـٰنُهُمْ","rightfully"],["فَإِنَّهُمْ","then indeed, they"],["غَيْرُ","(are) not"],["مَلُومِينَ","blameworthy"]]],"5406":["(Barang siapa mencari yang di balik itu, maka mereka itulah orang-orang yang melampaui batas) melanggar batas kehalalan menuju kepada keharaman.",[["فَمَنِ","But whoever"],["ٱبْتَغَىٰ","seeks"],["وَرَآءَ","beyond"],["ذَٰلِكَ","that"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they]"],["ٱلْعَادُونَ","(are) the transgressors "]]],"5407":["(Dan orang-orang yang terhadap amanat-amanat mereka) menurut suatu qiraat lafal amaanaatihim dibaca dalam bentuk mufrad atau tunggal, sehingga bacaannya menjadi amaanatihim, yakni perkara agama dan duniawi yang dipercayakan kepadanya untuk menunaikannya (dan janji mereka) yang telah diambil dari mereka dalam hal tersebut (mereka memeliharanya) benar-benar menjaganya.",[["وَٱلَّذِينَ","And those who"],["هُمْ","[they]"],["لِأَمَـٰنَـٰتِهِمْ","of their trusts"],["وَعَهْدِهِمْ","and their promise"],["رَٰعُونَ","(are) observers"]]],"5408":["(Dan orang-orang yang terhadap kesaksiannya) menurut suatu qiraat dibaca dalam bentuk jamak, sehingga bacaannya menjadi syahaadaatihim (mereka menunaikannya) mereka menegakkannya dan tidak menyembunyikannya.",[["وَٱلَّذِينَ","And those who"],["هُم","[they]"],["بِشَهَـٰدَٰتِهِمْ","in their testimonies"],["قَآئِمُونَ","stand firm"]]],"5409":["(Dan orang-orang yang memelihara salatnya) yaitu dengan mengerjakan pada waktunya.",[["وَٱلَّذِينَ","And those who"],["هُمْ","[they]"],["عَلَىٰ","on"],["صَلَاتِهِمْ","their prayer"],["يُحَافِظُونَ","keep a guard "]]],"5410":["(Mereka itu dimasukkan ke dalam surga lagi dimuliakan.)",[["أُو۟لَـٰٓئِكَ","Those"],["فِى","(will be) in"],["جَنَّـٰتٍۢ","Gardens"],["مُّكْرَمُونَ","honored"]]],"5411":["(Mengapakah orang-orang kami itu ke arahmu) menuju kepadamu (dengan bersegera) lafal muhthi`iina berkedudukan sebagai hal atau kata keterangan keadaan, yakni mereka selalu menatapkan pandangannya ke arahmu secara terus-menerus.",[["فَمَالِ","So what is with"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["قِبَلَكَ","before you"],["مُهْطِعِينَ","(they) hasten"]]],"5412":["(Dari kanan dan dari kiri) dari sebelah kananmu dan sebelah kirimu (dengan berkelompok-kelompok) secara bergerombol dan membentuk lingkaran di sekitarmu. Mereka berbuat demikian seraya mengatakan dengan nada mengejek, \"Sungguh jika mereka, yakni orang-orang yang beriman, masuk ke dalam surga, niscaya kami benar-benar akan masuk ke dalamnya sebelum mereka.\" Maka Allah berfirman:",[["عَنِ","On"],["ٱلْيَمِينِ","the right"],["وَعَنِ","and on"],["ٱلشِّمَالِ","the left"],["عِزِينَ","(in) separate groups"]]],"5413":["(\"Adakah setiap orang dari orang-orang kafir itu ingin masuk ke dalam surga yang penuh dengan kenikmatan?\")",[["أَيَطْمَعُ","Does long"],["كُلُّ","every"],["ٱمْرِئٍۢ","person"],["مِّنْهُمْ","among them"],["أَن","that"],["يُدْخَلَ","he enters"],["جَنَّةَ","a Garden"],["نَعِيمٍۢ","(of) Delight"]]],"5414":["(Sekali-kali tidak!) kalimat ini merupakan sanggahan terhadap mereka yang ingin masuk surga, padahal mereka kafir. (Sesungguhnya Kami ciptakan mereka) sama dengan selain mereka (dari apa yang mereka ketahui) yakni dari air mani; maka tidak cukup hanya dengan itu mereka mengharapkan surga, karena sesungguhnya surga itu hanya dapat diharapkan bagi orang-orang yang bertakwa.",[["كَلَّآ ۖ","By no means"],["إِنَّا","Indeed, We"],["خَلَقْنَـٰهُم","[We] have created them"],["مِّمَّا","from what"],["يَعْلَمُونَ","they know"]]],"5415":["(Maka) huruf laa di sini adalah huruf zaidah (Aku bersumpah dengan nama Rabb yang memiliki arah timur dan arah barat) yang memiliki matahari, bulan dan bintang-bintang lainnya (sesungguhnya Kami benar-benar Maha Kuasa.)",[["فَلَآ","But nay"],["أُقْسِمُ","I swear"],["بِرَبِّ","by (the) Lord"],["ٱلْمَشَـٰرِقِ","(of) the risings"],["وَٱلْمَغَـٰرِبِ","and the settings"],["إِنَّا","that We"],["لَقَـٰدِرُونَ","(are) surely Able"]]],"5416":["(Untuk mengganti) mereka (dengan kaum yang lebih baik dari mereka, dan sekali-kali Kami tidak dapat dikalahkan) tidak ada yang dapat mengalahkan Kami dalam hal ini.",[["عَلَىٰٓ","[On]"],["أَن","to"],["نُّبَدِّلَ","[We] replace"],["خَيْرًۭا","(with) better"],["مِّنْهُمْ","than them"],["وَمَا","and not"],["نَحْنُ","We"],["بِمَسْبُوقِينَ","(are) to be outrun"]]],"5417":["(Maka biarkanlah mereka) tinggalkanlah mereka (tenggelam) dalam kebatilan (dan bermain-main) dalam keduniaan (sampai mereka menjumpai) menemui (hari yang diancamkan kepada mereka) yang pada hari itu ada azab bagi mereka.",[["فَذَرْهُمْ","So leave them"],["يَخُوضُوا۟","(to) converse vainly"],["وَيَلْعَبُوا۟","and amuse themselves"],["حَتَّىٰ","until"],["يُلَـٰقُوا۟","they meet"],["يَوْمَهُمُ","their Day"],["ٱلَّذِى","which"],["يُوعَدُونَ","they are promised"]]],"5418":["(Yaitu pada hari mereka keluar dari kubur) dari tempat-tempat mereka dikubur (dengan cepat) menuju ke padang Mahsyar tempat mereka dihimpunkan (seakan-akan mereka pergi kepada berhala-berhala) menurut suatu qiraat dibaca nushubin, artinya sesuatu yang dibangun untuk pertanda atau tugu, yang dimaksud adalah berhala-berhala (dengan cepatnya) mereka pergi dengan cepat seakan-akan pergi kepada berhala-berhala mereka.",[["يَوْمَ","(The) Day"],["يَخْرُجُونَ","they will come out"],["مِنَ","from"],["ٱلْأَجْدَاثِ","the graves"],["سِرَاعًۭا","rapidly"],["كَأَنَّهُمْ","as if they (were)"],["إِلَىٰ","to"],["نُصُبٍۢ","a goal"],["يُوفِضُونَ","hastening"]]],"5419":["(Dalam keadaan hina) atau nista (pandangan mereka karena diliputi) diselimuti (oleh rasa hina. Itulah hari yang dahulunya diancamkan kepada mereka) lafal dzaalika menjadi mubtada, dan lafal-lafal sesudahnya berkedudukan menjadi khabarnya; makna yang dimaksud adalah hari kiamat.",[["خَـٰشِعَةً","Humbled"],["أَبْصَـٰرُهُمْ","their eyesights"],["تَرْهَقُهُمْ","will cover them"],["ذِلَّةٌۭ ۚ","humiliation"],["ذَٰلِكَ","That"],["ٱلْيَوْمُ","(is) the Day"],["ٱلَّذِى","which"],["كَانُوا۟","they were"],["يُوعَدُونَ","promised"]]],"5420":["(Sesungguhnya Kami telah mengutus Nuh kepada kaumnya, dengan memerintahkan, berilah peringatan) dengan memperingatkan (kepada kaummu sebelum datang kepada mereka) jika mereka tetap tidak mau beriman (azab yang pedih) siksaan yang menyakitkan di dunia dan akhirat.",[["إِنَّآ","Indeed, We"],["أَرْسَلْنَا","[We] sent"],["نُوحًا","Nuh"],["إِلَىٰ","to"],["قَوْمِهِۦٓ","his people"],["أَنْ","that"],["أَنذِرْ","Warn"],["قَوْمَكَ","your people"],["مِن","from"],["قَبْلِ","before"],["أَن","[that]"],["يَأْتِيَهُمْ","comes to them"],["عَذَابٌ","a punishment"],["أَلِيمٌۭ","painful"]]],"5421":["(Nuh berkata, \"Hai kaumku! Sesungguhnya aku adalah pemberi peringatan yang menjelaskan kepada kalian.\") Jelas peringatannya.",[["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["إِنِّى","Indeed, I am"],["لَكُمْ","to you"],["نَذِيرٌۭ","a warner"],["مُّبِينٌ","clear"]]],"5422":["(Yaitu hendaknya) artinya aku perintahkan kepada kalian hendaknya (kalian menyembah Allah, bertakwalah kalian kepada-Nya dan taat kepadaku.)",[["أَنِ","That"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["وَٱتَّقُوهُ","and fear Him"],["وَأَطِيعُونِ","and obey me"]]],"5423":["(Niscaya Allah akan mengampuni sebagian dosa-dosa kalian) huruf min di sini dapat dianggap sebagai huruf zaidah, karena sesungguhnya Islam itu mengampuni semua dosa yang terjadi sebelumnya; yakni semua dosa kalian. Sebagaimana dapat pula dianggap sebagai min yang mengandung makna sebagian, hal ini karena mengecualikan hak-hak yang bersangkutan dengan orang lain (dan menangguhkan kalian) tanpa diazab (sampai kepada waktu yang ditentukan) yaitu ajal kematiannya. (Sesungguhnya ketetapan Allah) yang memutuskan untuk mengazab kalian, jika kalian tidak beriman kepada-Nya (apabila telah datang tidak dapat ditangguhkan, kalau kalian mengetahui) seandainya kalian mengetahui hal tersebut, niscaya kalian beriman kepada-Nya.",[["يَغْفِرْ","He will forgive"],["لَكُم","for you"],["مِّن","[of]"],["ذُنُوبِكُمْ","your sins"],["وَيُؤَخِّرْكُمْ","and give you respite"],["إِلَىٰٓ","for"],["أَجَلٍۢ","a term"],["مُّسَمًّى ۚ","specified"],["إِنَّ","Indeed"],["أَجَلَ","(the) term"],["ٱللَّهِ","(of) Allah"],["إِذَا","when"],["جَآءَ","it comes"],["لَا","not"],["يُؤَخَّرُ ۖ","is delayed"],["لَوْ","if"],["كُنتُمْ","you"],["تَعْلَمُونَ","know"]]],"5424":["(Nuh berkata, \"Ya Rabbku! Sesungguhnya aku telah menyeru kaumku malam dan siang) terus-menerus tanpa mengenal waktu.",[["قَالَ","He said"],["رَبِّ","My Lord"],["إِنِّى","Indeed, I"],["دَعَوْتُ","invited"],["قَوْمِى","my people"],["لَيْلًۭا","night"],["وَنَهَارًۭا","and day"]]],"5425":["(Maka seruanku itu hanyalah menambah mereka lari) dari iman.",[["فَلَمْ","But not"],["يَزِدْهُمْ","increased them"],["دُعَآءِىٓ","my invitation"],["إِلَّا","except"],["فِرَارًۭا","(in) flight"]]],"5426":["(Dan sesungguhnya setiap kali aku menyeru mereka, agar Engkau mengampuni mereka, mereka memasukkan anak jari mereka ke dalam telinganya) supaya mereka tidak dapat mendengar seruanku (dan menutupkan bajunya ke mukanya) supaya mereka tidak melihatku (dan mereka tetap) dalam kekafiran mereka (dan menyombongkan diri) tidak mau beriman (dengan sangat.)",[["وَإِنِّى","And indeed, I"],["كُلَّمَا","every time"],["دَعَوْتُهُمْ","I invited them"],["لِتَغْفِرَ","that You may forgive"],["لَهُمْ","them"],["جَعَلُوٓا۟","they put"],["أَصَـٰبِعَهُمْ","their fingers"],["فِىٓ","in"],["ءَاذَانِهِمْ","their ears"],["وَٱسْتَغْشَوْا۟","and covered themselves"],["ثِيَابَهُمْ","(with) their garments"],["وَأَصَرُّوا۟","and persisted"],["وَٱسْتَكْبَرُوا۟","and were arrogant"],["ٱسْتِكْبَارًۭا","(with) pride"]]],"5427":["(Kemudian sesungguhnya aku telah menyeru mereka dengan terang-terangan) dengan sekuat suaraku.",[["ثُمَّ","Then"],["إِنِّى","indeed, I"],["دَعَوْتُهُمْ","invited them"],["جِهَارًۭا","publicly"]]],"5428":["(Kemudian sesungguhnya aku telah mengeraskan kepada mereka) suaraku (dan pula telah membisikkan) suaraku atau seruanku (kepada mereka dengan sangat rahasia.)",[["ثُمَّ","Then"],["إِنِّىٓ","indeed, I"],["أَعْلَنتُ","announced"],["لَهُمْ","to them"],["وَأَسْرَرْتُ","and I confided"],["لَهُمْ","to them"],["إِسْرَارًۭا","secretly"]]],"5429":["(Maka aku katakan, \"Mohonlah ampun kepada Rabb kalian) dari kemusyrikan kalian (sesungguhnya Dia adalah Maha Pengampun.\")",[["فَقُلْتُ","Then I said"],["ٱسْتَغْفِرُوا۟","Ask forgiveness"],["رَبَّكُمْ","(from) your Lord"],["إِنَّهُۥ","Indeed, He"],["كَانَ","is"],["غَفَّارًۭا","Oft-Forgiving"]]],"5430":["(Niscaya Dia akan mengirimkan hujan) pada saat itu mereka sedang mengalami kekeringan karena terlalu lama tidak ada hujan (kepada kalian dengan lebat) dengan deras.",[["يُرْسِلِ","He will send down"],["ٱلسَّمَآءَ","(rain from) the sky"],["عَلَيْكُم","upon you"],["مِّدْرَارًۭا","(in) abundance"]]],"5431":["(Dan membanyakkan harta dan anak-anak kalian dan mengadakan untuk kalian kebun-kebun) ladang-ladang (dan mengadakan pula bagi kalian sungai-sungai) yang mengalir di dalamnya.",[["وَيُمْدِدْكُم","And provide you"],["بِأَمْوَٰلٍۢ","with wealth"],["وَبَنِينَ","and children"],["وَيَجْعَل","and make"],["لَّكُمْ","for you"],["جَنَّـٰتٍۢ","gardens"],["وَيَجْعَل","and make"],["لَّكُمْ","for you"],["أَنْهَـٰرًۭا","rivers"]]],"5432":["(Mengapa kalian tidak mengharapkan keagungan dari Allah?) tidak mengharapkan Allah mengangkat derajat kalian, agar kalian beriman kepada-Nya.",[["مَّا","What"],["لَكُمْ","(is) for you"],["لَا","not"],["تَرْجُونَ","you attribute"],["لِلَّهِ","to Allah"],["وَقَارًۭا","grandeur"]]],"5433":["(Padahal sesungguhnya Dia telah menciptakan kalian dalam beberapa tingkatan kejadian) lafal athwaaran bentuk jamak dari lafal thaurun, artinya tahap; yakni mulai dari tahap air mani terus menjadi darah kental atau alaqah, hingga menjadi manusia yang sempurna bentuknya. Dan memperhatikan kejadian makhluk-Nya seharusnya menuntun mereka iman kepada yang telah menciptakannya.",[["وَقَدْ","And indeed"],["خَلَقَكُمْ","He created you"],["أَطْوَارًا","(in) stages"]]],"5434":["(Tidakkah kalian perhatikan) kalian lihat (bagaimana Allah telah menciptakan tujuh langit bertingkat-tingkat?) sebagian di antaranya berada di atas sebagian yang lain.",[["أَلَمْ","Do not"],["تَرَوْا۟","you see"],["كَيْفَ","how"],["خَلَقَ","did create"],["ٱللَّهُ","Allah"],["سَبْعَ","(the) seven"],["سَمَـٰوَٰتٍۢ","heavens"],["طِبَاقًۭا","(in) layers"]]],"5435":["(Dan Allah menciptakan padanya bulan) yaitu pada langit yang paling terdekat di antara keseluruhan langit itu (sebagai cahaya dan menjadikan matahari sebagai pelita?) yang memancarkan sinar terang yang jauh lebih kuat daripada sinar bulan.",[["وَجَعَلَ","And made"],["ٱلْقَمَرَ","the moon"],["فِيهِنَّ","therein"],["نُورًۭا","a light"],["وَجَعَلَ","and made"],["ٱلشَّمْسَ","the sun"],["سِرَاجًۭا","a lamp"]]],"5436":["(Dan Allah menumbuhkan kalian) Dia telah menciptakan kalian (dari tanah) karena Dia telah menciptakan bapak moyang kalian, yaitu Nabi Adam daripadanya (dengan sebaik-baiknya.)",[["وَٱللَّهُ","And Allah"],["أَنۢبَتَكُم","has caused you to grow"],["مِّنَ","from"],["ٱلْأَرْضِ","the earth"],["نَبَاتًۭا","(as) a growth"]]],"5437":["(Kemudian Dia mengembalikan kalian ke dalam tanah) dalam keadaan terkubur di dalamnya (dan mengeluarkan kalian) dari dalamnya menjadi hidup kembali pada hari kiamat (dengan sebenar-benarnya.)",[["ثُمَّ","Then"],["يُعِيدُكُمْ","He will return you"],["فِيهَا","into it"],["وَيُخْرِجُكُمْ","and bring you forth"],["إِخْرَاجًۭا","(a new) bringing forth"]]],"5438":["(Dan Allah menjadikan bagi kalian bumi sebagai hamparan) yakni dalam keadaan terhampar.",[["وَٱللَّهُ","And Allah"],["جَعَلَ","made"],["لَكُمُ","for you"],["ٱلْأَرْضَ","the earth"],["بِسَاطًۭا","an expanse"]]],"5439":["(Supaya kalian menempuh padanya jalan-jalan) atau menempuh jalan-jalan (yang luas.\") yang lebar.",[["لِّتَسْلُكُوا۟","That you may go along"],["مِنْهَا","therein"],["سُبُلًۭا","(in) paths"],["فِجَاجًۭا","wide"]]],"5440":["(Nuh berkata, \"Ya Rabbku! Sesungguhnya mereka telah mendurhakaiku, dan mereka telah mengikuti) orang-orang yang hina dan orang-orang yang miskin di antara mereka (orang-orang yang harta dan anak-anaknya tidak menambah kepadanya) maksudnya orang-orang yang rendah dan orang-orang miskin dari kalangan kaum Nabi Nuh itu, lebih senang mengikuti pemimpin-pemimpin yang diberi nikmat akan hal-hal tersebut, yakni banyak harta dan anaknya. Lafal wuldun dengan didamahkan huruf waunya dan sukun pada lamnya, atau waladun dengan difatahkan kedua-duanya; kalau bentuk yang pertama menurut suatu pendapat, bahwa itu adalah bentuk jamak dari lafal waladun. Dalam arti kata disamakan dengan wazan lafal khasyabun yang jamaknya khusybun. Menurut pendapat yang lain, lafal wuldun mempunyai arti yang sama dengan lafal waladun, karena wazannya dianggap sama dengan lafal bukhlun dan bakhiilun (melainkan kerugian belaka) yaitu keangkaramurkaan dan kekafiran.",[["قَالَ","Said"],["نُوحٌۭ","Nuh"],["رَّبِّ","My Lord"],["إِنَّهُمْ","Indeed, they"],["عَصَوْنِى","disobeyed me"],["وَٱتَّبَعُوا۟","and followed"],["مَن","(the one) who"],["لَّمْ","(did) not"],["يَزِدْهُ","increase him"],["مَالُهُۥ","his wealth"],["وَوَلَدُهُۥٓ","and his children"],["إِلَّا","except"],["خَسَارًۭا","(in) loss"]]],"5441":["(Dan mereka melakukan tipu daya) yaitu para pemimpin mereka (yang amat besar.\") Tipu daya mereka sangat besar, yaitu mereka telah mendustakan Nabi Nuh dan menyakitinya serta menyakiti orang-orang yang beriman kepadanya.",[["وَمَكَرُوا۟","And they have planned"],["مَكْرًۭا","a plan"],["كُبَّارًۭا","great"]]],"5442":["(Dan mereka berkata) kepada orang-orang yang menjadi bawahan mereka (\"Jangan sekali-kali kalian meninggalkan tuhan-tuhan sesembahan kalian dan jangan pula sekali-kali kalian meninggalkan wadd) dapat dibaca waddan dan wuddan (dan jangan pula suwa', yaghuts, ya'uq dan nasr\") nama-nama tersebut adalah nama-nama berhala-berhala mereka.",[["وَقَالُوا۟","And they said"],["لَا","(Do) not"],["تَذَرُنَّ","leave"],["ءَالِهَتَكُمْ","your gods"],["وَلَا","and (do) not"],["تَذَرُنَّ","leave"],["وَدًّۭا","Wadd"],["وَلَا","and not"],["سُوَاعًۭا","Suwa"],["وَلَا","and not"],["يَغُوثَ","Yaguth"],["وَيَعُوقَ","and Yauq"],["وَنَسْرًۭا","and Nasr"]]],"5443":["(Dan sesungguhnya mereka telah menyesatkan) dengan nama-nama tersebut (kebanyakan manusia) karena mereka telah memerintahkan manusia untuk menyembahnya (dan janganlah Engkau tambahkan bagi orang-orang yang lalim itu selain kesesatan) ayat ini diathafkan kepada lafal qad adhalluu, yakni merupakan doa Nabi Nuh setelah Allah mewahyukan kepadanya, bahwasanya sekali-kali tidak ada orang yang mau beriman di antara kaummu, melainkan orang-orang yang telah beriman saja.",[["وَقَدْ","And indeed"],["أَضَلُّوا۟","they have led astray"],["كَثِيرًۭا ۖ","many"],["وَلَا","And not"],["تَزِدِ","increase"],["ٱلظَّـٰلِمِينَ","the wrongdoers"],["إِلَّا","except"],["ضَلَـٰلًۭا","(in) error"]]],"5444":["(Disebabkan) huruf maa di sini adalah huruf shilah atau penghubung (kesalahan-kesalahan mereka) menurut suatu qiraat dibaca khathii'aatihim dengan memakai huruf hamzah sesudah huruf ya (mereka ditenggelamkan) oleh banjir besar (lalu dimasukkan ke dalam neraka) yaitu mereka diazab sesudah mereka ditenggelamkan di bawah air (maka mereka tidak dapat menemukan selain) selain daripada (Allah, seseorang pun yang menolong mereka) yang dapat melindungi mereka dari azab.",[["مِّمَّا","Because of"],["خَطِيٓـَٔـٰتِهِمْ","their sins"],["أُغْرِقُوا۟","they were drowned"],["فَأُدْخِلُوا۟","then made to enter"],["نَارًۭا","(the) Fire"],["فَلَمْ","and not"],["يَجِدُوا۟","they found"],["لَهُم","for themselves"],["مِّن","from"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["أَنصَارًۭا","any helpers"]]],"5445":["(Nuh berkata, \"Ya Rabbku! Janganlah Engkau biarkan seorang pun di antara orang-orang kafir itu tinggal di atas bumi) bertempat tinggal, makna yang dimaksud ialah jangan biarkan seorang pun di antara mereka.",[["وَقَالَ","And said"],["نُوحٌۭ","Nuh"],["رَّبِّ","My Lord"],["لَا","(Do) not"],["تَذَرْ","leave"],["عَلَى","on"],["ٱلْأَرْضِ","the earth"],["مِنَ","any"],["ٱلْكَـٰفِرِينَ","(of) the disbelievers"],["دَيَّارًا","(as) an inhabitant"]]],"5446":["(Sesungguhnya jika Engkau biarkan mereka tinggal, niscaya mereka akan menyesatkan hamba-hamba-Mu, dan mereka tidak akan melahirkan selain anak yang berbuat maksiat lagi sangat kafir) lafal faajiran dan kaffaaran berasal dari yafjuru dan yakfuru. Nabi Nuh berdoa demikian setelah ada wahyu mengenai keadaan mereka yang telah disebutkan tadi yakni, bahwa mereka tidak akan beriman, kecuali hanya orang-orang yang telah beriman kepadanya.",[["إِنَّكَ","Indeed, You"],["إِن","if"],["تَذَرْهُمْ","You leave them"],["يُضِلُّوا۟","they will mislead"],["عِبَادَكَ","Your slaves"],["وَلَا","and not"],["يَلِدُوٓا۟","they will beget"],["إِلَّا","except"],["فَاجِرًۭا","a wicked"],["كَفَّارًۭا","a disbeliever"]]],"5447":["(Ya Rabbku! Ampunilah aku, ibu bapakku) kedua orang tua Nabi Nuh termasuk orang-orang yang beriman (orang yang masuk ke dalam rumahku) atau mesjidku (dengan beriman, dan semua orang yang beriman laki-laki dan perempuan) hingga hari kiamat nanti (dan janganlah Engkau tambahkan kepada orang-orang yang zalim itu selain kebinasaan.\") Atau kehancuran, akhirnya mereka benar-benar dibinasakan.",[["رَّبِّ","My Lord"],["ٱغْفِرْ","Forgive"],["لِى","me"],["وَلِوَٰلِدَىَّ","and my parents"],["وَلِمَن","and whoever"],["دَخَلَ","enters"],["بَيْتِىَ","my house "],["مُؤْمِنًۭا","a believer"],["وَلِلْمُؤْمِنِينَ","and the believing men"],["وَٱلْمُؤْمِنَـٰتِ","and the believing women"],["وَلَا","And (do) not"],["تَزِدِ","increase"],["ٱلظَّـٰلِمِينَ","the wrongdoers"],["إِلَّا","except"],["تَبَارًۢا","(in) destruction"]]],"5448":["(Katakanlah) hai Muhammad! (\"Telah diwahyukan kepadaku) maksudnya aku telah diberitahu oleh Allah melalui wahyu-Nya (bahwasanya) dhamir yang terdapat pada lafal annahu ini adalah dhamir sya'n (telah mendengarkan) bacaan Alquranku (sekumpulan jin.\") yakni jin dari Nashibin; demikian itu terjadi sewaktu Nabi saw. sedang melakukan salat Subuh di lembah Nakhlah, yang terletak di tengah-tengah antara Mekah dan Thaif. Jin itulah yang disebutkan di dalam firman-Nya, \"Dan (ingatlah) ketika Kami hadapkan serombongan jin kepadamu.\" (Q.S. Al-Ahqaf 29) (lalu mereka berkata) kepada kaum mereka setelah mereka kembali kepada kaumnya: (\"Sesungguhnya kami telah mendengarkan Alquran yang menakjubkan) artinya mereka takjub akan kefasihan bahasanya dan kepadatan makna-makna yang dikandungnya, serta hal-hal lainnya.",[["قُلْ","Say"],["أُوحِىَ","It has been revealed"],["إِلَىَّ","to me"],["أَنَّهُ","that"],["ٱسْتَمَعَ","listened"],["نَفَرٌۭ","a group"],["مِّنَ","of"],["ٱلْجِنِّ","the jinn"],["فَقَالُوٓا۟","and they said"],["إِنَّا","Indeed, we"],["سَمِعْنَا","heard"],["قُرْءَانًا","a Quran"],["عَجَبًۭا","amazing"]]],"5449":["(Yang memberi petunjuk kepada jalan yang benar) yaitu kepada keimanan dan kebenaran (lalu kami beriman kepadanya. Dan kami sekali-kali tidak akan mempersekutukan) sesudah hari ini (seorang pun dengan Rabb kami.)",[["يَهْدِىٓ","It guides"],["إِلَى","to"],["ٱلرُّشْدِ","the right way"],["فَـَٔامَنَّا","so we believe"],["بِهِۦ ۖ","in it"],["وَلَن","and never"],["نُّشْرِكَ","we will associate"],["بِرَبِّنَآ","with our Lord"],["أَحَدًۭا","anyone"]]],"5450":["(Dan bahwasanya) dhamir yang terdapat pada ayat ini adalah dhamir sya'n, demikian pula pada dua tempat lain sesudahnya (Maha Tinggi Kebesaran Rabb kami) Maha Suci kebesaran dan keagungan-Nya dari apa-apa yang dinisbatkan kepada-Nya (Dia tidak beristri) tidak mempunyai istri (dan tidak pula beranak.)",[["وَأَنَّهُۥ","And that He "],["تَعَـٰلَىٰ","Exalted is"],["جَدُّ","(the) Majesty"],["رَبِّنَا","(of) our Lord "],["مَا","not"],["ٱتَّخَذَ","He has taken"],["صَـٰحِبَةًۭ","a wife"],["وَلَا","and not"],["وَلَدًۭا","a son"]]],"5451":["(Dan bahwasanya orang yang kurang akal daripada kami selalu mengatakan) maksudnya orang yang bodoh di antara kami (perkataan yang melampaui batas terhadap Allah) dusta yang berlebihan, yaitu dengan menyifati Allah punya istri dan anak.",[["وَأَنَّهُۥ","And that he"],["كَانَ","used to"],["يَقُولُ","speak "],["سَفِيهُنَا","the foolish among us"],["عَلَى","against"],["ٱللَّهِ","Allah"],["شَطَطًۭا","an excessive transgression"]]],"5452":["(Dan sesungguhnya kami mengira, bahwa) huruf an di sini adalah bentuk takhfif dari anna, yakni annahu (manusia dan jin sekali-kali tidak akan mengatakan perkataan yang dusta terhadap Allah) yakni menyifati-Nya dengan hal-hal tersebut hingga kami dapat buktikan kedustaan mereka dalam hal itu. Allah berfirman:",[["وَأَنَّا","And that we"],["ظَنَنَّآ","thought"],["أَن","that"],["لَّن","never"],["تَقُولَ","will say"],["ٱلْإِنسُ","the men"],["وَٱلْجِنُّ","and the jinn"],["عَلَى","against"],["ٱللَّهِ","Allah"],["كَذِبًۭا","any lie"]]],"5453":["(Dan bahwasanya ada beberapa orang laki-laki di antara manusia meminta perlindungan) memohon perlindungan (kepada beberapa laki-laki di antara jin) di dalam perjalanan mereka sewaktu mereka beristirahat di tempat yang menyeramkan, lalu masing-masing orang mengatakan, aku berlindung kepada penunggu tempat ini dari gangguan penunggu lainnya yang jahat (maka jin-jin itu menambah bagi mereka) dengan permintaan perlindungannya kepada jin-jin itu (dosa dan kesalahan) karena mereka mengatakan, bahwa kami telah dilindungi oleh jin anu dan orang anu.",[["وَأَنَّهُۥ","And that"],["كَانَ","(there) were"],["رِجَالٌۭ","men"],["مِّنَ","among"],["ٱلْإِنسِ","mankind"],["يَعُوذُونَ","who sought refuge"],["بِرِجَالٍۢ","in (the) men"],["مِّنَ","from"],["ٱلْجِنِّ","the jinn"],["فَزَادُوهُمْ","so they increased them"],["رَهَقًۭا","(in) burden"]]],"5454":["(Dan sesungguhnya mereka) yakni jin-jin itu (menyangka sebagaimana sangkaan kalian) hai manusia (bahwa) bentuk takhfif dari anna, asalnya annahu (Allah sekali-kali tidak akan membangkitkan seorang pun.\") sesudah matinya.",[["وَأَنَّهُمْ","And that they"],["ظَنُّوا۟","thought"],["كَمَا","as"],["ظَنَنتُمْ","you thought"],["أَن","that"],["لَّن","never"],["يَبْعَثَ","will raise"],["ٱللَّهُ","Allah"],["أَحَدًۭا","anyone"]]],"5455":["Jin mengatakan: (\"Dan sesungguhnya kami telah mencoba menyentuh langit) maksudnya kami telah bermaksud untuk mencuri pendengaran di langit (maka kami menjumpainya penuh dengan penjaga) para malaikat (yang kuat dan panah-panah api) yakni bintang-bintang yang membakar; hal ini terjadi setelah Nabi saw. diutus menjadi rasul.",[["وَأَنَّا","And that we"],["لَمَسْنَا","sought to touch"],["ٱلسَّمَآءَ","the heaven"],["فَوَجَدْنَـٰهَا","but we found it"],["مُلِئَتْ","filled (with)"],["حَرَسًۭا","guards"],["شَدِيدًۭا","severe"],["وَشُهُبًۭا","and flaming fires"]]],"5456":["(Dan sesungguhnya kami dahulu) sebelum Nabi saw. diutus (dapat menduduki beberapa tempat di langit itu untuk mendengar-dengarkan) berita-beritanya dan untuk mencurinya. (Tetapi sekarang barang siapa yang mencoba mendengar-dengarkan, seperti itu, tentu akan menjumpai panah api yang mengintai) panah-panah api yang terdiri dari meteor-meteor itu telah mengintainya dalam keadaan siap untuk memburunya.",[["وَأَنَّا","And that we"],["كُنَّا","used to"],["نَقْعُدُ","sit"],["مِنْهَا","there in"],["مَقَـٰعِدَ","positions"],["لِلسَّمْعِ ۖ","for hearing"],["فَمَن","but (he) who"],["يَسْتَمِعِ","listens"],["ٱلْـَٔانَ","now"],["يَجِدْ","will find"],["لَهُۥ","for him"],["شِهَابًۭا","a flaming fire"],["رَّصَدًۭا","waiting"]]],"5457":["(Dan sesungguhnya kami tidak mengetahui apakah keburukan yang dikehendaki) sesudah terjaganya langit dari pencurian pendengaran (bagi orang yang di bumi ataukah Rabb mereka menghendaki kebaikan bagi mereka) lafal rasyadan artinya khairan, yaitu kebaikan.",[["وَأَنَّا","And that we "],["لَا","not"],["نَدْرِىٓ","we know"],["أَشَرٌّ","whether evil"],["أُرِيدَ","is intended"],["بِمَن","for (those) who"],["فِى","(are) in"],["ٱلْأَرْضِ","the earth"],["أَمْ","or"],["أَرَادَ","intends"],["بِهِمْ","for them"],["رَبُّهُمْ","their Lord"],["رَشَدًۭا","a right path"]]],"5458":["(Dan sesungguhnya di antara kami ada orang-orang yang saleh) sesudah mendengarkan Alquran ini (dan di antara kami ada pula yang tidak demikian halnya) ada kaum yang tidak saleh. (Adalah kami menempuh jalan yang berbeda-beda) terdiri dari golongan yang berbeda-beda; ada yang muslim dan ada pula yang kafir.",[["وَأَنَّا","And that [we]"],["مِنَّا","among us"],["ٱلصَّـٰلِحُونَ","(are) the righteous"],["وَمِنَّا","and among us"],["دُونَ","(are) other than"],["ذَٰلِكَ ۖ","that"],["كُنَّا","We"],["طَرَآئِقَ","(are on) ways"],["قِدَدًۭا","different"]]],"5459":["(Dan sesungguhnya kami yakin, bahwa) huruf an ini adalah bentuk takhfif dari anna, asalnya annahu (kami sekali-kali tidak akan dapat melepaskan diri, dari kekuasaan, Allah di muka bumi, dan sekali-kali tidak pula dapat melepaskan diri daripada-Nya dengan lari) maksudnya, kami tidak akan dapat menyelamatkan diri daripada-Nya, apakah kami berada di bumi atau kami lari dari bumi menuju ke langit.",[["وَأَنَّا","And that we"],["ظَنَنَّآ","[we] have become certain"],["أَن","that"],["لَّن","never"],["نُّعْجِزَ","we will cause failure"],["ٱللَّهَ","(to) Allah"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَلَن","and never"],["نُّعْجِزَهُۥ","we can escape Him"],["هَرَبًۭا","(by) flight"]]],"5460":["(Dan sesungguhnya kami tatkala mendengar petunjuk) yakni Alquran (kami beriman kepadanya. Barang siapa beriman kepada Rabbnya, maka ia tidak usah takut) sesudah lafal yakhaafu diperkirakan adanya lafal huwa (akan kekurangan) pengurangan pahala kebaikannya (dan tidak pula takut akan dizalimi) diperlakukan secara zalim, yaitu dengan penambahan kesalahan dan dosanya.",[["وَأَنَّا","And that [we]"],["لَمَّا","when"],["سَمِعْنَا","we heard"],["ٱلْهُدَىٰٓ","the Guidance"],["ءَامَنَّا","we believed"],["بِهِۦ ۖ","in it"],["فَمَن","And whoever"],["يُؤْمِنۢ","believes"],["بِرَبِّهِۦ","in his Lord"],["فَلَا","then not"],["يَخَافُ","he will fear"],["بَخْسًۭا","any loss"],["وَلَا","and not"],["رَهَقًۭا","any burden"]]],"5461":["(Dan sesungguhnya di antara kami ada orang-orang yang taat dan ada pula orang-orang yang menyimpang dari kebenaran) yakni melewati batas disebabkan kekafiran mereka. (Barang siapa yang taat, maka mereka itu benar-benar telah memilih jalan petunjuk) atau menuju ke jalan hidayah.",[["وَأَنَّا","And that we"],["مِنَّا","among us"],["ٱلْمُسْلِمُونَ","(are) Muslims"],["وَمِنَّا","and among us"],["ٱلْقَـٰسِطُونَ ۖ","(are) unjust"],["فَمَنْ","And whoever"],["أَسْلَمَ","submits"],["فَأُو۟لَـٰٓئِكَ","then those"],["تَحَرَّوْا۟","have sought"],["رَشَدًۭا","(the) right path"]]],"5462":["(Adapun orang-orang yang menyimpang dari kebenaran, maka mereka menjadi kayu api bagi neraka Jahanam.\") atau sebagai bahan bakarnya. Dhamir anna dan annahum serta annahu yang terdapat pada dua belas tempat kembali kepada jin. Dan firman-Nya, \"Wa innaa minnal muslimuuna wa minnal qaasithuuna,\" dibaca kasrah huruf hamzahnya, yaitu innaa berarti merupakan jumlah isti'naf atau kalimat baru. Jika dibaca fathah yaitu menjadi anna berarti kedudukannya disamakan dengan kalimat-kalimat sebelumnya.",[["وَأَمَّا","And as for"],["ٱلْقَـٰسِطُونَ","the unjust"],["فَكَانُوا۟","they will be"],["لِجَهَنَّمَ","for Hell"],["حَطَبًۭا","firewood"]]],"5463":["Allah swt. berfirman mengenai orang-orang kafir Mekah: (Dan bahwasanya) mereka; adalah bentuk takhfif dari anna, sedangkan isimnya tidak disebutkan, yakni annahum, artinya, bahwasanya mereka; diathafkan kepada lafal annahus tama`a (jika mereka tetap berjalan lurus di atas jalan itu) yaitu agama Islam (benar-benar Kami akan memberi minum kepada mereka air yang banyak) dari langit. Demikian itu setelah hujan dihentikan dari mereka selama tujuh tahun.",[["وَأَلَّوِ","And that if"],["ٱسْتَقَـٰمُوا۟","they had remained"],["عَلَى","on"],["ٱلطَّرِيقَةِ","the Way"],["لَأَسْقَيْنَـٰهُم","surely We (would) have given them to drink"],["مَّآءً","water"],["غَدَقًۭا","(in) abundance"]]],"5464":["(Untuk Kami beri cobaan kepada mereka) untuk Kami uji mereka (dengan melaluinya) hingga Kami mengetahui bagaimana kesyukuran mereka, dengan pengetahuan yang nyata. (Dan barang siapa yang berpaling dari peringatan Rabbnya) yakni Alquran (niscaya Kami akan memasukkannya) (ke dalam azab yang amat berat.)",[["لِّنَفْتِنَهُمْ","That We might test them"],["فِيهِ ۚ","therein"],["وَمَن","And whoever"],["يُعْرِضْ","turns away"],["عَن","from"],["ذِكْرِ","the Remembrance"],["رَبِّهِۦ","(of) his Lord"],["يَسْلُكْهُ","He will make him enter"],["عَذَابًۭا","a punishment"],["صَعَدًۭا","severe"]]],"5465":["(Dan sesungguhnya mesjid-mesjid itu) atau tempat-tempat salat itu (adalah kepunyaan Allah. Maka janganlah kalian menyembah) di dalamnya (seseorang pun di samping Allah) seumpamanya kalian berbuat kemusyrikan di dalamnya, sebagaimana yang telah dilakukan oleh orang-orang Yahudi dan orang-orang Nasrani, yaitu apabila mereka memasuki gereja dan sinagog mereka, maka mereka menyekutukan-Nya.",[["وَأَنَّ","And that"],["ٱلْمَسَـٰجِدَ","the masjids"],["لِلَّهِ","(are) for Allah"],["فَلَا","so (do) not"],["تَدْعُوا۟","call"],["مَعَ","with"],["ٱللَّهِ","Allah"],["أَحَدًۭا","anyone"]]],"5466":["(Dan bahwasanya) dapat dibaca annahu dan innahu; juga merupakan kalimat baru, sedangkan dhamir yang ada ialah dhamir sya'n (tatkala hamba Allah berdiri) yakni Nabi Muhammad saw. (menyembah-Nya) beribadah kepada-Nya di lembah Nakhl (hampir saja mereka) yakni jin-jin yang mendengarkan bacaan Alquran itu (desak-mendesak mengerumuninya) yaitu sebagian di antara mereka menindih sebagian yang lain berjejal-jejal karena keinginan mereka yang sangat untuk mendengarkan bacaan Alquran. Lafal libadan dapat pula dibaca lubadan; dan merupakan bentuk jamak dari lubdatun.",[["وَأَنَّهُۥ","And that"],["لَمَّا","when"],["قَامَ","stood up"],["عَبْدُ","(the) slave"],["ٱللَّهِ","(of) Allah"],["يَدْعُوهُ","calling (upon) Him"],["كَادُوا۟","they almost"],["يَكُونُونَ","became"],["عَلَيْهِ","around him"],["لِبَدًۭا","a compacted mass"]]],"5467":["(Berkatalah dia) Nabi Muhammad berkata sebagai jawabannya terhadap orang-orang kafir yang mengatakan kepadanya, kembalilah kamu dari apa yang kamu lakukan sekarang ini. Akan tetapi menurut qiraat yang lain lafal qaala dibaca qul, artinya katakanlah: (\"Sesungguhnya aku hanya menyembah Rabbku) sebagai Tuhanku (dan aku tidak mempersekutukan sesuatu pun dengan-Nya.\")",[["قُلْ","Say"],["إِنَّمَآ","Only"],["أَدْعُوا۟","I call upon"],["رَبِّى","my Lord"],["وَلَآ","and not"],["أُشْرِكُ","I associate"],["بِهِۦٓ","with Him"],["أَحَدًۭا","anyone"]]],"5468":["(Katakanlah, \"Sesungguhnya aku tidak kuasa untuk mendatangkan sesuatu kemudaratan pun kepada kalian) atau keburukan (dan tidak pula sesuatu kemanfaatan.\") Atau kebaikan.",[["قُلْ","Say"],["إِنِّى","Indeed, I"],["لَآ","(do) not"],["أَمْلِكُ","possess"],["لَكُمْ","for you"],["ضَرًّۭا","any harm"],["وَلَا","and not"],["رَشَدًۭا","right path"]]],"5469":["(Katakanlah, \"Sesungguhnya aku sekali-kali tiada yang dapat melindungiku dari Allah) dari azab-Nya jika aku mendurhakai-Nya (seseorang pun, dan sekali-kali aku tiada akan memperoleh selain dari-Nya) atau selain-Nya (tempat untuk berlindung) maksudnya, tempat aku berlindung.",[["قُلْ","Say"],["إِنِّى","Indeed I"],["لَن","never"],["يُجِيرَنِى","can protect me"],["مِنَ","from"],["ٱللَّهِ","Allah"],["أَحَدٌۭ","anyone"],["وَلَنْ","and never"],["أَجِدَ","can I find"],["مِن","from"],["دُونِهِۦ","besides Him"],["مُلْتَحَدًا","any refuge"]]],"5470":["(Akan tetapi, aku hanya, menyampaikan peringatan) makna yang dikandung dalam lafal ini merupakan pengecualian atau istitsna dari maf'ul atau objek yang terdapat di dalam lafal amliku. Yakni aku tiada memiliki bagi kalian selain hanya menyampaikan peringatan (dari Allah) yang aku terima dari-Nya (dan risalah-Nya) lafal ini diathafkan kepada lafal balaaghan dan lafal-lafal yang terdapat di antara mustatsna minhu dan istitsna merupakan jumlah mu`taridhah atau kalimat sisipan yang berfungsi untuk mengukuhkan makna tiada memiliki. (Dan barang siapa yang mendurhakai Allah dan Rasul-Nya) dalam hal ketauhidan, lalu ia tidak beriman (maka sesungguhnya baginya neraka Jahanam, mereka kekal) lafal khaalidiina adalah hal atau kata keterangan keadaan dari dhamir man. Sehubungan dengan lafal lahuu dhamir yang ada padanya adalah untuk menyesuaikan maknanya dengan lafal man. Lafal khaalidiina ini merupakan hal dari lafal yang tidak disebutkan, lengkapnya mereka memasukinya dalam keadaan pasti kekal (di dalamnya untuk selama-lamanya.)",[["إِلَّا","But"],["بَلَـٰغًۭا","(the) notification"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["وَرِسَـٰلَـٰتِهِۦ ۚ","and His Messages"],["وَمَن","And whoever"],["يَعْصِ","disobeys"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["فَإِنَّ","then indeed"],["لَهُۥ","for him"],["نَارَ","(is the) Fire"],["جَهَنَّمَ","(of) Hell"],["خَـٰلِدِينَ","(they will) abide"],["فِيهَآ","therein"],["أَبَدًا","forever"]]],"5471":["(Sehingga apabila mereka melihat) lafal hattaa di sini mengandung makna ibtidaiyah atau permulaan, dan sekaligus mengandung makna ghayah atau tujuan terakhir dari lafal yang diperkirakan sebelumnya; lengkapnya, mereka masih tetap berada di dalam kekafirannya sehingga mereka melihat (apa yang diancamkan kepada mereka) yaitu azab (maka mereka akan mengetahui) manakala azab itu datang menimpa mereka, yaitu dalam perang Badar atau pada hari kiamat nanti (siapakah yang lebih lemah penolongnya dan lebih sedikit bilangannya.\") maksudnya pembantu-pembantunya, apakah mereka ataukah orang-orang mukmin; penafsiran ini menurut pendapat yang pertama, yaitu dalam perang Badar. Aku ataukah mereka; penafsiran ini berdasarkan pendapat yang kedua, yaitu pada hari kiamat nanti. Sebagian di antara mereka, atau di antara orang-orang kafir itu ada yang bertanya, kapankah datangnya ancaman yang dijanjikan itu? Kemudian turunlah firman selanjutnya, yaitu:",[["حَتَّىٰٓ","Until"],["إِذَا","when"],["رَأَوْا۟","they see"],["مَا","what"],["يُوعَدُونَ","they are promised"],["فَسَيَعْلَمُونَ","then they will know"],["مَنْ","who"],["أَضْعَفُ","(is) weaker"],["نَاصِرًۭا","(in) helpers"],["وَأَقَلُّ","and fewer"],["عَدَدًۭا","(in) number"]]],"5472":["(Katakanlah, \"Tiadalah) tidaklah (aku mengetahui apa yang diancamkan kepada kalian itu dekat) artinya, apakah azab itu dekat (ataukah Rabbku menjadikan bagi kedatangannya masa yang panjang?) Yang tidak diketahui oleh siapa pun kecuali hanya Dia.",[["قُلْ","Say"],["إِنْ","Not"],["أَدْرِىٓ","I know"],["أَقَرِيبٌۭ","whether is near"],["مَّا","what"],["تُوعَدُونَ","you are promised"],["أَمْ","or (whether)"],["يَجْعَلُ","will appoint"],["لَهُۥ","for it"],["رَبِّىٓ","my Lord"],["أَمَدًا","a (distant) term"]]],"5473":["(Dia adalah Tuhan Yang Mengetahui yang gaib) mengetahui semua hal yang gaib di mata hamba-hamba-Nya (maka Dia tidak memperlihatkan) tidak menampakkan (kepada seorang pun tentang yang gaib itu) di antara manusia ini.",[["عَـٰلِمُ","(The) All-Knower"],["ٱلْغَيْبِ","(of) the unseen"],["فَلَا","so not"],["يُظْهِرُ","He reveals"],["عَلَىٰ","from"],["غَيْبِهِۦٓ","His unseen"],["أَحَدًا","(to) anyone"]]],"5474":["(Kecuali kepada rasul yang diridai-Nya, maka sesungguhnya Dia) di samping Dia memperhatikan hal yang gaib kepada Rasul-Nya sesuai dengan apa yang dikehendaki-Nya sebagai mukjizat bagi rasul itu (mengadakan) menjadikan dan memberlakukan (di muka) rasul itu (dan di belakangnya penjaga-penjaga) yang terdiri dari malaikat-malaikat untuk menjaganya, hingga rasul itu dapat menyampaikan hal tersebut, di antara sejumlah wahyu-wahyu-Nya kepada manusia.",[["إِلَّا","Except"],["مَنِ","whom"],["ٱرْتَضَىٰ","He has approved"],["مِن","of"],["رَّسُولٍۢ","a Messenger"],["فَإِنَّهُۥ","and indeed, He"],["يَسْلُكُ","makes to march"],["مِنۢ","from"],["بَيْنِ","before"],["يَدَيْهِ","him"],["وَمِنْ","and from"],["خَلْفِهِۦ","behind him"],["رَصَدًۭا","a guard"]]],"5475":["(Supaya Dia mengetahui) yakni supaya Allah menampakkan (bahwa) adalah bentuk takhfif dari anna. (sesungguhnya mereka itu telah menyampaikan) yakni rasul-rasul itu (risalah-risalah Rabbnya) di sini dipakai dhamir hum karena memandang segi makna yang terkandung di dalam lafal man (sedangkan, sebenarnya, ilmu-Nya meliputi apa yang ada pada mereka) diathafkan kepada lafal yang tidak disebutkan, lengkapnya ilmu mengenai hal tersebut telah diliputi oleh ilmu-Nya (dan Dia menghitung segala sesuatu satu per satu.\") lafal `adadan adalah tamyiz yang mengganti kedudukan maf`ulnya, asalnya ialah \"ahshaa `adada kulli syai'in,\" yakni Dia telah menghitung bilangan segala sesuatu.",[["لِّيَعْلَمَ","That He may make evident"],["أَن","that"],["قَدْ","indeed"],["أَبْلَغُوا۟","they have conveyed"],["رِسَـٰلَـٰتِ","(the) Messages"],["رَبِّهِمْ","(of) their Lord"],["وَأَحَاطَ","and He has encompassed"],["بِمَا","what"],["لَدَيْهِمْ","(is) with them"],["وَأَحْصَىٰ","and He takes account"],["كُلَّ","(of) all"],["شَىْءٍ","things"],["عَدَدًۢا","(in) number"]]],"5476":["(Hai orang yang berselimut) yakni Nabi Muhammad. Asal kata al-muzzammil ialah al-mutazammil, kemudian huruf ta diidghamkan kepada huruf za sehingga jadilah al-muzzammil, artinya, orang yang menyelimuti dirinya dengan pakaian sewaktu wahyu datang kepadanya karena merasa takut akan kehebatan wahyu itu.",[["يَـٰٓأَيُّهَا","O you"],["ٱلْمُزَّمِّلُ","who wraps himself"]]],"5477":["(Bangunlah di malam hari) maksudnya, salatlah di malam hari (kecuali sedikit.)",[["قُمِ","Stand"],["ٱلَّيْلَ","(in) the night"],["إِلَّا","except"],["قَلِيلًۭا","a little"]]],"5478":["(Yaitu seperduanya) menjadi badal dari lafal qaliilan; pengertian sedikit ini bila dibandingkan dengan keseluruhan waktu malam hari (atau kurangilah daripadanya) dari seperdua itu (sedikit) hingga mencapai sepertiganya.",[["نِّصْفَهُۥٓ","Half of it"],["أَوِ","or"],["ٱنقُصْ","lessen"],["مِنْهُ","from it"],["قَلِيلًا","a little"]]],"5479":["(Atau lebih dari seperdua) hingga mencapai dua pertiganya; pengertian yang terkandung di dalam lafal au menunjukkan makna boleh memilih. (Dan bacalah Alquran itu) mantapkanlah bacaannya (dengan perlahan-lahan.)",[["أَوْ","Or"],["زِدْ","add"],["عَلَيْهِ","to it"],["وَرَتِّلِ","and recite"],["ٱلْقُرْءَانَ","the Quran"],["تَرْتِيلًا","(with) measured rhythmic recitation"]]],"5480":["(Sesungguhnya Kami akan menurunkan kepadamu perkataan) atau bacaan Alquran (yang berat) yang hebat. Dikatakan berat mengingat kewajiban-kewajiban yang terkandung di dalamnya.",[["إِنَّا","Indeed, We"],["سَنُلْقِى","will cast"],["عَلَيْكَ","upon you"],["قَوْلًۭا","a Word"],["ثَقِيلًا","heavy"]]],"5481":["(Sesungguhnya bangun di waktu malam) maksudnya, melakukan salat sunah di malam hari sesudah tidur (lebih tepat) untuk khusyuk di dalam memahami bacaan Alquran (dan bacaan di waktu itu lebih berkesan) lebih jelas dan lebih mantap serta lebih berkesan.",[["إِنَّ","Indeed"],["نَاشِئَةَ","(the) rising"],["ٱلَّيْلِ","(at) the night"],["هِىَ","it"],["أَشَدُّ","(is) very hard"],["وَطْـًۭٔا","and most potent"],["وَأَقْوَمُ","and more suitable"],["قِيلًا","(for) Word"]]],"5482":["(Sesungguhnya kamu pada siang hari mempunyai urusan yang panjang) mempunyai banyak kesibukan, sehingga kamu tidak mempunyai cukup waktu untuk banyak membaca Alquran.",[["إِنَّ","Indeed"],["لَكَ","for you"],["فِى","in"],["ٱلنَّهَارِ","the day"],["سَبْحًۭا","(is) occupation"],["طَوِيلًۭا","prolonged"]]],"5483":["(Sebutlah nama Rabbmu) katakanlah bismillahirrahmanirrahiim di awal bacaan Alquranmu (dan curahkanlah) kerahkanlah dirimu (untuk beribadat kepada-Nya dengan ketekunan yang penuh) lafal tabtiilan ini adalah mashdar dari lafal batula, sengaja didatangkan demi untuk memelihara fawashil, dan merupakan lafal yang berakar dari lafal tabattul.",[["وَٱذْكُرِ","And remember"],["ٱسْمَ","(the) name"],["رَبِّكَ","(of) your Lord"],["وَتَبَتَّلْ","and devote yourself"],["إِلَيْهِ","to Him"],["تَبْتِيلًۭا","(with) devotion"]]],"5484":["Dialah (Rabb masyriq dan magrib, tiada Tuhan melainkan Dia, maka ambillah Dia sebagai pelindung) artinya serahkanlah semua urusan-urusanmu di bawah perlindungan-Nya.",[["رَّبُّ","(The) Lord"],["ٱلْمَشْرِقِ","(of) the east"],["وَٱلْمَغْرِبِ","and the west"],["لَآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ","Him"],["فَٱتَّخِذْهُ","so take Him"],["وَكِيلًۭا","(as) Disposer of Affairs"]]],"5485":["(Dan bersabarlah terhadap apa yang mereka ucapkan) bersabarlah kamu di dalam menghadapi gangguan orang-orang kafir Mekah (dan jauhilah mereka dengan cara yang baik) tanpa keluh-kesah; ayat ini diturunkan sebelum ada perintah memerangi mereka.",[["وَٱصْبِرْ","And be patient"],["عَلَىٰ","over"],["مَا","what"],["يَقُولُونَ","they say"],["وَٱهْجُرْهُمْ","and avoid them"],["هَجْرًۭا","an avoidance"],["جَمِيلًۭا","gracious"]]],"5486":["(Dan biarkanlah Aku) maksudnya biar Aku saja yang bertindak (terhadap orang-orang yang mendustakan itu) lafal al-mukadzdzibiin diathafkan kepada maf`ul atau kepada maf'ul ma`ah. Maknanya Akulah yang akan bertindak terhadap mereka; mereka adalah pemimpin-pemimpin kaum Quraisy (orang-orang yang mempunyai kemewahan) kemewahan hidup (dan beri tangguhlah mereka barang sebentar) dalam jangka waktu yang tidak lama, dan ternyata selang beberapa waktu kemudian, akhirnya mereka mati terbunuh dalam perang Badar.",[["وَذَرْنِى","And leave Me"],["وَٱلْمُكَذِّبِينَ","and the deniers"],["أُو۟لِى","possessors"],["ٱلنَّعْمَةِ","(of) the ease"],["وَمَهِّلْهُمْ","and allow them respite "],["قَلِيلًا","a little"]]],"5487":["(Karena sesungguhnya pada sisi Kami ada belenggu-belenggu) merupakan bentuk jamak dari lafal niklun, artinya belenggu-belenggu yang berat (dan neraka Jahim) yaitu neraka yang apinya sangat membakar.",[["إِنَّ","Indeed"],["لَدَيْنَآ","with Us"],["أَنكَالًۭا","(are) shackles"],["وَجَحِيمًۭا","and burning fire"]]],"5488":["(Dan makanan yang menyumbat di kerongkongan) mengganjal di kerongkongan, itu adalah buah pohon zaqum atau buah pohon dhari' atau buah pohon ghislin atau berupa duri api, apabila dimakan tidak dapat dikeluarkan dan pula tidak dapat masuk ke dalam perut (dan azab yang pedih) di samping azab yang telah disebutkan tadi, hal ini disediakan bagi orang-orang yang mendustakan Nabi saw.",[["وَطَعَامًۭا","And food"],["ذَا","that"],["غُصَّةٍۢ","chokes"],["وَعَذَابًا","and a punishment"],["أَلِيمًۭا","painful"]]],"5489":["(Pada hari berguncang) karena gempa yang dahsyat (bumi dan gunung-gunung, dan menjadilah gunung-gunung itu tumpukan-tumpukan) tumpukan-tumpukan pasir (yang beterbangan) menjadi debu yang beterbangan yang pada sebelumnya kokoh bersatu. Lafal mahiilan berasal dari lafal haala, yahiilu; bentuk asalnya adalah mahyuulun, kemudian karena mengingat harakat dhammah dianggap berat atas huruf ya, maka dipindahkan kepada huruf ha, sehingga jadilah mahuwylun. Kemudian huruf wawu dibuang karena mengingat kedudukannya yang zaidah, sehingga jadilah mahuylun, selanjutnya harakat damah diganti menjadi kasrah untuk menyesuaikannya dengan huruf ya, sehingga jadilah mahiilun.",[["يَوْمَ","(On the) Day"],["تَرْجُفُ","will quake"],["ٱلْأَرْضُ","the earth"],["وَٱلْجِبَالُ","and the mountains"],["وَكَانَتِ","and will become"],["ٱلْجِبَالُ","the mountains"],["كَثِيبًۭا","a heap of sand"],["مَّهِيلًا","pouring down"]]],"5490":["(Sesungguhnya Kami telah mengutus kepada kalian) hai penduduk Mekah (seorang rasul) yakni Nabi Muhammad saw. (yang menjadi saksi terhadap kalian) kelak di hari kiamat, tentang kedurhakaan-kedurhakaan yang telah kalian kerjakan (sebagaimana Kami telah mengutus, dahulu, seorang rasul kepada Firaun) yakni Nabi Musa a.s.",[["إِنَّآ","Indeed, We"],["أَرْسَلْنَآ","[We] have sent"],["إِلَيْكُمْ","to you"],["رَسُولًۭا","a Messenger"],["شَـٰهِدًا","(as) a witness"],["عَلَيْكُمْ","upon you"],["كَمَآ","as"],["أَرْسَلْنَآ","We sent"],["إِلَىٰ","to"],["فِرْعَوْنَ","Firaun"],["رَسُولًۭا","a Messenger"]]],"5491":["(Maka Firaun mendurhakai rasul itu, lalu Kami siksa dia dengan siksaan yang berat) atau azab yang keras.",[["فَعَصَىٰ","But disobeyed"],["فِرْعَوْنُ","Firaun"],["ٱلرَّسُولَ","the Messenger"],["فَأَخَذْنَـٰهُ","so We seized him"],["أَخْذًۭا","(with) a seizure"],["وَبِيلًۭا","ruinous"]]],"5492":["(Maka bagaimanakah kalian dapat memelihara diri kalian jika tetap kafir) di dunia (kepada hari) lafal yauman menjadi maf'ul kedua dari lafal tattaquuna. Yakni memelihara diri dari azab hari itu. Atau dengan kata lain, dengan benteng apakah kalian memelihara diri dari azab pada hari itu (yang menjadikan anak-anak beruban) lafal syiiban bentuk jamak dari lafal asyyab; dikatakan anak-anak beruban, sebagai gambaran tentang hari itu yang penuh dengan kengerian yang sangat mencekam; hari yang dimaksud adalah hari kiamat. Bentuk asal lafal syiiban adalah syuyban, dengan memakai harakat damah pada huruf syin. Kemudian harakat itu diganti menjadi kasrah demi untuk menyelaraskannya dengan huruf ya yang jatuh sesudahnya, sehingga jadilah syiiban. Dikatakan di dalam menggambarkan hari yang penuh dengan malapetaka, yaumun yusyiibu nawaashial athfaali, yakni hari yang dapat membuat ubun-ubun anak-anak beruban. Ungkapan ini adalah ungkapan majaz atau kata kiasan. Akan tetapi boleh juga makna yang terkandung di dalam ayat ini dimaksud adalah makna hakiki bukan majazi.",[["فَكَيْفَ","Then how"],["تَتَّقُونَ","will you guard yourselves"],["إِن","if"],["كَفَرْتُمْ","you disbelieve"],["يَوْمًۭا","a Day"],["يَجْعَلُ","(that) will make"],["ٱلْوِلْدَٰنَ","the children"],["شِيبًا","gray-haired"]]],"5493":["(Langit pun menjadi pecah belah) menjadi retak dan pecah-pecah (pada hari itu) mengingat beratnya hari itu. (Adalah janji Dia) janji Allah swt. mengenai kedatangan hari itu (pasti terlaksana) pasti terjadi.",[["ٱلسَّمَآءُ","The heaven"],["مُنفَطِرٌۢ","(will) break apart"],["بِهِۦ ۚ","therefrom"],["كَانَ","is"],["وَعْدُهُۥ","His Promise"],["مَفْعُولًا","to be fulfilled"]]],"5494":["(Sesungguhnya ini) yaitu ayat-ayat yang memperingatkan ini (adalah suatu peringatan) suatu nasihat bagi semua makhluk. (Maka barang siapa yang menghendaki niscaya ia menempuh jalan kepada Rabbnya) menempuh jalan yang menyampaikan kepada-Nya, yaitu melalui iman dan taat kepada-Nya.",[["إِنَّ","Indeed"],["هَـٰذِهِۦ","this"],["تَذْكِرَةٌۭ ۖ","(is) a Reminder"],["فَمَن","then whoever"],["شَآءَ","wills"],["ٱتَّخَذَ","(let him) take"],["إِلَىٰ","to"],["رَبِّهِۦ","his Lord"],["سَبِيلًا","a way"]]],"5495":["(Sesungguhnya Rabbmu mengetahui bahwasanya kamu berdiri, salat, kurang) kurang sedikit (dari dua pertiga malam, atau seperdua malam, atau sepertiganya) jika dibaca nishfihi dan tsulutsihi berarti diathafkan kepada lafal tsulutsay; dan jika dibaca nishfahu dan tsulutsahu berarti diathafkan kepada lafal adnaa. Pengertian berdiri atau melakukan salat sunat di malam hari di sini pengertiannya sama dengan apa yang terdapat di awal surah ini, yakni sesuai dengan apa yang telah diperintahkan Allah kepadanya (dan segolongan dari orang-orang yang bersama kamu) lafal ayat ini diathafkan kepada dhamir yang terkandung di dalam lafal taquumu, demikian pula sebagian orang-orang yang bersamamu. Pengathafan ini diperbolehkan sekalipun tanpa mengulangi huruf taukidnya, demikian itu karena mengingat adanya fashl atau pemisah. Makna ayat secara lengkap, dan segolongan orang-orang yang bersama kamu yang telah melakukan hal yang sama. Mereka melakukan demikian mengikuti jejak Nabi saw. sehingga disebutkan, bahwa ada di antara mereka orang-orang yang tidak menyadari berapa rakaat salat malam yang telah mereka kerjakan, dan waktu malam tinggal sebentar lagi. Sesungguhnya Nabi saw. selalu melakukan salat sunah sepanjang malam, karena demi melaksanakan perintah Allah secara hati-hati. Para sahabat mengikuti jejaknya selama satu tahun, atau lebih dari satu tahun, sehingga disebutkan bahwa telapak-telapak kaki mereka bengkak-bengkak karena terlalu banyak salat. Akhirnya Allah swt. memberikan keringanan kepada mereka. (Dan Allah menetapkan) menghitung (ukuran malam dan siang. Dia mengetahui bahwa) huruf an adalah bentuk takhfif dari anna sedangkan isimnya tidak disebutkan, asalnya ialah annahu (kalian sekali-kali tidak dapat menentukan batas waktu-waktu itu) yaitu waktu malam hari. Kalian tidak dapat melakukan salat malam sesuai dengan apa yang diwajibkan atas kalian melainkan kalian harus melakukannya sepanjang malam. Dan yang demikian itu memberatkan kalian (maka Dia mengampuni kalian) artinya, Dia mencabut kembali perintah-Nya dan memberikan keringanan kepada kalian (karena itu bacalah apa yang mudah dari Alquran) dalam salat kalian (Dia mengetahui, bahwa) huruf an adalah bentuk takhfif dari anna, lengkapnya annahu (akan ada di antara kalian orang-orang yang sakit dan orang-orang yang berjalan di muka bumi) atau melakukan perjalanan (mencari sebagian karunia Allah) dalam rangka mencari rezeki-Nya melalui berniaga dan lain-lainnya (dan orang-orang yang lain lagi, mereka berperang di jalan Allah) ketiga golongan orang-orang tersebut, amat berat bagi mereka hal-hal yang telah disebutkan tadi menyangkut salat malam. Akhirnya Allah memberikan keringanan kepada mereka, yaitu mereka diperbolehkan melakukan salat malam sebatas kemampuan masing-masing. Kemudian ayat ini dinasakh oleh ayat yang mewajibkan salat lima waktu (maka bacalah apa yang mudah dari Alquran) sebagaimana yang telah disebutkan di atas (dan dirikanlah salat) fardu (tunaikanlah zakat dan berikanlah pinjaman kepada Allah) seumpamanya kalian membelanjakan sebagian harta kalian yang bukan zakat kepada jalan kebajikan (pinjaman yang baik) yang ditunaikan dengan hati yang tulus ikhlas. (Dan kebaikan apa saja yang kalian perbuat untuk diri kalian, niscaya kalian akan memperoleh balasannya di sisi Allah sebagai balasan yang jauh lebih baik) dari apa yang telah kalian berikan. Lafal huwa adalah dhamir fashal. Lafal maa sekalipun bukan termasuk isim makrifat akan tetapi diserupakan dengan isim makrifat karena tidak menerima takrif (dan yang paling besar pahalanya. Mohonlah ampun kepada Allah, sesungguhnya Allah Maha Pengampun lagi Maha Penyayang) kepada orang-orang mukmin.",[["۞ إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["يَعْلَمُ","knows"],["أَنَّكَ","that you"],["تَقُومُ","stand"],["أَدْنَىٰ","(a little) less"],["مِن","than"],["ثُلُثَىِ","two-thirds"],["ٱلَّيْلِ","(of) the night"],["وَنِصْفَهُۥ","and half of it"],["وَثُلُثَهُۥ","and a third of it"],["وَطَآئِفَةٌۭ","and (so do) a group"],["مِّنَ","of"],["ٱلَّذِينَ","those who"],["مَعَكَ ۚ","(are) with you"],["وَٱللَّهُ","And Allah"],["يُقَدِّرُ","determines"],["ٱلَّيْلَ","the night"],["وَٱلنَّهَارَ ۚ","and the day"],["عَلِمَ","He knows"],["أَن","that"],["لَّن","not"],["تُحْصُوهُ","you count it"],["فَتَابَ","so He has turned"],["عَلَيْكُمْ ۖ","to you"],["فَٱقْرَءُوا۟","so recite"],["مَا","what"],["تَيَسَّرَ","is easy"],["مِنَ","of"],["ٱلْقُرْءَانِ ۚ","the Quran"],["عَلِمَ","He knows"],["أَن","that"],["سَيَكُونُ","there will be"],["مِنكُم","among you"],["مَّرْضَىٰ ۙ","sick"],["وَءَاخَرُونَ","and others"],["يَضْرِبُونَ","traveling"],["فِى","in"],["ٱلْأَرْضِ","the land"],["يَبْتَغُونَ","seeking"],["مِن","of"],["فَضْلِ","(the) Bounty"],["ٱللَّهِ ۙ","(of) Allah"],["وَءَاخَرُونَ","and others"],["يُقَـٰتِلُونَ","fighting"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ ۖ","(of) Allah"],["فَٱقْرَءُوا۟","So recite"],["مَا","what"],["تَيَسَّرَ","is easy"],["مِنْهُ ۚ","of it"],["وَأَقِيمُوا۟","and establish"],["ٱلصَّلَوٰةَ","the prayer"],["وَءَاتُوا۟","and give"],["ٱلزَّكَوٰةَ","the zakah"],["وَأَقْرِضُوا۟","and loan"],["ٱللَّهَ","Allah"],["قَرْضًا","a loan"],["حَسَنًۭا ۚ","goodly"],["وَمَا","And whatever"],["تُقَدِّمُوا۟","you send forth"],["لِأَنفُسِكُم","for yourselves"],["مِّنْ","of"],["خَيْرٍۢ","good"],["تَجِدُوهُ","you will find it"],["عِندَ","with"],["ٱللَّهِ","Allah"],["هُوَ","It"],["خَيْرًۭا","(will be) better"],["وَأَعْظَمَ","and greater"],["أَجْرًۭا ۚ","(in) reward"],["وَٱسْتَغْفِرُوا۟","And seek forgiveness"],["ٱللَّهَ ۖ","(of) Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۢ","Most Merciful"]]],"5496":["(Hai orang yang berselimut!) yakni Nabi saw. Bentuk asal lafal al-muddatstsir ialah al-mutadatstsir, kemudian huruf ta diidgamkan kepada huruf dal sehingga jadilah al-Muddatstsir, artinya orang yang menyelimuti dirinya dengan pakaiannya sewaktu wahyu turun kepadanya.",[["يَـٰٓأَيُّهَا","O you"],["ٱلْمُدَّثِّرُ","who covers himself"]]],"5497":["(Bangunlah, lalu berilah peringatan) maksudnya pertakutilah penduduk Mekah dengan neraka jika mereka tidak mau beriman.",[["قُمْ","Stand up"],["فَأَنذِرْ","and warn"]]],"5498":["(Dan Rabbmu agungkanlah) agungkanlah Dia dari persekutuan yang diada-adakan oleh orang-orang musyrik.",[["وَرَبَّكَ","And your Lord"],["فَكَبِّرْ","magnify"]]],"5499":["(Dan pakaianmu bersihkanlah) dari najis, atau pendekkanlah pakaianmu sehingga berbeda dengan kebiasaan orang-orang Arab yang selalu menguntaikan pakaian mereka hingga menyentuh tanah di kala mereka menyombongkan diri, karena dikhawatirkan akan terkena barang yang najis.",[["وَثِيَابَكَ","And your clothing"],["فَطَهِّرْ","purify"]]],"5500":["(Dan perbuatan dosa) lafal Ar-Rujza ditafsirkan oleh Nabi saw. berhala-berhala (tinggalkanlah) hal itu untuk selama-lamanya.",[["وَٱلرُّجْزَ","And uncleanliness"],["فَٱهْجُرْ","avoid"]]],"5501":["(Dan janganlah kamu memberi dengan maksud memperoleh balasan yang lebih banyak) lafal Tastaktsiru dibaca Rafa' berkedudukan sebagai Haal atau kata keterangan keadaan. Maksudnya, janganlah kamu memberi sesuatu dengan tujuan untuk memperoleh balasan yang lebih banyak dari apa yang telah kamu berikan. Hal ini khusus berlaku hanya bagi Nabi saw. karena sesungguhnya dia diperintahkan untuk mengerjakan akhlak-akhlak yang paling mulia dan pekerti yang paling baik.",[["وَلَا","And (do) not"],["تَمْنُن","confer favor"],["تَسْتَكْثِرُ","(to) acquire more"]]],"5502":["(Dan kepada Rabbmu bersabarlah) di dalam melaksanakan perintah-perintah dan menjauhi larangan-larangan-Nya.",[["وَلِرَبِّكَ","And for your Lord"],["فَٱصْبِرْ","be patient"]]],"5503":["(Apabila ditiup sangkakala) untuk tiupan yang kedua, guna membangkitkan manusia.",[["فَإِذَا","Then when"],["نُقِرَ","is blown"],["فِى","in"],["ٱلنَّاقُورِ","the trumpet"]]],"5504":["(Maka waktu itu) waktu peniupan sangkakala yang kedua (adalah waktu) lafal Yaumaidzin berkedudukan menjadi Badal dari lafal yang sebelumnya, dan sekaligus menjadi Mubtada. Lafal Yaumaidzin dimabnikan karena mengingat dimudhafkan kepada Isim yang Ghairu Mutamakkin. Kemudian yang menjadi Khabarnya ialah (datangnya hari yang sulit) Amil yang mempengaruhi lafal Idza adalah kalimat yang disimpulkan dari pengertian keseluruhannya. Yakni pada hari itu perkara dirasakan amat berat.",[["فَذَٰلِكَ","That"],["يَوْمَئِذٍۢ","Day"],["يَوْمٌ","(will be) a Day"],["عَسِيرٌ","difficult"]]],"5505":["(Bagi orang-orang kafir lagi tidak mudah) di dalam ungkapan ini terkandung pengertian, bahwa keadaan pada hari itu dirasakan amat ringan oleh orang-orang yang beriman di balik kesulitan yang dirasakan oleh orang-orang kafir.",[["عَلَى","For"],["ٱلْكَـٰفِرِينَ","the disbelievers "],["غَيْرُ","not"],["يَسِيرٍۢ","easy"]]],"5506":["(Biarkanlah Aku) artinya, serahkanlah kepada-Ku (untuk menindak orang yang Aku ciptakan) lafal Waman di'athafkan kepada Maf'ul atau kepada Maf'ul Ma'ah (dalam keadaan sendirian) menjadi Haal atau kata keterangan keadaan bagi lafal Man, atau bagi Dhamirnya yang tidak disebutkan. Maksudnya, orang yang diciptakan-Nya hanya dia sendiri, tanpa keluarga, tanpa harta benda, dia adalah Walid bin Mughirah Al-Makhzumi.",[["ذَرْنِى","Leave Me"],["وَمَنْ","and whom"],["خَلَقْتُ","I created"],["وَحِيدًۭا","alone"]]],"5507":["(Dan Aku jadikan baginya harta benda yang banyak) harta yang luas dan berlimpah, berupa tanam-tanaman, susu perahan, dan perniagaan.",[["وَجَعَلْتُ","And I granted"],["لَهُۥ","to him"],["مَالًۭا","wealth"],["مَّمْدُودًۭا","extensive"]]],"5508":["(Dan anak-anak) yang jumlahnya sepuluh orang atau lebih (yang selalu bersama dia) di kala menyaksikan perayaan-perayaan dan kamu pun mendengar tentang persaksian mereka itu.",[["وَبَنِينَ","And children"],["شُهُودًۭا","present"]]],"5509":["(Dan Kulapangkan) Kuluaskan (baginya) kehidupan, umurnya dan anak-anak yang dimilikinya (dengan selapang-lapangnya.)",[["وَمَهَّدتُّ","And I spread"],["لَهُۥ","for him"],["تَمْهِيدًۭا","ease"]]],"5510":["(Kemudian dia ingin sekali supaya Aku menambahkannya.)",[["ثُمَّ","Then"],["يَطْمَعُ","he desires"],["أَنْ","that"],["أَزِيدَ","I (should) add more"]]],"5511":["(Sekali-kali tidak) Aku tidak akan memberikan tambahan lagi kepadanya selain dari hal tersebut (karena sesungguhnya dia terhadap ayat-ayat Kami) yakni terhadap Alquran (selalu menentang) selalu melawan dan ingkar.",[["كَلَّآ ۖ","By no means"],["إِنَّهُۥ","Indeed, he"],["كَانَ","has been"],["لِـَٔايَـٰتِنَا","to Our Verses"],["عَنِيدًۭا","stubborn"]]],"5512":["(Aku akan membebaninya) Aku akan memberatinya (mendaki pendakian yang memayahkan) yaitu kepayahan karena azab; atau gunung api yang dia daki, kemudian dia jatuh, demikianlah untuk selama-lamanya.",[["سَأُرْهِقُهُۥ","Soon I will cover Him"],["صَعُودًا","(with) a laborious punishment"]]],"5513":["(Sesungguhnya dia telah memikirkan) tentang apa yang dikatakannya mengenai Alquran yang ia dengar dari Nabi saw. (dan menetapkan) di dalam dirinya hal tersebut.",[["إِنَّهُۥ","Indeed, he"],["فَكَّرَ","thought"],["وَقَدَّرَ","and plotted"]]],"5514":["(Maka celakalah dia) dikutuk dan diazablah dia. (Bagaimanakah dia menetapkan?) maksudnya, keadaan apakah yang telah ditetapkannya itu?",[["فَقُتِلَ","So may he be destroyed"],["كَيْفَ","how"],["قَدَّرَ","he plotted"]]],"5515":["(Kemudian celakalah dia. Bagaimanakah dia menetapkan?)",[["ثُمَّ","Then"],["قُتِلَ","may he be destroyed"],["كَيْفَ","how"],["قَدَّرَ","he plotted"]]],"5516":["(Kemudian ia memikirkan) rencana yang ditekuninya itu, atau dia melayangkan pandangannya ke muka kaumnya.",[["ثُمَّ","Then"],["نَظَرَ","he looked"]]],"5517":["(Sesudah itu dia bermasam muka) mukanya cemberut dan suram karena merasa sempit dengan apa yang dikatakannya (dan merengut) makin bertambah masam mukanya.",[["ثُمَّ","Then"],["عَبَسَ","he frowned"],["وَبَسَرَ","and scowled"]]],"5518":["(Kemudian dia berpaling) dari iman (dan menyombongkan diri) sombong tidak mau mengikut Nabi saw.",[["ثُمَّ","Then"],["أَدْبَرَ","he turned back"],["وَٱسْتَكْبَرَ","and was proud"]]],"5519":["(Lalu dia berkata) di dalam menanggapi apa yang didatangkan oleh Nabi saw. yakni Alquran (\"Tiada lain) (Alquran ini hanyalah sihir yang dipelajari\") maksudnya, yang diambil dari tukang-tukang sihir.",[["فَقَالَ","Then he said"],["إِنْ","Not"],["هَـٰذَآ","(is) this"],["إِلَّا","but"],["سِحْرٌۭ","magic"],["يُؤْثَرُ","imitated"]]],"5520":["(\"Tiada lain) (ini hanyalah perkataan manusia\") sama dengan apa yang dikatakan oleh orang-orang musyrik lainnya, yaitu bahwasanya Alquran ini diajarkan kepadanya oleh manusia.",[["إِنْ","Not"],["هَـٰذَآ","(is) this"],["إِلَّا","but"],["قَوْلُ","(the) word"],["ٱلْبَشَرِ","(of) a human being"]]],"5521":["(Aku akan memasukkannya) akan menjerumuskannya (ke dalam Saqar) yakni neraka Jahanam.",[["سَأُصْلِيهِ","Soon I will drive him"],["سَقَرَ","(into) Hell"]]],"5522":["(Tahukah kamu, apakah Saqar itu?) ungkapan ini menggambarkan tentang kedahsyatannya.",[["وَمَآ","And what"],["أَدْرَىٰكَ","can make you know"],["مَا","what"],["سَقَرُ","(is) Hell"]]],"5523":["(Saqar itu tidak meninggalkan dan tidak membiarkan) sedikit pun dari daging dan otot melainkan dia melahapnya habis-habisan, kemudian daging dan otot itu kembali seperti semula, lalu dilahapnya lagi, demikianlah seterusnya.",[["لَا","Not"],["تُبْقِى","it lets remain"],["وَلَا","and not"],["تَذَرُ","it leaves"]]],"5524":["(Lagi sangat membakar kulit manusia) membakar permukaan kulit dengan cepat.",[["لَوَّاحَةٌۭ","Scorching"],["لِّلْبَشَرِ","the human (skin)"]]],"5525":["(Di atasnya ada sembilan belas) malaikat yang bertugas menjaganya. Seorang di antara orang-orang kafir yang terkenal dengan kekuatan dan kekerasan tubuhnya mengatakan, \"Aku menjamin kalian untuk dapat mengalahkan tujuh belas malaikat itu, dan kalian harus menjamin aku untuk dapat mengalahkan dua malaikat lainnya.\" Maka Allah berfirman:",[["عَلَيْهَا","Over it"],["تِسْعَةَ","(are) nine"],["عَشَرَ","teen"]]],"5526":["(Dan tiada Kami jadikan penjaga neraka itu melainkan malaikat) yakni mereka tidak akan dapat dilawan, tidak sebagaimana yang diduga oleh orang-orang kafir (dan tidaklah Kami menjadikan bilangan mereka) yang sembilan belas itu (melainkan untuk jadi cobaan) atau membawa kepada kesesatan (bagi orang-orang kafir) seumpamanya mereka mengatakan, mengapa jumlah malaikat-malaikat penjaga neraka itu hanya sembilan belas? (supaya menjadi yakin) menjadi tambah jelas (orang-orang yang diberi Alkitab) artinya, supaya orang-orang Yahudi yakin akan kebenaran Nabi saw. yang telah menyatakan bahwa jumlah mereka sembilan belas malaikat, dan ini sesuai dengan keterangan yang terdapat di dalam kitab mereka (dan supaya orang-orang yang beriman bertambah) yaitu, orang-orang yang beriman dari kalangan ahli kitab (imannya) kepercayaannya, karena apa yang dijelaskan oleh Nabi saw. itu sesuai dan cocok dengan keterangan yang terdapat di dalam Kitab mereka (dan supaya orang-orang yang diberi Alkitab dan orang-orang mukmin itu tidak ragu-ragu) yaitu orang-orang yang beriman bukan dari kalangan mereka; tentang bilangan malaikat-malaikat penjaga neraka itu (dan supaya orang-orang yang di dalam hatinya ada penyakit) berupa keragu-raguan; mereka berada di Madinah (dan orang-orang kafir mengatakan) yaitu orang-orang kafir Mekah: (\"Apakah yang dikehendaki Allah dengan hal ini) yakni bilangan ini (sebagai suatu perumpamaan?\") mereka menamakannya sebagai perumpamaan, karena hal itu amat aneh didengar oleh mereka. Lafal Matsalan berkedudukan sebagai Haal atau kata keterangan keadaan. (Demikianlah) sebagaimana disesatkan-Nya orang yang tidak mempercayai bilangan ini, dan diberi-Nya petunjuk orang yang percaya kepada-Nya (Allah membiarkan sesat orang-orang yang dikehendaki-Nya dan memberi petunjuk kepada siapa yang dikehendaki-Nya. Dan tidak ada yang mengetahui tentara Rabbmu) yaitu malaikat-malaikat tentang kekuatan dan kemampuan mereka (melainkan Dia sendiri. Dan Saqar itu tiada lain) neraka itu (hanyalah peringatan bagi manusia.)",[["وَمَا","And not"],["جَعَلْنَآ","We have made"],["أَصْحَـٰبَ","keepers"],["ٱلنَّارِ","(of) the Fire"],["إِلَّا","except"],["مَلَـٰٓئِكَةًۭ ۙ","Angels"],["وَمَا","And not"],["جَعَلْنَا","We have made"],["عِدَّتَهُمْ","their number"],["إِلَّا","except"],["فِتْنَةًۭ","(as) a trial"],["لِّلَّذِينَ","for those who"],["كَفَرُوا۟","disbelieve "],["لِيَسْتَيْقِنَ","that may be certain"],["ٱلَّذِينَ","those who"],["أُوتُوا۟","were given"],["ٱلْكِتَـٰبَ","the Scripture"],["وَيَزْدَادَ","and may increase"],["ٱلَّذِينَ","those who"],["ءَامَنُوٓا۟","believe"],["إِيمَـٰنًۭا ۙ","(in) faith"],["وَلَا","and not"],["يَرْتَابَ","may doubt"],["ٱلَّذِينَ","those who"],["أُوتُوا۟","were given"],["ٱلْكِتَـٰبَ","the Scripture"],["وَٱلْمُؤْمِنُونَ ۙ","and the believers"],["وَلِيَقُولَ","and that may say"],["ٱلَّذِينَ","those"],["فِى","in"],["قُلُوبِهِم","their hearts"],["مَّرَضٌۭ","(is) a disease"],["وَٱلْكَـٰفِرُونَ","and the disbelievers"],["مَاذَآ","What"],["أَرَادَ","(does) intend"],["ٱللَّهُ","Allah"],["بِهَـٰذَا","by this"],["مَثَلًۭا ۚ","example"],["كَذَٰلِكَ","Thus"],["يُضِلُّ","does let go astray"],["ٱللَّهُ","Allah"],["مَن","whom"],["يَشَآءُ","He wills"],["وَيَهْدِى","and guides"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["وَمَا","And none"],["يَعْلَمُ","knows"],["جُنُودَ","(the) hosts"],["رَبِّكَ","(of) your Lord"],["إِلَّا","except"],["هُوَ ۚ","Him"],["وَمَا","And not"],["هِىَ","it"],["إِلَّا","(is) but"],["ذِكْرَىٰ","a reminder"],["لِلْبَشَرِ","to (the) human beings"]]],"5527":["(Ingatlah) lafal Kallaa pada ayat ini merupakan lafal yang mengandung makna Istiftah atau kata pembuka, artinya, ingatlah (demi bulan.)",[["كَلَّا","Nay"],["وَٱلْقَمَرِ","By the moon"]]],"5528":["(Dan malam ketika) dibaca Idzaa bukan Idz (datang) sesudah siang hari habis. Akan tetapi menurut suatu qiraat dibaca Adbara, yakni telah berlalu.",[["وَٱلَّيْلِ","And the night"],["إِذْ","when"],["أَدْبَرَ","it departs"]]],"5529":["(Dan subuh apabila mulai terang) mulai menampakkan sinarnya.",[["وَٱلصُّبْحِ","And the morning"],["إِذَآ","when"],["أَسْفَرَ","it brightens"]]],"5530":["(Sesungguhnya Saqar itu) neraka Saqar itu (adalah salah satu bencana yang amat besar) malapetaka yang paling besar.",[["إِنَّهَا","Indeed, it"],["لَإِحْدَى","(is) surely one"],["ٱلْكُبَرِ","(of) the greatest"]]],"5531":["(Sebagai ancaman) berkedudukan menjadi Haal dari lafal Ihdaa, disebutkan karena mengingat di dalamnya terkandung makna azab (bagi manusia.)",[["نَذِيرًۭا","A warning"],["لِّلْبَشَرِ","to (the) human being"]]],"5532":["(Yaitu bagi siapa di antara kalian) lafal ayat ini berkedudukan sebagai Badal dari lafal Al-Basyar (yang berkehendak akan maju) kepada kebaikan atau surga dengan beriman (atau mundur) menuju kepada perbuatan dosa, atau neraka dengan melakukan kekafiran.",[["لِمَن","To whoever"],["شَآءَ","wills"],["مِنكُمْ","among you"],["أَن","to"],["يَتَقَدَّمَ","proceed"],["أَوْ","or"],["يَتَأَخَّرَ","stay behind"]]],"5533":["(Tiap-tiap diri bertanggung jawab atas apa yang telah diperbuatnya) dia tergadaikan, yaitu diazab di dalam neraka disebabkan amal perbuatannya sendiri.",[["كُلُّ","Every"],["نَفْسٍۭ","soul"],["بِمَا","for what"],["كَسَبَتْ","it has earned"],["رَهِينَةٌ","(is) pledged"]]],"5534":["(Kecuali golongan kanan) mereka adalah orang-orang yang beriman, mereka selamat dari siksa neraka, di mana mereka berada.",[["إِلَّآ","Except"],["أَصْحَـٰبَ","(the) companions"],["ٱلْيَمِينِ","(of) the right"]]],"5535":["(Di dalam surga saling tanya-menanya) di antara sesama mereka.",[["فِى","In"],["جَنَّـٰتٍۢ","Gardens"],["يَتَسَآءَلُونَ","asking each other"]]],"5536":["(Tentang orang-orang yang berdosa) tentang keadaan orang-orang yang berdosa, lalu mereka berkata kepada ahli neraka sesudah orang-orang yang bertauhid dikeluarkan daripadanya:",[["عَنِ","About"],["ٱلْمُجْرِمِينَ","the criminals"]]],"5537":["(\"Apakah yang memasukkan kalian) yang menjerumuskan kalian (ke dalam Saqar?\")",[["مَا","What"],["سَلَكَكُمْ","led you"],["فِى","into"],["سَقَرَ","Hell"]]],"5538":["(Mereka menjawab, \"Kami dahulu tidak termasuk orang-orang yang mengerjakan salat,)",[["قَالُوا۟","They will say"],["لَمْ","Not"],["نَكُ","we were"],["مِنَ","of"],["ٱلْمُصَلِّينَ","those who prayed"]]],"5539":["(dan Kami tidak pula memberi makan orang miskin.)",[["وَلَمْ","And not"],["نَكُ","we used to"],["نُطْعِمُ","feed"],["ٱلْمِسْكِينَ","the poor"]]],"5540":["(Dan adalah Kami tenggelam ke dalam pembicaraan) yang batil (bersama dengan orang-orang yang membicarakannya.)",[["وَكُنَّا","And we used to"],["نَخُوضُ","indulge in vain talk"],["مَعَ","with"],["ٱلْخَآئِضِينَ","the vain talkers"]]],"5541":["(Dan adalah Kami mendustakan hari pembalasan) yakni hari berbangkit dan hari pembalasan.",[["وَكُنَّا","And we used to"],["نُكَذِّبُ","deny"],["بِيَوْمِ","(the) Day"],["ٱلدِّينِ","(of) the Judgment"]]],"5542":["(Hingga datang kepada kami kematian\") ajal kami.",[["حَتَّىٰٓ","Until"],["أَتَىٰنَا","came to us"],["ٱلْيَقِينُ","the certainty"]]],"5543":["(Maka tidak berguna lagi bagi mereka syafaat dari orang-orang yang memberi syafaat) baik dari kalangan malaikat, para nabi atau pun orang-orang saleh. Makna yang dimaksud ialah bahwa tiada syafaat bagi mereka.",[["فَمَا","Then not"],["تَنفَعُهُمْ","will benefit them"],["شَفَـٰعَةُ","intercession"],["ٱلشَّـٰفِعِينَ","(of) the intercessors"]]],"5544":["(Maka mengapa) berkedudukan menjadi Mubtada (mereka) menjadi Khabar dari Mubtada, berta'alluq kepada lafal yang tidak disebutkan yang Dhamirnya dipindahkan kepadanya (berpaling dari peringatan?) lafal Mu'ridhiina menjadi Haal atau kata keterangan keadaan dari Dhamir Lahum. Makna yang dimaksud, apakah gerangan sesuatu yang terjadi pada diri mereka sehingga mereka berpaling dari peringatan?",[["فَمَا","Then what"],["لَهُمْ","(is) for them"],["عَنِ","(that) from"],["ٱلتَّذْكِرَةِ","the Reminder"],["مُعْرِضِينَ","they (are) turning away"]]],"5545":["(Seakan-akan mereka itu keledai liar yang lari terkejut) keledai-keledai liar yang larat.",[["كَأَنَّهُمْ","As if they (were)"],["حُمُرٌۭ","donkeys"],["مُّسْتَنفِرَةٌۭ","frightened"]]],"5546":["(Lari dari singa) lari sekencang-kencangnya karena menghindar dan menyelamatkan diri dari singa.",[["فَرَّتْ","Fleeing"],["مِن","from"],["قَسْوَرَةٍۭ","a lion"]]],"5547":["(Bahkan tiap-tiap orang dari mereka berkehendak supaya diberikan kepadanya lembaran-lembaran yang terbuka) dari Allah swt. disebabkan mengikuti Nabi saw. Sebagaimana yang telah mereka katakan, bahwa tidak sekali-kali kami beriman kepadamu sebelum kamu menurunkan kepada kami sebuah kitab yang kami baca.",[["بَلْ","Nay"],["يُرِيدُ","Desires"],["كُلُّ","every"],["ٱمْرِئٍۢ","person"],["مِّنْهُمْ","of them"],["أَن","that"],["يُؤْتَىٰ","he may be given"],["صُحُفًۭا","pages"],["مُّنَشَّرَةًۭ","spread out"]]],"5548":["(Sekali-kali tidak) lafal ini merupakan sanggahan terhadap apa yang mereka kehendaki itu. (Sebenarnya mereka tidak takut kepada negeri akhirat) kepada azabnya.",[["كَلَّا ۖ","Nay"],["بَل","But"],["لَّا","not"],["يَخَافُونَ","they fear"],["ٱلْـَٔاخِرَةَ","the Hereafter"]]],"5549":["(Ingatlah) Kallaa di sini menunjukkan makna Istiftah atau kata pembukaan (sesungguhnya dia itu) Alquran itu (adalah peringatan) nasihat dan pelajaran.",[["كَلَّآ","Nay"],["إِنَّهُۥ","Indeed, it"],["تَذْكِرَةٌۭ","(is) a Reminder"]]],"5550":["(Maka barang siapa menghendaki, niscaya dia mengambil pelajaran daripadanya) niscaya dia membacanya kemudian mengambil pelajaran daripadanya.",[["فَمَن","So whoever"],["شَآءَ","wills"],["ذَكَرَهُۥ","(may) pay heed to it"]]],"5551":["(Dan mereka tidak akan mengambil pelajaran daripadanya) dapat dibaca Yadzkuruuna dan Tadzkuruuna (kecuali bila Allah menghendakinya. Dia adalah Tuhan Yang patut kita bertakwa kepada-Nya) Dia adalah yang harus ditakwai (dan berhak memberi ampun) seumpamanya Dia memberikan ampunan-Nya kepada orang-orang yang bertakwa kepada-Nya.",[["وَمَا","And not"],["يَذْكُرُونَ","will pay heed"],["إِلَّآ","except"],["أَن","that"],["يَشَآءَ","wills"],["ٱللَّهُ ۚ","Allah"],["هُوَ","He"],["أَهْلُ","(is) worthy"],["ٱلتَّقْوَىٰ","to be feared"],["وَأَهْلُ","and worthy"],["ٱلْمَغْفِرَةِ","to forgive"]]],"5552":["(Aku bersumpah dengan hari kiamat) huruf Laa di sini adalah huruf Zaidah.",[["لَآ","Nay"],["أُقْسِمُ","I swear"],["بِيَوْمِ","by (the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"]]],"5553":["(Dan Aku bersumpah dengan jiwa yang amat menyesali) dirinya sendiri sekalipun ia berupaya sekuat tenaga di dalam kebaikan. Jawab Qasam tidak disebutkan; lengkapnya, Aku bersumpah dengan nama hari kiamat dan dengan nama jiwa yang banyak mencela, bahwa niscaya jiwa itu pasti akan dibangkitkan. Pengertian Jawab ini ditunjukkan oleh firman selanjutnya, yaitu:",[["وَلَآ","And nay"],["أُقْسِمُ","I swear"],["بِٱلنَّفْسِ","by the soul"],["ٱللَّوَّامَةِ","self-accusing"]]],"5554":["(Apakah manusia mengira) yakni, orang kafir (bahwa Kami tidak akan mengumpulkan kembali tulang belulangnya) untuk dibangkitkan menjadi hidup kembali.",[["أَيَحْسَبُ","Does think"],["ٱلْإِنسَـٰنُ","[the] man"],["أَلَّن","that not"],["نَّجْمَعَ","We will assemble"],["عِظَامَهُۥ","his bones"]]],"5555":["(Bukan demikian) Kami akan mengumpulkannya kembali (Kami kuasa) di samping mengumpulkan kembali tulang-tulangnya itu (menyusun kembali jari-jemarinya dengan sempurna) artinya, Kami dapat mengembalikan tulang jari-jemari itu sekalipun bentuknya kecil, maka terlebih lagi tulang-tulang lainnya yang lebih besar daripadanya.",[["بَلَىٰ","Nay"],["قَـٰدِرِينَ","(We are) Able"],["عَلَىٰٓ","on"],["أَن","that"],["نُّسَوِّىَ","We can restore"],["بَنَانَهُۥ","his fingertips"]]],"5556":["(Bahkan manusia itu hendak membuat maksiat terus-menerus) huruf Lam yang ada pada lafal Liyafjura adalah Zaidah, sedangkan lafal Yafjuru dinashabkan oleh An yang diperkirakan keberadaannya. Yakni dia selalu berbuat dusta (di dalam menghadapinya) di dalam menghadapi hari kiamat. Pengertian ini ditunjukkan oleh firman selanjutnya, yaitu:",[["بَلْ","Nay"],["يُرِيدُ","Desires"],["ٱلْإِنسَـٰنُ","[the] man"],["لِيَفْجُرَ","to give (the) lie"],["أَمَامَهُۥ","(to) what is before him"]]],"5557":["(Ia bertanya, \"Bilakah) Kapan (hari kiamat itu?\") pertanyaannya itu mengandung nada mengejek dan mendustakannya.",[["يَسْـَٔلُ","He asks"],["أَيَّانَ","When"],["يَوْمُ","(is the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"]]],"5558":["(Maka apabila mata terbelalak) dapat dibaca Bariqa dan Baraqa, artinya kaget dan bimbang setelah ia melihat apa yang dahulu selalu ia dustakan.",[["فَإِذَا","So when"],["بَرِقَ","is dazzled"],["ٱلْبَصَرُ","the vision"]]],"5559":["(Dan apabila bulan telah hilang cahayanya) yakni menjadi gelap dan lenyap sinarnya.",[["وَخَسَفَ","And becomes dark"],["ٱلْقَمَرُ","the moon"]]],"5560":["(Dan matahari dan bulan dikumpulkan) maka kedua-duanya terbit dari arah barat; atau kedua-duanya telah hilang sinarnya, yang demikian itu terjadi pada hari kiamat.",[["وَجُمِعَ","And are joined"],["ٱلشَّمْسُ","the sun"],["وَٱلْقَمَرُ","and the moon"]]],"5561":["(Pada hari itu manusia berkata, \"Ke mana tempat lari?\")",[["يَقُولُ","Will say"],["ٱلْإِنسَـٰنُ","[the] man"],["يَوْمَئِذٍ","that Day"],["أَيْنَ","Where"],["ٱلْمَفَرُّ","(is) the escape"]]],"5562":["(Sekali-kali tidak) lafal ini menunjukkan kata tolakan terhadap pencarian jalan lari. (Tidak ada tempat berlindung) tidak ada tempat mengungsi yang dapat dijadikan perlindungan baginya.",[["كَلَّا","By no means"],["لَا","(There is) no"],["وَزَرَ","refuge"]]],"5563":["(Hanya kepada Rabbmu sajalah pada hari itu tempat kembali) bagi semua makhluk, lalu mereka dihisab dan menerima pembalasan.",[["إِلَىٰ","To"],["رَبِّكَ","your Lord"],["يَوْمَئِذٍ","that Day"],["ٱلْمُسْتَقَرُّ","(is) the place of rest"]]],"5564":["(Pada hari itu diberitakan kepada manusia apa yang telah dikerjakannya dan apa yang dilalaikannya) yaitu semua amal perbuatannya dari mulai awal hingga akhir, diberitakan kepadanya.",[["يُنَبَّؤُا۟","Will be informed"],["ٱلْإِنسَـٰنُ","[the] man"],["يَوْمَئِذٍۭ","that Day"],["بِمَا","of what"],["قَدَّمَ","he sent forth"],["وَأَخَّرَ","and kept back"]]],"5565":["(Bahkan manusia itu menjadi saksi atas dirinya sendiri) yakni semua anggota tubuhnya memberikan kesaksian terhadap semua amal perbuatannya, sehingga ia tidak dapat mengingkarinya lagi. Huruf Ha yang ada pada lafal Bashiirah menunjukkan makna Mubalaghah.",[["بَلِ","Nay"],["ٱلْإِنسَـٰنُ","[The] man"],["عَلَىٰ","against"],["نَفْسِهِۦ","himself"],["بَصِيرَةٌۭ","(will be) a witness"]]],"5566":["(Meskipun dia mengemukakan alasan-alasannya) lafal Ma'aadziir bentuk jamak dari lafal Ma'dzirah, akan tetapi tidak menurut cara yang beraturan. Makna ayat, seandainya dia mengemukakan semua alasannya, niscaya alasan-alasannya itu tidak akan diterima. Allah berfirman kepada Nabi-Nya:",[["وَلَوْ","Even if"],["أَلْقَىٰ","he presents"],["مَعَاذِيرَهُۥ","his excuses"]]],"5567":["(Janganlah kamu gerakkan untuk membacanya) membaca Alquran, sebelum malaikat Jibril selesai daripadanya (lisanmu karena hendak cepat-cepat menguasainya) karena kamu merasa khawatir bacaannya tidak dapat kamu kuasai.",[["لَا","Not"],["تُحَرِّكْ","move"],["بِهِۦ","with it"],["لِسَانَكَ","your tongue"],["لِتَعْجَلَ","to hasten"],["بِهِۦٓ","with it"]]],"5568":["(Sesungguhnya atas tanggungan Kamilah mengumpulkannya) di dadamu, maksudnya membuat kamu dapat menghafalnya (dan bacaannya) yakni membuatmu pandai membacanya; atau membuat mudah dibaca olehmu.",[["إِنَّ","Indeed"],["عَلَيْنَا","upon Us"],["جَمْعَهُۥ","(is) its collection"],["وَقُرْءَانَهُۥ","and its recitation"]]],"5569":["(Apabila Kami telah selesai membacakannya) kepada kamu melalui bacaan malaikat Jibril (maka ikutilah bacaannya itu) artinya, dengarlah dengan seksama bacaan Jibril kepadamu terlebih dahulu. Sesungguhnya Nabi saw. setelah itu mendengarkannya terlebih dahulu dengan seksama, kemudian membacanya.",[["فَإِذَا","And when"],["قَرَأْنَـٰهُ","We have recited it"],["فَٱتَّبِعْ","then follow"],["قُرْءَانَهُۥ","its recitation"]]],"5570":["(Kemudian, sesungguhnya atas tanggungan Kamilah penjelasannya) dengan memberikan pemahaman mengenainya kepadamu. Kaitan atau hubungan korelasi antara ayat ini dengan ayat-ayat sebelumnya ialah bahwasanya ayat-ayat sebelumnya itu mengandung makna berpaling dari ayat-ayat Allah. Sedangkan pada ayat ini terkandung pengertian bersegera menguasai ayat-ayat Allah dengan cara menghafalnya.",[["ثُمَّ","Then"],["إِنَّ","indeed"],["عَلَيْنَا","upon Us"],["بَيَانَهُۥ","(is) its explanation"]]],"5571":["(Sekali-kali jangan) lafal Kallaa menunjukkan makna Istiftah, yakni ingatlah (sebenarnya kalian mencintai kehidupan dunia) dapat dibaca Tuhibbuuna dan Yuhibbuuna, kalau dibaca Yuhibbuuna artinya, mereka mencintai kehidupan dunia.",[["كَلَّا","No"],["بَلْ","But"],["تُحِبُّونَ","you love"],["ٱلْعَاجِلَةَ","the immediate"]]],"5572":["(Dan meninggalkan kehidupan akhirat) karena itu mereka tidak beramal untuk menyambut hari akhirat.",[["وَتَذَرُونَ","And leave"],["ٱلْـَٔاخِرَةَ","the Hereafter"]]],"5573":["(Wajah-wajah pada hari itu) pada hari kiamat (ada yang berseri-seri) tampak cerah dan bercahaya.",[["وُجُوهٌۭ","Faces"],["يَوْمَئِذٍۢ","that Day"],["نَّاضِرَةٌ","(will be) radiant"]]],"5574":["(Kepada Rabbnyalah mereka melihat) mereka akan melihat Allah swt. di akhirat.",[["إِلَىٰ","Towards"],["رَبِّهَا","their Lord"],["نَاظِرَةٌۭ","looking"]]],"5575":["(Dan wajah-wajah pada hari itu ada yang muram) tampak gelap dan sangat muram.",[["وَوُجُوهٌۭ","And faces"],["يَوْمَئِذٍۭ","that Day"],["بَاسِرَةٌۭ","(will be) distorted"]]],"5576":["(Mereka yakin) merasa yakin (bahwa akan ditimpakan kepadanya malapetaka yang amat dahsyat) bencana yang sangat besar, yang dapat meremukkan tulang-tulang punggung.",[["تَظُنُّ","Thinking"],["أَن","that"],["يُفْعَلَ","will be done"],["بِهَا","to them"],["فَاقِرَةٌۭ","backbreaking"]]],"5577":["(Sekali-kali jangan) bermakna Alaa, yakni ingatlah. (Apabila telah sampai) napas (pada tenggorokan) atau kerongkongan.",[["كَلَّآ","No"],["إِذَا","When"],["بَلَغَتِ","it reaches"],["ٱلتَّرَاقِىَ","the collar bones"]]],"5578":["(Dan dikatakan) kepadanya oleh yang ada di sekitarnya: (\"Siapakah yang dapat mengobati?\") hingga sembuh.",[["وَقِيلَ","And it is said"],["مَنْ ۜ","Who"],["رَاقٍۢ","(will) cure"]]],"5579":["(Dan dia yakin) yakni orang yang napasnya telah sampai di tenggorokan itu merasa yakin akan hal tersebut (bahwa sesungguhnya itulah waktu perpisahan) yaitu meninggalkan dunia.",[["وَظَنَّ","And he is certain"],["أَنَّهُ","that it"],["ٱلْفِرَاقُ","(is) the parting"]]],"5580":["(Dan bertaut betis dengan betis) betis kanan dan betis kirinya bertaut ketika ia mati. Atau makna yang dimaksud ialah saling bertaut antara sakit berpisah dengan dunia dan sakit menghadapi akhirat di dalam dirinya.",[["وَٱلْتَفَّتِ","And is wound"],["ٱلسَّاقُ","the leg"],["بِٱلسَّاقِ","about the leg"]]],"5581":["(Kepada Rabbmulah pada hari itu mereka dihalau) atau kepada-Nyalah mereka digiring; hal ini menunjukkan tentang adanya Amil dalam lafal Idzaa. Lengkapnya, apabila nyawa telah sampai di tenggorokan, maka ia akan dihalau menuju kepada keputusan Rabbnya.",[["إِلَىٰ","To"],["رَبِّكَ","your Lord"],["يَوْمَئِذٍ","that Day"],["ٱلْمَسَاقُ","(will be) the driving"]]],"5582":["(Dan ia tidak mau membenarkan) yaitu manusia (dan tidak mau mengerjakan salat) ia tidak mau mempercayai rasul dan tidak pula mau mendirikan salat.",[["فَلَا","And not"],["صَدَّقَ","he accepted (the) truth"],["وَلَا","and not"],["صَلَّىٰ","he prayed"]]],"5583":["(Tetapi ia mendustakan) Alquran (dan berpaling) dari iman.",[["وَلَـٰكِن","But"],["كَذَّبَ","he denied"],["وَتَوَلَّىٰ","and turned away"]]],"5584":["(Kemudian ia pergi kepada ahlinya dengan berlagak) dengan langkah-langkah yang sombong.",[["ثُمَّ","Then"],["ذَهَبَ","he went"],["إِلَىٰٓ","to"],["أَهْلِهِۦ","his family"],["يَتَمَطَّىٰٓ","swaggering"]]],"5585":["(Kecelakaanlah bagimu) di dalam ungkapan kalimat ini terkandung Iltifat dari Ghaibah, kalimat ini adalah Isim Fi'il, sedangkan huruf Lamnya menunjukkan makna Tabyin, artinya: dia menyerahkan kepadamu apa-apa yang tidak kamu sukai (maka kecelakaanlah bagimu) yakni dia lebih utama untuk diprioritaskan olehmu.",[["أَوْلَىٰ","Woe"],["لَكَ","to you"],["فَأَوْلَىٰ","and woe"]]],"5586":["(Kemudian kecelakaanlah bagimu dan kecelakaanlah bagimu) mengukuhkan makna ayat di atas.",[["ثُمَّ","Then"],["أَوْلَىٰ","woe"],["لَكَ","to you"],["فَأَوْلَىٰٓ","and woe"]]],"5587":["(Apakah manusia mengira) menduga (bahwa ia akan dibiarkan begitu saja) tanpa dibebani dengan syariat-syariat; janganlah ia menduga seperti itu.",[["أَيَحْسَبُ","Does think"],["ٱلْإِنسَـٰنُ","man"],["أَن","that"],["يُتْرَكَ","he will be left"],["سُدًى","neglected"]]],"5588":["(Bukankah dia dahulu) sebelum itu (setetes mani yang ditumpahkan) ke dalam rahim; lafal Yumnaa dapat pula dibaca Tumnaa.",[["أَلَمْ","Was not"],["يَكُ","he"],["نُطْفَةًۭ","a semen-drop"],["مِّن","of"],["مَّنِىٍّۢ","semen"],["يُمْنَىٰ","emitted"]]],"5589":["(Kemudian adalah) mani itu (menjadi segumpal darah lalu Allah menciptakannya) dari air mani itu menjadi manusia (dan menyempurnakannya) melengkapinya dengan anggota-anggota tubuh yang diperlukannya.",[["ثُمَّ","Then"],["كَانَ","he was"],["عَلَقَةًۭ","a clinging substance"],["فَخَلَقَ","then He created"],["فَسَوَّىٰ","and proportioned"]]],"5590":["(Lalu Allah menjadikan daripadanya) dari air mani yang telah menjadi segumpal darah, segumpal daging (sepasang) dua jenis (laki-laki dan perempuan) terkadang menjadi satu dan terkadang tersendiri.",[["فَجَعَلَ","Then made"],["مِنْهُ","of him"],["ٱلزَّوْجَيْنِ","two kinds"],["ٱلذَّكَرَ","(the) male"],["وَٱلْأُنثَىٰٓ","and the female"]]],"5591":["(Bukankah yang berbuat demikian) yang mengerjakan kesemuanya itu (berkuasa pula menghidupkan orang mati?) Nabi saw. menjawab, tentu saja dapat.",[["أَلَيْسَ","Is not"],["ذَٰلِكَ","[that]"],["بِقَـٰدِرٍ","(He) Able"],["عَلَىٰٓ","[over]"],["أَن","to"],["يُحْـِۧىَ","give life"],["ٱلْمَوْتَىٰ","(to) the dead"]]],"5592":["(Bukankah) artinya, sesungguhnya (telah datang atas manusia) Nabi Adam (satu waktu dari masa) empat puluh tahun (sedangkan dia belum merupakan) ketika itu (sesuatu yang dapat disebut) maksudnya, Nabi Adam selama empat puluh tahun masih tetap berbentuk tanah dan bukan berarti apa-apa. Atau bila yang dimaksud dengan manusia adalah jenis manusia selain dia, maka yang dimaksud dengan lafal Al-Hiin atau masa ialah masa mengandung, jadi bukan empat puluh tahun.",[["هَلْ","Has"],["أَتَىٰ","(there) come"],["عَلَى","upon"],["ٱلْإِنسَـٰنِ","man"],["حِينٌۭ","a period"],["مِّنَ","of"],["ٱلدَّهْرِ","time"],["لَمْ","not"],["يَكُن","he was"],["شَيْـًۭٔا","a thing"],["مَّذْكُورًا","mentioned"]]],"5593":["(Sesungguhnya Kami telah menciptakan manusia) artinya, jenis manusia (dari setetes mani yang bercampur) yang bercampur dengan indung telur, yaitu air mani laki-laki bercampur menjadi satu dengan air mani perempuan (yang Kami hendak mengujinya) dengan membebankan kewajiban-kewajiban kepadanya; jumlah ayat ini merupakan jumlah Isti`naf yakni kalimat permulaan; atau dianggap sebagai Hal dari lafal yang diperkirakan. Yaitu, Kami bermaksud hendak mengujinya ketika Kami mempersiapkan kejadiannya (karena itu Kami jadikan dia) Kami menjadikan dia dapat (mendengar dan melihat.)",[["إِنَّا","Indeed, We"],["خَلَقْنَا","[We] created"],["ٱلْإِنسَـٰنَ","man"],["مِن","from"],["نُّطْفَةٍ","a semen-drop"],["أَمْشَاجٍۢ","a mixture"],["نَّبْتَلِيهِ","(that) We test him"],["فَجَعَلْنَـٰهُ","so We made (for) him"],["سَمِيعًۢا","hearing"],["بَصِيرًا","and sight"]]],"5594":["(Sesungguhnya Kami telah menunjukinya jalan petunjuk) maksudnya, Kami telah menjelaskan kepadanya jalan hidayah dengan mengutus rasul-rasul kepada manusia (ada yang bersyukur) yaitu menjadi orang mukmin (dan ada pula yang kafir) kedua lafal ini, yakni Syaakiran dan Kafuuran merupakan Haal dari Maf'ul; yakni Kami telah menjelaskan jalan hidayah kepadanya, baik sewaktu ia dalam keadaan bersyukur atau pun sewaktu ia kafir sesuai dengan kepastian Kami. Lafal Immaa di sini menunjukkan rincian tentang keadaan.",[["إِنَّا","Indeed, We"],["هَدَيْنَـٰهُ","guided him"],["ٱلسَّبِيلَ","(to) the way"],["إِمَّا","whether"],["شَاكِرًۭا","(he) be grateful"],["وَإِمَّا","and whether"],["كَفُورًا","(he) be ungrateful"]]],"5595":["(Sesungguhnya Kami menyediakan) telah mempersiapkan (bagi orang-orang kafir rantai) untuk menyeret mereka ke dalam neraka (dan belenggu-belenggu) pada leher mereka dan rantai itu diikatkan kepadanya (serta neraka Sair) yaitu neraka yang apinya menyala-nyala dengan besarnya, tempat mereka diazab.",[["إِنَّآ","Indeed, We"],["أَعْتَدْنَا","[We] have prepared"],["لِلْكَـٰفِرِينَ","for the disbelievers"],["سَلَـٰسِلَا۟","chains"],["وَأَغْلَـٰلًۭا","and shackles"],["وَسَعِيرًا","and a Blazing Fire"]]],"5596":["(Sesungguhnya orang-orang yang berbuat kebaikan) lafal Al-Abraar bentuk jamak dari lafal Barrun atau Baarrun, artinya orang-orang yang taat (mereka minum dari gelas) atau tempat minum, yang berisikan khamar. Maksudnya, mereka meminum khamar. Hal ini diungkapkan dengan memakai nama alat peminumnya. Huruf Min bermakna Tab'idh (yang campurannya) yakni khamar itu dicampur dengan (kafur.)",[["إِنَّ","Indeed"],["ٱلْأَبْرَارَ","the righteous"],["يَشْرَبُونَ","will drink"],["مِن","from"],["كَأْسٍۢ","a cup"],["كَانَ","is"],["مِزَاجُهَا","its mixture"],["كَافُورًا","(of) Kafur"]]],"5597":["(Yaitu mata air) menjadi Badal dari lafal Kaafuur artinya, mata air itu berbau kafur (yang meminum daripadanya) dari mata air itu (hamba-hamba Allah) yakni kekasih-kekasih-Nya (yang mereka dapat mengalirkannya dengan sebaik-baiknya) mereka dapat mengalirkan air dari telaga itu menurut kehendaknya dari tempat-tempat tinggal mereka.",[["عَيْنًۭا","A spring "],["يَشْرَبُ","will drink"],["بِهَا","from it"],["عِبَادُ","(the) slaves"],["ٱللَّهِ","(of) Allah"],["يُفَجِّرُونَهَا","causing it to gush forth"],["تَفْجِيرًۭا","abundantly"]]],"5598":["(Mereka menunaikan nazar) untuk taat kepada Allah (dan takut akan suatu hari yang azabnya merata di mana-mana) menyebar di semua tempat.",[["يُوفُونَ","They fulfill"],["بِٱلنَّذْرِ","the vows"],["وَيَخَافُونَ","and fear"],["يَوْمًۭا","a Day "],["كَانَ","(which) is"],["شَرُّهُۥ","its evil"],["مُسْتَطِيرًۭا","widespread"]]],"5599":["(Dan mereka memberikan makanan yang disukainya) atau yang digemarinya (kepada orang miskin) atau orang fakir (anak yatim) anak yang ayahnya sudah tiada (dan orang yang ditawan) orang yang ditahan karena membela perkara yang hak.",[["وَيُطْعِمُونَ","And they feed"],["ٱلطَّعَامَ","the food"],["عَلَىٰ","in spite of"],["حُبِّهِۦ","love (for) it"],["مِسْكِينًۭا","(to the) needy"],["وَيَتِيمًۭا","and (the) orphan"],["وَأَسِيرًا","and (the) captive"]]],"5600":["(Sesungguhnya kami memberi makanan kepada kalian hanyalah demi karena Allah) demi untuk mengharapkan pahala-Nya (kami tidak menghendaki balasan dari kalian dan tidak pula ucapan terima kasih) berterima kasih atas pemberian makanan itu. Apakah mereka benar-benar mengucapkan demikian ataukah hal itu telah diketahui oleh Allah swt. kemudian Allah memuji mereka. Sesungguhnya dengan masalah ini ada dua pendapat.",[["إِنَّمَا","Only"],["نُطْعِمُكُمْ","we feed you"],["لِوَجْهِ","for (the) Countenance"],["ٱللَّهِ","(of) Allah"],["لَا","Not"],["نُرِيدُ","we desire"],["مِنكُمْ","from you"],["جَزَآءًۭ","any reward"],["وَلَا","and not"],["شُكُورًا","thanks"]]],"5601":["(Sesungguhnya kami takut kepada Rabb kami akan suatu hari yang penuh dengan kemasaman) yaitu muka-muka pada saat itu bermuram durja dan tidak enak dipandang karena kepahitannya (lagi penuh dengan kesulitan) yakni hari itu penuh dengan penderitaan yang sangat parah.",[["إِنَّا","Indeed, we"],["نَخَافُ","fear"],["مِن","from"],["رَّبِّنَا","our Lord"],["يَوْمًا","a Day "],["عَبُوسًۭا","harsh"],["قَمْطَرِيرًۭا","and distressful"]]],"5602":["(Maka Allah memelihara mereka dari kesusahan hari itu, dan memberikan kepada mereka) atau menghadiahkan kepada mereka (kejernihan) yaitu keindahan dan kecemerlangan pada wajah-wajah mereka (dan kegembiraan hati.)",[["فَوَقَىٰهُمُ","But will protect them"],["ٱللَّهُ","Allah"],["شَرَّ","(from the) evil"],["ذَٰلِكَ","(of) that"],["ٱلْيَوْمِ","Day"],["وَلَقَّىٰهُمْ","and will cause them to meet"],["نَضْرَةًۭ","radiance"],["وَسُرُورًۭا","and happiness"]]],"5603":["(Dan Dia memberi balasan kepada mereka karena kesabaran mereka) disebabkan kesabaran mereka dari perbuatan maksiat (surga) yang mereka dimasukkan ke dalamnya (dan sutera) yang menjadi pakaian mereka.",[["وَجَزَىٰهُم","And will reward them"],["بِمَا","because"],["صَبَرُوا۟","they were patient"],["جَنَّةًۭ","(with) a Garden"],["وَحَرِيرًۭا","and silk"]]],"5604":["(Seraya bersandarkan) menjadi Haal atau kata keterangan keadaan dari Isim yang dirafa'kan oleh lafal Udkhiluuha. Lafal Udkhiluuhaa ini keberadaannya diperkirakan (di dalamnya di atas dipan-dipan) atau ranjang-ranjang yang empuk (mereka tidak melihat) tidak menemukan; menjadi Haal yang kedua (di dalamnya matahari dan tidak pula dingin yang bersangatan) maksudnya, di dalam surga mereka tidak merasakan panasnya matahari yang menyengat, dan tidak pula dingin yang mencekam. Tetapi menurut suatu pendapat bahwa lafal Zamhariiran ini artinya bulan. Maknanya, surga tetap terang-benderang sekalipun tanpa matahari dan bulan.",[["مُّتَّكِـِٔينَ","Reclining"],["فِيهَا","therein"],["عَلَى","on"],["ٱلْأَرَآئِكِ ۖ","couches"],["لَا","Not"],["يَرَوْنَ","they will see"],["فِيهَا","therein"],["شَمْسًۭا","sun"],["وَلَا","and not"],["زَمْهَرِيرًۭا","freezing cold"]]],"5605":["(Dan dekatlah) di'athafkan secara Mahall kepada lafal Yarauna (di atas mereka) maksudnya, di antara mereka (naungannya) yaitu naungan pohon-pohon surga (dan buahnya dimudahkan memetiknya semudah-mudahnya) artinya, buah-buahannya didekatkan sehingga dapat dipetik baik oleh orang yang berdiri, atau orang yang duduk, bahkan orang yang sedang berbaring sekalipun.",[["وَدَانِيَةً","And near"],["عَلَيْهِمْ","above them"],["ظِلَـٰلُهَا","(are) its shades"],["وَذُلِّلَتْ","and will hang low"],["قُطُوفُهَا","its cluster of fruits"],["تَذْلِيلًۭا","dangling low"]]],"5606":["(Dan diedarkan kepada mereka) di dalam surga itu (bejana-bejana dari perak dan piala-piala) atau gelas-gelas yang tanpa pengikat (yang bening laksana kaca.)",[["وَيُطَافُ","And will be circulated"],["عَلَيْهِم","among them"],["بِـَٔانِيَةٍۢ","vessels"],["مِّن","of"],["فِضَّةٍۢ","silver"],["وَأَكْوَابٍۢ","and cups"],["كَانَتْ","(that) are"],["قَوَارِيرَا۠","(of) crystal"]]],"5607":["(Yaitu kaca-kaca dari perak) gelas-gelas dan piala-piala itu terbuat dari perak yang bagian dalamnya dapat dilihat dari luar, sehingga tampak bening sebening kaca (yang telah diukur mereka) yakni oleh pelayan-pelayan yang mengedarkannya (dengan sebaik-baiknya) sesuai dengan kecukupan minum orang-orang yang meminumnya, tidak lebih dan tidak pula kurang; cara minum yang demikian itu merupakan cara minum yang paling nikmat.",[["قَوَارِيرَا۟","Crystal-clear"],["مِن","of"],["فِضَّةٍۢ","silver"],["قَدَّرُوهَا","They will determine its"],["تَقْدِيرًۭا","measure"]]],"5608":["(Di dalam surga itu mereka diberi minum segelas) khamar (yang campurannya) atau sesuatu yang dicampurkan ke dalam minuman itu (adalah jahe.)",[["وَيُسْقَوْنَ","And they will be given to drink"],["فِيهَا","therein"],["كَأْسًۭا","a cup "],["كَانَ","is"],["مِزَاجُهَا","its mixture"],["زَنجَبِيلًا","(of) Zanjabil"]]],"5609":["(Yaitu dari mata air) menjadi Badal dari lafal Zanjabiilaa (yang dinamakan salsabil) yaitu air telaga itu rasanya seperti jahe yang sangat disukai oleh orang-orang Arab, dan minuman ini sangat mudah diteguknya.",[["عَيْنًۭا","A spring"],["فِيهَا","therein"],["تُسَمَّىٰ","named"],["سَلْسَبِيلًۭا","Salsabil"]]],"5610":["(Dan mereka dikelilingi oleh pelayan-pelayan muda yang tetap muda) mereka sama sekali tidak akan menjadi tua. (Apabila kamu melihat mereka, kamu akan mengira mereka) karena penampilan mereka yang indah dan jumlah mereka yang menyebar dengan sangat banyaknya (mutiara yang bertaburan) dari untaiannya atau dari tempat asalnya, yang demikian itu lebih indah dibandingkan berada di tempat lain.",[["۞ وَيَطُوفُ","And will circulate"],["عَلَيْهِمْ","among them"],["وِلْدَٰنٌۭ","young boys"],["مُّخَلَّدُونَ","made eternal"],["إِذَا","When"],["رَأَيْتَهُمْ","you see them"],["حَسِبْتَهُمْ","you would think them"],["لُؤْلُؤًۭا","(to be) pearls"],["مَّنثُورًۭا","scattered"]]],"5611":["(Dan apabila kamu melihat di sana) maksudnya, kamu diizinkan untuk melihat surga (niscaya kamu akan melihat) menjadi Jawab Syarath dari Idzaa (berbagai macam kenikmatan) yang tak dapat digambarkan (dan kerajaan yang besar) yang luas dan tak terbatas.",[["وَإِذَا","And when"],["رَأَيْتَ","you look"],["ثَمَّ","then"],["رَأَيْتَ","you will see"],["نَعِيمًۭا","blessings"],["وَمُلْكًۭا","and a kingdom"],["كَبِيرًا","great"]]],"5612":["(Pakaian luar mereka) dinashabkan karena menjadi Zharaf, dan menjadi Khabar dari Mubtada sesudahnya. Menurut qiraat lain dibaca 'Aaliyhim karena dianggap menjadi Mubtada sedangkan lafal sesudahnya menjadi Khabarnya, dan Dhamir Muttashilnya kembali kepada Ma'thuf 'Alaih (dari sutera halus) terbuat daripadanya (yang hijau) dibaca Rafa' yakni Khudhrun (dan sutera tebal) dibaca Jaar yakni Istabraqin artinya, sutera yang tebal. Yakni pakaian bagian luar mereka terbuat dari sutera halus, sedangkan bagian dalamnya terbuat dari sutera tebal. Menurut suatu qiraat dibaca Khudhrin Waistabraqun; menurut qiraat lainnya dibaca Khudhrun Waistabraqun; dan menurut suatu qiraat lain lagi dibaca Khudrin Waistabraqin (dan mereka diberi perhiasan dari gelang-gelang perak) tetapi pada ayat lainnya disebutkan terbuat dari emas; hal ini menunjukkan bahwa mereka diberi perhiasan yang terbuat dari emas dan perak secara berbarengan, tetapi terpisah-pisah (dan Rabb mereka memberikan kepada mereka minuman yang bersih) atau sangat bersih, berbeda dengan keadaan khamar di dunia.",[["عَـٰلِيَهُمْ","Upon them"],["ثِيَابُ","(will be) garments"],["سُندُسٍ","(of) fine silk"],["خُضْرٌۭ","green"],["وَإِسْتَبْرَقٌۭ ۖ","and heavy brocade"],["وَحُلُّوٓا۟","And they will be adorned"],["أَسَاوِرَ","(with) bracelets"],["مِن","of"],["فِضَّةٍۢ","silver"],["وَسَقَىٰهُمْ","and will give them to drink"],["رَبُّهُمْ","their Lord"],["شَرَابًۭا","a drink"],["طَهُورًا","pure"]]],"5613":["(Sesungguhnya ini) yakni kenikmatan ini (adalah balasan untuk kalian, dan usaha kalian adalah disyukuri.)",[["إِنَّ","Indeed"],["هَـٰذَا","this"],["كَانَ","is"],["لَكُمْ","for you"],["جَزَآءًۭ","a reward"],["وَكَانَ","and has been"],["سَعْيُكُم","your effort"],["مَّشْكُورًا","appreciated"]]],"5614":["(Sesungguhnya Kami) lafal Nahnu berfungsi mengukuhkan makna isimnya Inna, atau dianggap sebagai Dhamir Fashal (telah menurunkan Alquran kepadamu dengan berangsur-angsur) ayat ini menjadi Khabar dari Inna, yakni Kami menurunkannya secara berangsur-angsur, tidak sekaligus.",[["إِنَّا","Indeed, We"],["نَحْنُ","[We]"],["نَزَّلْنَا","[We] revealed"],["عَلَيْكَ","to you"],["ٱلْقُرْءَانَ","the Quran"],["تَنزِيلًۭا","progressively"]]],"5615":["(Maka bersabarlah kamu untuk melaksanakan ketetapan Rabbmu) yang dibebankan kepadamu yaitu, menyampaikan risalah-Nya (dan janganlah kamu ikuti, di antara mereka) yakni orang-orang kafir (orang yang berdosa dan orang yang kafir) yang dimaksud adalah Atabah bin Rabi'ah dan Walid bin Mughirah, kedua-duanya telah berkata kepada Nabi saw., \"Kembalilah kamu dari perkara ini dari agama Islam.\" Dan dapat pula diartikan setiap orang yang berdosa dan setiap orang yang kafir; makna yang dimaksud ialah janganlah kamu mengikuti ajakan dan seruan kedua jenis orang tersebut dalam keadaan bagaimana pun, yang seruannya itu mengajakmu kepada perbuatan dosa atau kekafiran.",[["فَٱصْبِرْ","So be patient"],["لِحُكْمِ","for (the) Command"],["رَبِّكَ","(of) your Lord"],["وَلَا","and (do) not"],["تُطِعْ","obey"],["مِنْهُمْ","from them"],["ءَاثِمًا","any sinner"],["أَوْ","or"],["كَفُورًۭا","disbeliever"]]],"5616":["(Dan sebutlah nama Rabbmu) di dalam salatmu (pada waktu pagi dan petang) yakni dalam salat Subuh, Zuhur dan Asar.",[["وَٱذْكُرِ","And remember"],["ٱسْمَ","(the) name"],["رَبِّكَ","(of) your Lord"],["بُكْرَةًۭ","morning"],["وَأَصِيلًۭا","and evening"]]],"5617":["(Dan pada sebagian dari malam, maka sujudlah kamu kepada-Nya) artinya, dirikanlah salat Magrib dan Isyak (dan bertasbihlah kepada-Nya pada bagian yang panjang di malam hari) lakukanlah salat sunat di malam hari, sebagaimana keterangan yang telah kami sebutkan yaitu, sepertiganya atau separohnya atau dua pertiganya.",[["وَمِنَ","And of"],["ٱلَّيْلِ","the night"],["فَٱسْجُدْ","prostrate"],["لَهُۥ","to Him"],["وَسَبِّحْهُ","and glorify Him"],["لَيْلًۭا","a night"],["طَوِيلًا","long"]]],"5618":["(Sesungguhnya mereka menyukai kehidupan dunia) (dan mereka tidak mempedulikan hari yang berat) yaitu hari yang penuh dengan penderitaan, yakni hari kiamat. Maksudnya, mereka tidak beramal untuk menyambut kedatangannya.",[["إِنَّ","Indeed"],["هَـٰٓؤُلَآءِ","these"],["يُحِبُّونَ","love"],["ٱلْعَاجِلَةَ","the immediate"],["وَيَذَرُونَ","and leave"],["وَرَآءَهُمْ","behind them"],["يَوْمًۭا","a Day"],["ثَقِيلًۭا","grave"]]],"5619":["(Kami telah menciptakan mereka dan menguatkan) menjadikan kuat (persendian tubuh mereka) yakni semua anggota tubuh mereka dan sendi-sendinya (apabila Kami menghendaki, Kami sungguh-sungguh mengganti) Kami menjadikan (orang-orang yang serupa dengan mereka) dalam bentuknya sebagai pengganti mereka, seumpamanya Kami membinasakan mereka terlebih dahulu (dengan sebenar-benarnya) lafal ayat ini berfungsi mengukuhkan makna yang terdapat dalam lafal Baddalnaa. lafal Idzaa berkedudukan sama dengan lafal In seperti contoh lain, yaitu: In Yasya' Yudzhibkum, artinya; Seandainya Allah menghendaki niscaya Dia membinasakan kalian. Demikian itu karena pengertian yang terkandung di dalam lafal Idzaa hanya khusus dipakai untuk sesuatu yang pasti akan terjadi, sedangkan di sini Allah swt. tidak menghendaki hal tersebut.",[["نَّحْنُ","We"],["خَلَقْنَـٰهُمْ","created them"],["وَشَدَدْنَآ","and We strengthened"],["أَسْرَهُمْ ۖ","their forms"],["وَإِذَا","and when"],["شِئْنَا","We will"],["بَدَّلْنَآ","We can change"],["أَمْثَـٰلَهُمْ","their likeness[es]"],["تَبْدِيلًا","(with) a change"]]],"5620":["(Sesungguhnya ini) surah ini (adalah suatu peringatan) suatu nasihat dan pelajaran bagi makhluk (maka barang siapa menghendaki niscaya dia mengambil jalan kepada Rabbnya) yakni jalan yang dapat menyampaikan dia kepada-Nya, yaitu melalui ketaatan.",[["إِنَّ","Indeed"],["هَـٰذِهِۦ","this"],["تَذْكِرَةٌۭ ۖ","(is) a reminder"],["فَمَن","so whoever"],["شَآءَ","wills"],["ٱتَّخَذَ","let him take"],["إِلَىٰ","to"],["رَبِّهِۦ","his Lord"],["سَبِيلًۭا","a way"]]],"5621":["(Dan kalian tidak menghendaki) dapat dibaca Tasyaa-uuna dan Yasyaa-uuna, kalau dibaca Yasyaa-uuna artinya, dan mereka tidak menghendaki untuk mengambil jalan kepada Rabbnya dengan mengerjakan ketaatan (kecuali bila dikehendaki Allah) hal tersebut. (Sesungguhnya Allah adalah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["وَمَا","And not"],["تَشَآءُونَ","you will"],["إِلَّآ","except"],["أَن","that"],["يَشَآءَ","wills"],["ٱللَّهُ ۚ","Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["كَانَ","is"],["عَلِيمًا","All-Knower"],["حَكِيمًۭا","All-Wise"]]],"5622":["(Dia memasukkan siapa yang dikehendaki-Nya ke dalam rahmat-Nya) yakni surga-Nya, mereka adalah orang-orang yang beriman. (Dan bagi orang-orang lalim) dinashabkan oleh Fi'il atau kata kerja yang keberadaannya diperkirakan, lengkapnya, Dia telah menyediakan bagi mereka. Pengertian ini disimpulkan dari firman berikutnya (disediakan-Nya azab yang pedih) azab yang menyakitkan; mereka adalah orang-orang kafir.",[["يُدْخِلُ","He admits"],["مَن","whom"],["يَشَآءُ","He wills"],["فِى","into"],["رَحْمَتِهِۦ ۚ","His mercy"],["وَٱلظَّـٰلِمِينَ","but (for) the wrongdoers"],["أَعَدَّ","He has prepared"],["لَهُمْ","for them"],["عَذَابًا","a punishment"],["أَلِيمًۢا","painful"]]],"5623":["(Demi angin yang bertiup sepoi-sepoi) yang bertiup secara beruntun bagaikan beruntunnya susunan rambut kuda yang satu sama lainnya saling beriring-iringan. Dinashabkan karena menjadi Haal atau kata keterangan keadaan.",[["وَٱلْمُرْسَلَـٰتِ","By the ones sent forth"],["عُرْفًۭا","one after another"]]],"5624":["(Dan demi angin yang bertiup dengan kencang) yang bertiup sangat kencang.",[["فَٱلْعَـٰصِفَـٰتِ","And the winds that blow"],["عَصْفًۭا","violently"]]],"5625":["(Dan demi angin yang menyebarkan rahmat) yaitu angin yang menyebarkan hujan.",[["وَٱلنَّـٰشِرَٰتِ","And the ones that scatter"],["نَشْرًۭا","far and wide"]]],"5626":["(Dan demi yang membedakan sejelas-jelasnya) maksudnya, demi ayat-ayat Alquran yang membedakan antara perkara yang hak dan perkara yang batil, serta yang membedakan antara perkara yang halal dan perkara yang haram.",[["فَٱلْفَـٰرِقَـٰتِ","And those who separate"],["فَرْقًۭا","(by the) Criterion"]]],"5627":["(Dan demi malaikat-malaikat yang menyampaikan peringatan) yakni malaikat-malaikat yang turun untuk menyampaikan wahyu kepada para nabi dan para rasul supaya wahyu tersebut disampaikan kepada umat-umat manusia.",[["فَٱلْمُلْقِيَـٰتِ","And those who bring down"],["ذِكْرًا","(the) Reminder"]]],"5628":["(Untuk menolak alasan-alasan atau memberi peringatan-peringatan) dari Allah swt. Menurut suatu qiraat dibaca 'Udzuran dan Nudzuran, dengan memakai harakat damah pada kedua huruf Dzalnya.",[["عُذْرًا","(As) justification"],["أَوْ","or"],["نُذْرًا","warning"]]],"5629":["(Sesungguhnya apa yang dijanjikan kepada kalian itu) hai orang-orang kafir Mekah, yaitu mengenai hari berbangkit dan azab yang akan menimpa kalian (pasti terjadi) pasti akan terjadi.",[["إِنَّمَا","Indeed, what"],["تُوعَدُونَ","you are promised"],["لَوَٰقِعٌۭ","will surely occur"]]],"5630":["(Maka apabila bintang-bintang telah dihapuskan) dihilangkan cahayanya.",[["فَإِذَا","So when"],["ٱلنُّجُومُ","the stars"],["طُمِسَتْ","are obliterated"]]],"5631":["(Dan apabila langit dibelah) atau menjadi terbelah.",[["وَإِذَا","And when"],["ٱلسَّمَآءُ","the heaven"],["فُرِجَتْ","is cleft asunder"]]],"5632":["(Dan apabila gunung-gunung telah dihancurkan) diletuskan hingga menjadi debu yang beterbangan.",[["وَإِذَا","And when"],["ٱلْجِبَالُ","the mountains"],["نُسِفَتْ","are blown away"]]],"5633":["(Dan apabila rasul-rasul telah dikumpulkan di dalam suatu waktu) memakai Wau dan Hamzah sebagai Badal daripadanya yaitu, pada satu ketika rasul-rasul akan dikumpulkan.",[["وَإِذَا","And when"],["ٱلرُّسُلُ","the Messengers"],["أُقِّتَتْ","are gathered to their appointed time"]]],"5634":["(Sampai hari kapankah) yakni hari yang besar (ditangguhkan) persaksian terhadap umat-umat mereka tentang penyampaian mereka?",[["لِأَىِّ","For what"],["يَوْمٍ","Day"],["أُجِّلَتْ","are (these) postponed"]]],"5635":["(Sampai hari keputusan) di antara semua makhluk; dari pengertian ayat inilah diambil kesimpulan bagi Jawab lafal Idzaa yakni, terjadilah keputusan di antara semua makhluk.",[["لِيَوْمِ","For (the) Day"],["ٱلْفَصْلِ","(of) Judgment"]]],"5636":["(Dan tahukah kamu apakah hari keputusan itu?) ayat ini menggambarkan tentang kengerian yang terdapat di dalam hari tersebut.",[["وَمَآ","And what"],["أَدْرَىٰكَ","will make you know"],["مَا","what"],["يَوْمُ","(is the) Day"],["ٱلْفَصْلِ","(of) the Judgment"]]],"5637":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan) ayat ini mengandung makna ancaman bagi mereka yang tidak mempercayainya.",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5638":["(Bukankah Kami telah membinasakan orang-orang yang dahulu?) disebabkan kedustaan mereka.",[["أَلَمْ","Did not"],["نُهْلِكِ","We destroy"],["ٱلْأَوَّلِينَ","the former (people)"]]],"5639":["(Lalu Kami iringi mereka dengan orang-orang yang datang kemudian) di antara orang-orang yang mendustakan seperti orang-orang kafir Mekah, maka Kami kelak akan membinasakan mereka pula.",[["ثُمَّ","Then"],["نُتْبِعُهُمُ","We follow them up"],["ٱلْـَٔاخِرِينَ","(with) the later ones"]]],"5640":["(Demikianlah) sebagaimana Kami lakukan terhadap orang-orang yang mendustakan (Kami berbuat terhadap orang-orang yang berdosa) artinya, Kami akan melakukan hal yang sama terhadap orang-orang yang berdosa yang kelak akan datang, yaitu Kami pasti akan membinasakan mereka.",[["كَذَٰلِكَ","Thus"],["نَفْعَلُ","We deal"],["بِٱلْمُجْرِمِينَ","with the criminals"]]],"5641":["(Kecelakaan besarlah pada hari itu bagi orang-orang yang mendustakan) sebagai pengukuh terhadap ayat sebelumnya.",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5642":["(Bukankah Kami menciptakan kalian dari air yang hina?) yang lemah, yaitu air mani.",[["أَلَمْ","Did not"],["نَخْلُقكُّم","We create you"],["مِّن","from"],["مَّآءٍۢ","a water"],["مَّهِينٍۢ","despicable"]]],"5643":["(Kemudian Kami letakkan dia dalam tempat yang kokoh) tempat yang terpelihara, yaitu dalam rahim.",[["فَجَعَلْنَـٰهُ","Then We placed it"],["فِى","in"],["قَرَارٍۢ","an abode"],["مَّكِينٍ","safe"]]],"5644":["(Sampai waktu yang ditentukan) yaitu sampai waktu kelahirannya.",[["إِلَىٰ","For"],["قَدَرٍۢ","a period"],["مَّعْلُومٍۢ","known"]]],"5645":["(Lalu Kami tentukan) waktu tersebut (maka sebaik-baik yang menentukan) adalah Kami.",[["فَقَدَرْنَا","So We measured"],["فَنِعْمَ","and Best"],["ٱلْقَـٰدِرُونَ","(are We to) measure"]]],"5646":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5647":["(Bukankah Kami menjadikan bumi tempat berkumpul) lafal Kifaatan adalah Mashdar dari lafal Kafata yang artinya berkumpul atau tempat untuk berkumpul.",[["أَلَمْ","Have not"],["نَجْعَلِ","We made"],["ٱلْأَرْضَ","the earth"],["كِفَاتًا","a receptacle"]]],"5648":["(Orang-orang hidup) pada permukaannya (dan orang-orang mati) yang ada pada perutnya.",[["أَحْيَآءًۭ","(For the) living"],["وَأَمْوَٰتًۭا","and (the) dead"]]],"5649":["(Dan Kami jadikan padanya gunung-gunung yang tinggi) gunung-gunung yang menjulang tinggi (dan Kami beri minum kalian dengan air yang tawar) air yang segar dan tawar.",[["وَجَعَلْنَا","And We made"],["فِيهَا","therein"],["رَوَٰسِىَ","firmly set mountains"],["شَـٰمِخَـٰتٍۢ","lofty"],["وَأَسْقَيْنَـٰكُم","and We gave you to drink"],["مَّآءًۭ","water "],["فُرَاتًۭا","sweet"]]],"5650":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan) kemudian pada hari kiamat dikatakan kepada orang-orang yang mendustakan:",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5651":["(\"Pergilah kamu sekalian mendapatkan azab yang dahulunya kalian mendustakannya.)",[["ٱنطَلِقُوٓا۟","Proceed"],["إِلَىٰ","to"],["مَا","what"],["كُنتُم","you used to"],["بِهِۦ","in it"],["تُكَذِّبُونَ","deny"]]],"5652":["(Pergilah kalian mendapatkan naungan yang mempunyai tiga cabang) yang dimaksud adalah asap neraka Jahanam, apabila membubung terbagi menjadi tiga, karena sangat besarnya.",[["ٱنطَلِقُوٓا۟","Proceed"],["إِلَىٰ","to"],["ظِلٍّۢ","a shadow"],["ذِى","having"],["ثَلَـٰثِ","three"],["شُعَبٍۢ","columns"]]],"5653":["(Yang tidak melindungi) asap itu tidak dapat menaungi mereka dari panas hari itu (dan tiada bermanfaat) barang sedikit pun bagi mereka (untuk menolak api\") yakni api neraka.",[["لَّا","No"],["ظَلِيلٍۢ","cool shade"],["وَلَا","and not"],["يُغْنِى","availing"],["مِنَ","against"],["ٱللَّهَبِ","the flame"]]],"5654":["(Sesungguhnya neraka itu) maksudnya, api neraka itu (melontarkan bunga api) memercikkan bunga api (sebesar istana) yakni besar dan tingginya bagaikan istana.",[["إِنَّهَا","Indeed, it"],["تَرْمِى","throws up"],["بِشَرَرٍۢ","sparks"],["كَٱلْقَصْرِ","as the fortress"]]],"5655":["(Seolah-olah ia iringan unta) lafal Jimaalaatun bentuk jamak dari lafal Jimaalah, juga lafal Jimaalah ini adalah bentuk jamak dari lafal Jamalun. Menurut suatu qiraat dibaca Jimaalatun (yang kuning kehitam-hitaman) perwujudan dan warnanya. Di dalam sebuah hadis disebutkan: \"Manusia yang paling buruk ialah yang hitam bagaikan aspal.\" Orang-orang Arab menamakan unta yang berwarna hitam unta kuning, demikian itu karena warna hitamnya dicampuri dengan warna kuning. Tetapi menurut pendapat yang lain bahwa arti lafal Shufrun dalam ayat ini adalah hitam, karena alasan yang telah disebutkan tadi, tetapi menurut pendapat lainnya lagi bermakna kuning. Lafal Syararun adalah bentuk jamak dari lafal Syaraarah artinya percikan atau bunga api; dan lafal Al-Qiiru/Al-Qaaru artinya belakin atau aspal.",[["كَأَنَّهُۥ","As if they (were)"],["جِمَـٰلَتٌۭ","camels"],["صُفْرٌۭ","yellow"]]],"5656":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5657":["(Ini) yakni hari kiamat ini (adalah hari yang mereka tidak dapat berbicara) sepatah kata pun.",[["هَـٰذَا","This"],["يَوْمُ","(is) a Day"],["لَا","not"],["يَنطِقُونَ","they will speak"]]],"5658":["(Dan tidak diizinkan kepada mereka) mengemukakan alasannya (sehingga mereka dapat mengemukakan alasannya) lafal Faya'tadziruuna di'athafkan kepada lafal Yu'dzanu tanpa ada penyebab yang mengaitkannya, tetapi tetap termasuk ke dalam pengertian negatif. Artinya tiada berkenan bagi mereka untuk berbicara, maka tiada alasan bagi mereka.",[["وَلَا","And not"],["يُؤْذَنُ","will it be permitted"],["لَهُمْ","for them"],["فَيَعْتَذِرُونَ","to make excuses"]]],"5659":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5660":["(Ini adalah hari keputusan; Kami mengumpulkan kalian) hai orang-orang yang mendustakan dari kalangan umat ini, yakni umat Nabi Muhammad (dan orang-orang yang terdahulu) dari kalangan orang-orang yang mendustakan sebelum kalian; lalu kalian semuanya akan dihisab kemudian diazab.",[["هَـٰذَا","This"],["يَوْمُ","(is the) Day"],["ٱلْفَصْلِ ۖ","(of) Judgment"],["جَمَعْنَـٰكُمْ","We have gathered you"],["وَٱلْأَوَّلِينَ","and the former (people)"]]],"5661":["(Jika kalian mempunyai tipu daya) tipu muslihat untuk melindungi diri kalian dari azab (maka lakukanlah tipu daya kalian itu terhadap-Ku) perbuatlah tipu daya kalian itu.",[["فَإِن","So if"],["كَانَ","is"],["لَكُمْ","for you"],["كَيْدٌۭ","a plan"],["فَكِيدُونِ","then plan against Me"]]],"5662":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5663":["(Sesungguhnya orang-orang yang bertakwa berada dalam naungan) berada dalam naungan pohon-pohon, yang pada hari itu bukan main panasnya, padahal tiada matahari (dan mata air-mata air) yang mengalir.",[["إِنَّ","Indeed"],["ٱلْمُتَّقِينَ","the righteous"],["فِى","(will be) in"],["ظِلَـٰلٍۢ","shades"],["وَعُيُونٍۢ","and springs"]]],"5664":["(Dan mendapat buah-buahan dari jenis-jenis yang mereka sukai) di dalam ungkapan ayat ini terkandung pengertian bahwa makanan dan minuman di surga sesuai dengan selera penghuninya masing-masing. Berbeda dengan keadaan di dunia, makanan dan minuman sesuai dengan kemampuan masing-masing. Kemudian dikatakan kepada orang-orang yang bertakwa itu:",[["وَفَوَٰكِهَ","And fruits"],["مِمَّا","from what"],["يَشْتَهُونَ","they desire"]]],"5665":["(\"Makan dan minumlah kalian dengan enak) lafal Haniian merupakan Haal atau kata keterangan keadaan, yakni makan dan minumlah dengan seenak-enaknya (karena apa yang telah kalian kerjakan\") berupa ketaatan.",[["كُلُوا۟","Eat"],["وَٱشْرَبُوا۟","and drink"],["هَنِيٓـًٔۢا","(in) satisfaction"],["بِمَا","for what"],["كُنتُمْ","you used to"],["تَعْمَلُونَ","do"]]],"5666":["(Sesungguhnya demikianlah Kami) sebagaimana Kami memberikan balasan kepada orang-orang yang takwa (memberikan balasan kepada orang-orang yang berbuat baik.)",[["إِنَّا","Indeed, We"],["كَذَٰلِكَ","thus"],["نَجْزِى","reward"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"5667":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5668":["(\"Makanlah dan bersenang-senanglah kamu sekalian) khithab atau perintah ini ditujukan kepada orang-orang kafir di dunia (dalam waktu yang pendek) waktu yang singkat; yang batasnya adalah kematian mereka. Di dalam ungkapan ini terkandung makna ancaman terhadap mereka (sesungguhnya kalian adalah orang-orang yang berdosa.\")",[["كُلُوا۟","Eat"],["وَتَمَتَّعُوا۟","and enjoy yourselves"],["قَلِيلًا","a little"],["إِنَّكُم","indeed, you"],["مُّجْرِمُونَ","(are) criminals"]]],"5669":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5670":["(Dan apabila dikatakan kepada mereka, \"Rukuklah\") yakni salatlah kalian (niscaya mereka tidak mau rukuk) tidak mau salat.",[["وَإِذَا","And when"],["قِيلَ","it is said"],["لَهُمُ","to them"],["ٱرْكَعُوا۟","Bow"],["لَا","not"],["يَرْكَعُونَ","they bow"]]],"5671":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5672":["(Maka kepada perkataan apakah sesudah ini) sesudah Alquran ini (mereka akan beriman?) maksudnya, tidak mungkin mereka akan beriman kepada kitab-kitab Allah lainnya sesudah mereka mendustakannya, karena di dalam Alquran terkandung unsur I'jaz atau mukjizat yang tidak terdapat pada kitab-kitab Allah lainnya.",[["فَبِأَىِّ","Then in what"],["حَدِيثٍۭ","statement"],["بَعْدَهُۥ","after it"],["يُؤْمِنُونَ","will they believe"]]]});